-- Adds preparation steps imported from BigQuery/Dataiku.
-- Run after database/supabase_schema.sql and database/supabase_seed_data.sql.

begin;

alter table fact_recette_base add column if not exists etapes text default '';

update fact_recette_base set etapes = '[''Préparation Préparation : - Repos : - Cuisson : -'', ''Étape 1 Épluchez l’ail et les oignons. Coupez-les en petits morceaux. Égouttez les champignons.\nÉtape 2 Dans votre Cookeo, faites roussir la viande et les lardons avec le morceau de beurre sur le mode « dorer » / 3 min (préchauffage inclus), en remuant avec une cuillère en bois.\nÉtape 3 Ajoutez les oignons et les champignons. Saupoudrez de farine et mélangez. Faites dorer sur le mode « dorer » /  3 min (préchauffage inclus), en remuant avec une cuillère en bois.\nÉtape 4 Mouillez avec le vin rouge : il doit recouvrir la viande. Salez et poivrez. Ajoutez l’ail et le bouquet garni.\nÉtape 5 Fermez le Cookeo et lancez la cuisson sur le mode « cuisson sous pression » / 35 min.'']' where recette_id = '0eac620cf8abfecc05b4592613bb0bf1';
update fact_recette_base set etapes = '[''Préparation 10 min Préparation : 5 min Repos : - Cuisson : 5 min'', "Étape 1 Faire cuire les saucisses au four micro-ondes, ou à la casserole avec de l''eau, pendant 3 min.\nÉtape 2 Pendant ce temps, mettre les pains dans le grille-pain pendant 2 min.\nÉtape 3 Déposer les saucisses dans les pains, puis verser du sweet relish sur les saucisses.\nÉtape 4 Ajouter la moutarde et le ketchup à volonter."]' where recette_id = 'b1ddc26e37b4ca7eada41ad390ee2087';
update fact_recette_base set etapes = '[''Préparation 10 min Préparation : - Repos : - Cuisson : 10 min'', ''Étape 1 Faire fondre la noix de beurre dans une poêle. Déposer les noix et les faire dorer légèrement sur chaque côté.\nÉtape 2 Servir immédiatement avec une toute petite pincée de poivre et une de sel de Guérande.'']' where recette_id = '60cf84845f55c2a199d7808152f76bd1';
update fact_recette_base set etapes = '[''Préparation 10 min Préparation : 5 min Repos : - Cuisson : 5 min'', "Étape 1 Faites revenir les oignons à feux doux.\nÉtape 2 Ajouter les steaks.\nÉtape 3 Une fois saisi, poser une tranche de cheddar sur le steak et laisser fondre.\nÉtape 4 Une fois cuit, déposer le steak et le fromage sur une des tranches du pain que vous aurez auparavant tartinée d''un mélange de ketchup et de moutarde.\nÉtape 5 Ajouter la salade et de petites rondelles de tomates.\nÉtape 6 Vous pouvez maintenant recouvrir la préparation de l''autre tranche (avec ketchup et moutarde)"]' where recette_id = '1366f45e2d19195876ca3c6076855fdc';
update fact_recette_base set etapes = '[''Préparation 12 min Préparation : 10 min Repos : - Cuisson : 2 min'', "Étape 1 Dans un saladier mettre la farine puis les oeufs entiers et l''eau (ou de la biere c''est un peu moin sec au finale).\nÉtape 2 Ensuite melanger le tout avec un fouet (l''ideal c''est d''avoir un robot qui melange tout seul!!)jusqu''à obtiention d''une pate homogene sans grumeau et pas liquide surtout!\nÉtape 3 Faite chauffer une grande cassserole avec de l''eau et un kub or et des que l''eau est chaude vous pouver y verser la pate sois avec la rape speciale à spaetle ou sinon faut couper la pate sur une planche en petit morceau long de 2 ou 3cm et large de 0.5mm à vous de voir comment vous aimez.\nÉtape 4 Attendre que ca remonte à la surface et les sortir avec un ecumoire puis les mettre dans une passoire et continuer jusqu''à ce que vous n''ayez plus de pate.\nÉtape 5 Ensuite vous pouvez les griller dans une poele avec un peu d''huile ou les servir comme ca."]' where recette_id = '143641b4881dfe07a08e69d8f2515141';
update fact_recette_base set etapes = '[''Préparation 15 min Préparation : 10 min Repos : - Cuisson : 5 min'', "Étape 1 Décortiquer les crevettes. Les faire revenir très rapidement dans l''huile d''olive en les saupoudrant de curry.\nÉtape 2 Ajouter la crème et mélanger le tout.\nÉtape 3 Servir immédiatement avec du riz thaï."]' where recette_id = '040ace30513cc49ca4dbd0279f27fe49';
update fact_recette_base set etapes = '[''Préparation 15 min Préparation : 10 min Repos : - Cuisson : 5 min'', ''Étape 1 Beurrez les 8 tranches de pain de mie sur une seule face. Posez 1 tranche de fromage sur chaque tranche de pain de mie. Posez 1 tranche de jambon plié en deux sur 4 tranches de pain de mie. Recouvrez avec les autres tartines (face non beurrée au dessus).\nÉtape 2 Dans un bol mélanger le fromage râpé avec le lait, le sel, le poivre et la muscade.\nÉtape 3 Répartissez le mélange sur les croque-monsieur.\nÉtape 4 Placez sur une plaque au four sous le grill pendant 10 mn.'']' where recette_id = 'fecf622ca882ae30dd85f39a061be0fb';
update fact_recette_base set etapes = '[''Préparation 15 min Préparation : 10 min Repos : - Cuisson : 5 min'', "Étape 1 Détailler les oignons en lamelles et les poivrons en lanières. Faire revenir dans l''huile d''olive quelques minutes.\nÉtape 2 Ciseler les feuilles de laitue en lanières et coupre les tomates en dés.\nÉtape 3 Couper le gigot d''agneau en fines lamelles et les faire cuire à feu vif pendant environ 5 minutes.\nÉtape 4 Réchauffer les petits pains au four puis les couper en 2 sur un tiers de leur longueur.\nÉtape 5 Répartir dans chaque pain : salade, tomates, mélange oignons/poivrons et viande.\nÉtape 6 Terminer avec un mélange de crème, ciboulette, menthe, sel et poivre.\nÉtape 7 Servir immédiatement."]' where recette_id = 'e057897553b97e96aef3d0258f129f99';
update fact_recette_base set etapes = '[''Préparation 15 min Préparation : 10 min Repos : - Cuisson : 5 min'', "Étape 1 Hacher le jambon.\nÉtape 2 Malaxer la farine avec l''huile, l''oeuf et le sel puis verser l''eau petit à petit. La pâte doit être fluide.\nÉtape 3 Laisser reposer 1 heure puis les cuire dans une poêle bien chaude légèrement graissée.\nÉtape 4 Retourner la crêpe et casser un oeuf dessus. Ajouter l''équivalent d''1/2 tranche de jambon et 10 g de gruyère.\nÉtape 5 Lorsque le blanc d''oeuf est cuit, repliez les côtés de la crêpes vers le centre. Saler, poivrer et servir."]' where recette_id = 'bbf074f421304bb22790a70c381b75b1';
update fact_recette_base set etapes = '[''Préparation 15 min Préparation : 10 min Repos : - Cuisson : 5 min'', ''Étape 1 Faire revenir les noix de St Jacques salées, poivrées 1 à 2 minutes de chaque côtés.\nÉtape 2 Pendant ce temps, chauffer la crème fraîche avec du curry dedans.\nÉtape 3 Ajouter la crème-curry aux noix de St Jacques et laisser 1 à 2 minutes.\nÉtape 4 Servir avec des tagliatelles fraîches ou des spaghetti frais.'']' where recette_id = '74d30020f351cb9907b7cd9654f3354a';
update fact_recette_base set etapes = '[''Préparation 15 min Préparation : 15 min Repos : - Cuisson : -'', "Étape 1 Retirer les arêtes éventuelles à l''aide d''une pince à épiler.\nÉtape 2 Essuyer le saumon avec du papier absorbant.\nÉtape 3 Enduire le poisson du mélange sel + sucre + poivre.\nÉtape 4 Dans un grand plat, mettre une grande feuille de film transparent. Poser le saumon coté peau en dessous, mettre de l''aneth sur le coté sans peau (s''il y a 2 pavés, les empiler l''un sur l''autre en remettant de l’aneth au dessus). Fermer la « papillote » bien serrée.\nÉtape 5 Poser un poids lourd sur le saumon (boite de pois chiches ou autre). Laisser mariner 48 h au frigo, en retournant le poisson tous les jours (jeter l’eau rendue).\nÉtape 6 Le jour j, essuyer le saumon avec du papier absorbant pour ôter le sel (ne pas le rincer sous l’eau!) puis découper le saumon en fines lamelles (comme un carpaccio).\nÉtape 7 Déguster nature avec du citron ou bien une sauce appropriée.\nÉtape 8 Lorsque je ne fais pas de sauce, je rajoute de l’aneth sur le poisson une fois qu’il est en lamelles.\nÉtape 9 Sauce : faire une mayonnaise avec...\nÉtape 10 - 3-4 cuillères à soupe de moutarde douce\nÉtape 11 - 1 cuillère à soupe de vin rouge\nÉtape 12 - 1 cuillère à soupe de sucre en poudre\nÉtape 13 - 1/3 cuillère à café de sel\nÉtape 14 - 3 cuillères à soupe d’huile (excepté l’huile d’olive)\nÉtape 15 Une fois la sauce faite, incorporer 3 cuillères à soupe d’aneth."]' where recette_id = '3802f1f8e7ef792c99746a2aa5ed273c';
update fact_recette_base set etapes = '[''Préparation 15 min Préparation : 5 min Repos : - Cuisson : 10 min'', "Étape 1 Faire revenir les escalopes dans le beurre jusqu''à ce qu''elles soient pratiquement cuites.\nÉtape 2 Saler, poivrer, ajouter la crème et remuer.\nÉtape 3 Mettre les champignons et le persil.\nÉtape 4 Laisser cuire encore 2-3 mn."]' where recette_id = 'f91cdf523b87b092df7ffbb0747e0d37';
update fact_recette_base set etapes = '[''Préparation 17 min Préparation : 10 min Repos : - Cuisson : 7 min'', "Étape 1 Éplucher et émincer finement l''oignon.\nÉtape 2 Faire fondre le beurre avec l''huile dans une poêle.\nÉtape 3 Verser l''oignon émincé et laisser cuire à feu vif en remuant souvent jusqu''à ce que l''oignon commence à dorer.\nÉtape 4 Verser alors 1/3 de verre d''eau et laisser mijoter à feu moyen jusqu''à ce que l''eau se soit évaporée. L''oignon est alors brun et confit, saler au goût et réserver.\nÉtape 5 Vider la poêle des oignons sans la nettoyer et poser le thon dans la poêle chaude, laisser cuire à feu moyen environ 5 minutes. Attention le thon ne doit pas être trop cuit car alors il devient sec et dur.\nÉtape 6 Lorsque le thon devient légèrement gris sur un tiers de la hauteur le retourner et le laisser cuire de l''autre côté environ 3 minutes.\nÉtape 7 Servir avec un riz au beurre, les oignons confits et de la coriandre hachée. Tout simple mais un régal. Saler et poivrer légèrement au moment de servir."]' where recette_id = 'ce61527b90aae4162b21a4cdae7435e7';
update fact_recette_base set etapes = '[''Préparation 18 min Préparation : 10 min Repos : - Cuisson : 8 min'', "Étape 1 Dans chaque tranche de poulet mettre deux tranches de bacon l''une à côté de l''autre et poser dessus une tranche de fromage.\nÉtape 2 Refermer le tout en pliant la tranche en deux.\nÉtape 3 Prévoir 3 assiettes et mettre dedans la farine, l''oeuf battu et la chapelure. \r\nTremper chaque escalope d''abord dans la farine,\nÉtape 4 puis dans l''oeuf\nÉtape 5 et pour finir dans la chapelure.\nÉtape 6 Les faire cuire quelques minutes de chaque côté dans une poêle avec un peu de beurre.\nÉtape 7 Déguster immédiatement."]' where recette_id = '4fe32383916b4608b915a58a50450dd2';
update fact_recette_base set etapes = '[''Préparation 18 min Préparation : 3 min Repos : - Cuisson : 15 min'', "Étape 1 Préchauffer le four à 220°, thermostat 6-7.\nRincer le dos de cabillaud à l''eau claire, bien l''égoutter sur du papier absorbant.\nÉtape 2 Huiler un plat allant au four avec une cuillère à soupe d''huile d''olive.\nÉtape 3 Disposer le dos de cabillaud dans le plat. Saler, poivrer selon votre goût.\nÉtape 4 Arroser le poisson d''une cuillère à soupe d''huile d''olive.\nÉtape 5 Enfourner pour 15 min."]' where recette_id = 'c2d72ea85fd569083be435ef50147f5a';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 5 min Repos : - Cuisson : 15 min'', "Étape 1 Dans une grande casserole d''eau froide, mettez les ailes de raie, le vinaigre, le laurier, le thym, les grains de poivre, 1 cuillère à café de gros sel.\nÉtape 2 Faites chauffer doucement jusqu''à frémissement et laisser cuire 15 minutes sans bouillir.\nÉtape 3 Mettez le beurre doux à cuire dans une casserole 1 à 2 minutes, ajoutez ensuite le beurre demi-sel.\nÉtape 4 Hachez le persil. Une fois le beurre fondu, ajoutez le jus de citron, les câpres et le persil haché puis retirer du feu.\nÉtape 5 Égouttez les ailes de raie puis servez-les accompagnées de la sauce. Vous pouvez servir les ailes de raie aux câpres accompagnées de purée de pommes de terre."]' where recette_id = 'f12fd4e797cea131ae1632c6e9858a16';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 10 min Repos : - Cuisson : 10 min'', "Étape 1 Trancher le choux en gros quartiers et le blanchir jusqu''à ce qu''il soit cuit mais ferme.\nÉtape 2 Faire revenir l''oignon avec une noisette de beurre et ajouter les lardons.\nÉtape 3 Ajouter le choux (bien égoutté) et faire dorer le tout. Saler, poivrer.\nÉtape 4 Déglacer au vin blanc et laisser évaporer un peu à feu vif.\nÉtape 5 C''est prêt!!"]' where recette_id = 'f3bfab8aa35a2028a7bdb63c109f823e';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 5 min Repos : - Cuisson : 15 min'', "Étape 1 Saler poiver et saupoudrer les côtelettes d''herbes de Provence sur les deux faces. Asperger avec quelques gouttes du jus de citron.\nÉtape 2 Emincer échalotes et ail.\nÉtape 3 Faire chauffer un peu d''huile d''olive dans une poêle.\nÉtape 4 Faire griller les côtelettes à feu vif pendant 4-5 minutes de chaque côté. Réduire le feu et ajouter les échalotes: quand elles ont fondu dans la graisse, ajouter l''ail, saupoudrer à nouveau d''herbes de Provence, arroser de jus de citron et couvrir. Laisser mijoter encore 3 ou 4 minutes.\nÉtape 5 Servir avec une rondelle de citron pour décorer et une bonne salade en accompagnement (le mélange laitue + concombre, par sa fraîcheur, fait très bien l''affaire)."]' where recette_id = '2dbf8b49a4d0dc34c46d991f31e526be';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 10 min Repos : - Cuisson : 10 min'', "Étape 1 Mélanger l''huile, le curry, le miel et le jus du citron.\nÉtape 2 Faire cuire les côtes de porc à la poêle.\nÉtape 3 À mi-cuisson des côtes de porc, arrosez avec la préparation.\nÉtape 4 Terminez la cuisson en retournant souvent la viande."]' where recette_id = '4ba8a3f4ac8d5615d40860ac503ab788';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 5 min Repos : - Cuisson : 15 min'', "Étape 1 Préchauffer votre four à thermostat 8 (250°C).\nUne fois que votre pâte est confectionnée, la laisser reposer au moins 30 min.\nÉtape 2 Rompre la pousse, puis l''étaler le plus finement possible sur un plan de travail fariné. La parsemer des oignons émincés, des lardons puis répartir la crème uniformément dessus.\nÉtape 3 Enfourner votre flammenkueche à four chaud et surveiller la cuisson (5 à 10 min en principe)."]' where recette_id = 'b463d730c390cf3d2ab84a646ace1770';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 20 min Repos : - Cuisson : -'', "Étape 1 Dans un saladier, mélanger la farine et le gros sel.\nÉtape 2 A l''aide d''un fouet, verser l''eau en deux ou trois fois, tout en mélangeant la préparation. On obtient une pâte lisse et épaisse à laquelle on ajoute un oeuf pour donner une belle coloration à la cuisson.\nÉtape 3 Filmer et laisser reposer 1 à 2 heures au réfrigérateur.\nÉtape 4 Graisser la crêpière avec une coton imbibé d''huile. Verser une louche de pâte, attendre que la galette colore pour la décoller à l''aide d''une spatule et la retourner. La laisser cuire encore 1 mn environ.\nÉtape 5 Pour une galette complète, beurrer généreusement les deux côtés de la galette et déposer au centre de l''un des deux, du jambon et de l''emmental râpé, puis casser un oeuf au centre de la galette. \nUne fois qu''il commence à cuire, saler, poivrer et rabattre les bords de la galette de façon à ne laisser paraître que le jaune. \nC''est prêt une fois que l''oeuf est assez cuit."]' where recette_id = '14591e4d815f6c24ca726cd97ea96014';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 5 min Repos : - Cuisson : 15 min'', "Étape 1 Cuire les macaronis le temps indiqué sur le paquet, les égoutter et réserver.\nÉtape 2 Dans une petite casserole, faire fondre le beurre à feu doux.\nÉtape 3 Une fois bien fondu, ajouter la farine et bien mélanger.\nÉtape 4 Incorporer le lait, assaisonner et remuer sans vous arrêter jusqu''à ce que la sauce épaississe.\nÉtape 5 Hors du feu, ajouter le cheddar râpé et remuer jusqu''à ce qu''il soit complètement fondu.\nÉtape 6 Enfin, verser les macaronis dans la sauce au fromage et remuer pour bien les enrober. C''est prêt !"]' where recette_id = 'a3f6d99dd93fc1d73e3329eee05bda0c';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 10 min Repos : - Cuisson : 10 min'', "Étape 1 Inciser les magrets côté peau en quadrillage sans couper la viande.\nÉtape 2 Cuire les magrets à feu vif dans une cocotte en fonte, en commençant par le coté peau.\nÉtape 3 Le temps de cuisson dépend du fait qu''on aime la viande plus ou moins saignante. Compter environ 5 min de chaque côté. Retirer régulièrement la graisse en cours de cuisson.\nÉtape 4 Réserver les magrets au chaud (au four, couverts par une feuille d''aluminium).\nÉtape 5 Déglacer la cocotte avec le miel et le vinaigre balsamique. Ne pas faire bouillir, la préparation tournerait au caramel. Bien poivrer.\nÉtape 6 Mettre en saucière accompagnant le magret coupé en tranches.\nÉtape 7 Comme accompagnement, je suggère des petits navets glacés (cuits à l''eau puis passés au beurre avec un peu de sucre)."]' where recette_id = '1bbde49a960a655e1f7b1e975b955d9b';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 5 min Repos : - Cuisson : 15 min'', ''Étape 1 Coupez en morceaux les blancs de poulet. Épluchez et émincez les oignons. Lavez et coupez en lamelles le poivron. Diluez le cube de volaille dans l’eau. Coupez en rondelles le chorizo.\nÉtape 2 Dans la cuve du Cookeo, mettez les lardons, les oignons, le poulet, le poivron, le cumin, le paprika, le piment, mélangez puis démarrez le mode "dorer" pendant 5 minutes en remuant de temps en temps.\nÉtape 3 Ajoutez le riz, le bouillon de volaille, le chorizo, salez, poivrez puis programmez 10 minutes en cuisson sous pression.\nÉtape 4 Rectifiez l’assaisonnement puis servez.'']' where recette_id = 'fe4b3ce1106f14d7ea8822ec7406bc42';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 10 min Repos : - Cuisson : 10 min'', "Étape 1 Mixez 4 escalopes de poulet avec 4 blancs d''œufs puis ajouter le sel et le poivre.\nÉtape 2 Avec une cuillère à soupe formez des petites boulettes avec ce mélange.\nÉtape 3 Roulez les boulettes dans la chapelure afin de les recouvrir.\nÉtape 4 Dans une poêle, faire chauffer de l''huile et mettre les nuggets à cuire.\nÉtape 5 Retournez les nuggets au bout de 4 à 5 min (quand ils sont bien dorés).\nÉtape 6 Vous pouvez servir !"]' where recette_id = '6d13862f107e29b4b2ea83f824304ad9';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 10 min Repos : - Cuisson : 10 min'', "Étape 1 Couper les pleurotes en lamelles puis éplucher l''ail et séparer les feuilles de persil des tiges.\nÉtape 2 A l''aide d''un hachoir, mélanger l''ail et le persil.\nÉtape 3 Verser 3 cuillères d''huile d''olive et laisser chauffer 2 minutes à feu vif, ajouter l''ail et le persil puis laisser dorer à feu moyen.\nÉtape 4 Ajouter les pleurotes et laisser cuire pendant 8 minutes.\nÉtape 5 Saler et poivrer à la fin de la cuisson."]' where recette_id = 'a1f3d41affb0d8779b5c96f56b76385f';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 5 min Repos : - Cuisson : 15 min'', "Étape 1 Mettre une grande poêle à chauffer.\r\nCouper les oignons en petits morceaux, et les faire cuire à feu assez fort.\nÉtape 2 Remuer, en ajoutant du curry et du cumin.\nÉtape 3 Couper les blancs de poulet en morceaux, les ajouter dans la poêle et remettre des épices; tourner.\nÉtape 4 Baisser le feu, et ajouter 2 cuillères à soupe de crème.\nÉtape 5 Après 5 min de cuisson, remettre 2 cuillères à soupe de crème et des épices (si nécessaire).\nÉtape 6 Si le plat est fait à l''avance, remettre un peu de crème au moment de réchauffer car la sauce s''évapore.\nÉtape 7 Bon appétit"]' where recette_id = 'a95dfd3b111f9b87ede736ceea242fe2';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 20 min Repos : - Cuisson : -'', "Étape 1 Mettre 350 g de farine dans un grand saladier puis ajouter successivement le sel, la levure boulangère et l''huile d''olive.\nÉtape 2 Verser petit à petit l''eau tiède tout en mélangeant avec une cuillère en bois.\nÉtape 3 Remuer longuement jusqu''à obtention d''une pâte qui se détache du saladier.\nÉtape 4 Laisser reposer la pâte pendant 1h en couvrant le saladier avec un torchon dans un endroit chaud.\nÉtape 5 Après le temps de repos, déposer de la farine sur votre plan de travail y déposer la pâte à pizza.\nÉtape 6 La travailler comme on travaillerait une pâte à pain.\nÉtape 7 Façonner votre pizza aux dimensions de votre plaque à four où l''idéal, c''est de déposer la pâte sur du papier cuisson.\nÉtape 8 Agrémenter votre pizza au grès de vos envies ou de vos restes dans le frigo."]' where recette_id = 'e6fde24e7cbb96ace7d184c8f39087be';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 10 min Repos : - Cuisson : 10 min'', "Étape 1 Faire cuire les pâtes selon votre goût et le type de pâtes.\nÉtape 2 Dans une casserole, faire revenir les oignons avec un peu d''huile, ajouter le thon, le concentré de tomates, la crème, le sel et le poivre.\nÉtape 3 Egoutter les pâtes, et les mélanger avec la préparation.\nÉtape 4 Ajouter le gruyère râpé."]' where recette_id = 'ef997232c53854d89d18f444cf5c8db2';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 5 min Repos : - Cuisson : 15 min'', "Étape 1 Faites fondre dans une poêle anti-adhésive la beurre avec la crème.\nÉtape 2 Ajoutez le parmesan grossiement coupé (s''il n''est pas déjà en poudre!), la moitié du persil haché et le petit piment oiseau ouvert dans la longueur.\nÉtape 3 Faites cuire les pâtes comme indiqué sur le sachet.\nÉtape 4 Retirez l''envelope du piment oiseau de la sauce, égouttez les pâtes et versez la sauce dessus en mélangeant bien.\nÉtape 5 Décorez avec le reste du persil haché.\nÉtape 6 N''ajoutez pas trop de sel, le parmesan aura déjà relevé le goût des pâtes."]' where recette_id = '9782f0c32ebcacb45147cfa6cd938e7a';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 10 min Repos : - Cuisson : 10 min'', "Étape 1 Préparez votre marinade dans un plat assez creux pour que les dés de poulets soient bien tous en contact avec les lamelles d''oignon, les herbes, l''huile et la sauce soja. Mélangez bien, couvrez et laissez mariner au moins deux heures à température ambiante.\nÉtape 2 Mettez votre julienne dans une grande casserole d''eau bouillante, et laissez cuire 6-7 min dès reprise de l''ébullition. Egouttez et réservez.\nÉtape 3 Faites cuire vos nouilles dans un grand volume d''eau (attention ça cuit très vite, 3-4 min dès reprise de l''ébullition). Egouttez et réservez.\nÉtape 4 Dans un wok ou un faitout, versez la marinade et cuisez à feu fort pour dorer un peu le poulet. Quand le poulet est cuit, ajoutez la julienne, et enfin les nouilles.\nÉtape 5 Remuez rapidement en mélangeant bien les ingrédients, et juste avant de servir, ajoutez l''assaisonnement (4 cuillères à soupe de sauce soja, 2 cuillères à soupe de nuoc mam et les 2 cuillères à café de sucre).\nÉtape 6 Servez immédiatement et dégustez sans attendre!"]' where recette_id = 'fc7500bd2b0d2689a940b3481aadb4c7';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 10 min Repos : - Cuisson : 10 min'', "Étape 1 Enlever la peau brune des soles.\nÉtape 2 Dans un plat, fariner la sole, salée et poivrée, des deux côtés.\nÉtape 3 Dans une poèle ovale si possible pour la forme du poisson, mettre l''huile à chauffer, vérifier la chaleur en posant la queue du poisson uniquement et commencer la cuisson.\nÉtape 4 Quand la face est dorée, régler la force du gaz et retourner la sole.\nÉtape 5 Réserver la sole et dégraisser, replacer sur le gaz et ajouter le beurre, ajouter la sole et conduire la cuisson pour avoir le beurre noisette et non brûlé.\nÉtape 6 Déglacer avec le jus du citron, le beurre forme alors de grosses bulles c''est cela la bonne meunière. Dresser aussitôt et servir.\nÉtape 7 A accompagner avec des tagliatelles ou des pommes vapeurs."]' where recette_id = 'b9324995619b89a360700ac92378873e';
update fact_recette_base set etapes = '[''Préparation 20 min Préparation : 20 min Repos : - Cuisson : -'', "Étape 1 Couper la viande au couteau (en brunoise).\nÉtape 2 Dans un bol, mélanger le jaune d’œuf, la moutarde de Dijon, l''oignon, les câpres, la Worcestershire sauce, le ketchup, le tabasco, le sel et le poivre. Ajouter l''huile d''olive en remuant avec le fouet.\nÉtape 3 Ajouter la viande à la sauce ainsi que le persil. Rectifier l''assaisonnement.\nÉtape 4 Réfrigérer ou servir immédiatement."]' where recette_id = '29c48ccd4271f00e51a8aa3739da2ff9';
update fact_recette_base set etapes = '[''Préparation 21 min Préparation : 16 min Repos : - Cuisson : 5 min'', "Étape 1 Mettre les nouilles dans un saladier et verser de l’eau chaude à hauteur\npendant 4 minutes.\nÉtape 2 Pendant ce temps là on prépare les légumes :\nCommencer par émincer l’oignon finement et le réserver dans un saladier.\nPasser aux courgettes: retirer les extrémités et les tailler en 2, couper des lamelles puis les couper finement en bâtonnets\nFaire la même chose avec les carottes et réserver tous vos légumes.\nÉtape 3 Retirer les pâtes de l’eau chaude: elles doivent être ramollies mais pas cuites !\nDécortiquer les crevettes. Penser à conserver les queues.\nÉtape 4 Faire chauffer votre poêle et lorsqu’elle est bien chaude, mettre tous les légumes dans l''huile.\nLaisser colorer mais veiller à garder vos légumes bien craquants !\nÉtape 5 Ajouter deux cuillères à soupe de sucre et rajouter ensuite la sauce soja.\nPas besoin de saler puisque la sauce soja va déjà amener le sel.\nÉtape 6 Intégrer ensuite les nouilles et poivrer. \nEnfin, ajouter les crevettes et mélanger pour qu’elles s’enrobent bien de sauce.\nDresser et déguster."]' where recette_id = '75917c04901d187b2fe029d59c803b7d';
update fact_recette_base set etapes = '[''Préparation 24 min Préparation : 20 min Repos : - Cuisson : 4 min'', ''Étape 1 Mélangez la farine et la bière.\nÉtape 2 Ajoutez les jaunes d\''oeufs,\nÉtape 3 puis les blancs d\''oeuf monté en neige ferme\nÉtape 4 en soulevant la masse pour ne pas le "casser". \r\nLa pâte à fish and chips est prête.\nÉtape 5 Trempez les filets de poisson généreusement\nÉtape 6 et faites frire à 160°C ou 180°C pendant 3 ou 4 min.\nÉtape 7 Egoutter soigneusement lorsque c\''est doré.\nÉtape 8 Servir avec des frites.'']' where recette_id = 'fb79a9e5e3afc815d1e91a0182663f2f';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 10 min Repos : - Cuisson : 15 min'', "Étape 1 Préparer la marinade : mélanger 1 pot de yoghourt avec les massalas (tandoori et garam), cannelle, clous de girofle et cumin. Saler.\nÉtape 2 Enduire les morceaux de poulet et laisser mariner au moins 1 heure.\nÉtape 3 Préchauffer le four au maximum (un four ''tandoor est une vraie fournaise!) et faites-y cuire le poulet pendant 10 mn.\nÉtape 4 Retirer et laisser reposer.\nÉtape 5 Dans une cocotte, faire fondre le ghee et y faire blondir les oignons, puis ajouter la pâte ail/gingembre et laisser frire quelques\nÉtape 6 minutes. Ajouter une cuillerée d''eau de temps à autre pour éviter\nÉtape 7 que ça attache.\nÉtape 8 Laisser cuire jusqu''à ce que la matière grasse se sépare.\nÉtape 9 Ajouter la pâte de noix de cajou, lapoudre de piment, la purée de tomate et laisser cuire 10 min à feu doux. Ajouter le second pot de youghourt, la crème fouettée et les morceaux de poulet. Bien mélanger et laisser mijoter\nÉtape 10 encore 15 à 20 mn.\nÉtape 11 Dresser sur un plat creux et parsemer de feulles de coriandre hachées."]' where recette_id = '3e38ddb04affd1c1fd6b34e825e3dc48';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 20 min Repos : - Cuisson : 5 min'', "Étape 1 Lavez et essuyez les crevettes. Faites chauffer 4 cuillères à soupe d''huile dans 1 grande poêle. Ajoutez les crevettes et faites les cuire 5 mn de chaque côté puis sortez les de la poêle.\nÉtape 2 Passez l''ail au mixeur, le persil et le piment doux.\nÉtape 3 Dans la poêle, versez le reste de d''huile puis ajoutez l''ail, le persil et le piment. Remuez bien, pour que l''ail soit cuit mais non brûlé.\nÉtape 4 Remettez les crevettes à chauffer. Salez, poivrez et servez chaud."]' where recette_id = '1af18d85d8c5061312f6bec1e0c5603a';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 10 min Repos : - Cuisson : 15 min'', "Étape 1 Mélangez la farine dans le beurre fondu jusqu''à coloration blonde.\nÉtape 2 Mouillez avec le lait et faites épaissir sur feu doux en remuant. Assaisonnez de sel, de poivre et de muscade.\nÉtape 3 Ajoutez la crème, le concentré de tomate et le  jambon coupé en dés.\nÉtape 4 Réchauffez les crêpes puis garnissez-les de la béchamel au jambon bien chaude.\nÉtape 5 Réchauffez éventuellement les crêpes dans un four chaud ou gratinez-les avec du fromage râpé."]' where recette_id = '42255e867812b16d9e306341923340a7';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 25 min Repos : - Cuisson : -'', "Étape 1 Mélanger la farine, les oeufs et le lait à l''aide d''un fouet jusqu''à obtention d''une pâte homogène sans grumeaux.\nÉtape 2 Préchauffer la poêle huilée et y verser une louche de pâte.\nÉtape 3 Faire toutes les crêpes de la même façon en huilant la poêle de temps en temps, et déguster !!!"]' where recette_id = '04ca635d0fbeabbd635ead59afb1814a';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 15 min Repos : - Cuisson : 10 min'', "Étape 1 Laver soigneusement les épinards et les faire fondre dans le beurre.\nÉtape 2 Piquer la gousse d''ail pelée sur une fourchette puis s''en servir pour remuer les épinards.\nÉtape 3 Lorsque les épinards ont fondu, les arroser de crème et les parfumer de muscade, de sel et de poivre.\nÉtape 4 Mélanger et servir."]' where recette_id = '02613231cce54824ab7e9a7ee15c02d0';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 10 min Repos : - Cuisson : 15 min'', ''Étape 1 Salez et poivre les escalopes. Pelez et hachez finement les échalotes.\nÉtape 2 Faites chauffer le beurre dans une poêle. Mettre les escalopes dans le beurre chaud et faites-les saisir 5 mn de chaque côté. Egouttez les et tenez-les au chaud.\nÉtape 3 Mettez les échalotes dans la poêle et faites-les fondre doucement en remuant.\nÉtape 4 Ajoutez la crème et mélangez en grattant avec une spatule.\nÉtape 5 Incorporez une cuillère à soupe de curry en remuant. Salez, poivrez et ajoutez éventuellement une pointe de Cayenne. Faites épaissir en remuant pendant 2 à 3 minutes.\nÉtape 6 Nappez aussitôt les escalopes de cette sauce.'']' where recette_id = '4c3f563c92fedc5eae2d5f425780060b';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 10 min Repos : - Cuisson : 15 min'', "Étape 1 Couper les filets de poulet en petits morceaux, les mettre dans un saladier avec la sauce soja, l''ail, l''huile d''olive, la ciboulette et le curry. Laissez reposer une heure.\nÉtape 2 Après, faire revenir l''oignon avec un peu d''huile d''olive, une fois légèrement caramélisé, mettre la viande.\nÉtape 3 Quand la viande commence à cuire, mettre petit à petit la crème fraîche (épaisse ou liquide), ajouter du curry selon vos goûts sur la viande.\nÉtape 4 Mélanger bien le tout, saler et poivrer.\nÉtape 5 Bon appétit à vous."]' where recette_id = '62c33df4d4a0066d4998ffc944c86f27';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 15 min Repos : - Cuisson : 10 min'', "Étape 1 Faire cuire les pommes de terre avec la peau (elles doivent rester un peu fermes). Faire cuire les courgettes (coupées en rondelles) à l''étouffée avec des herbes de Provence, du sel et du poivre.\nÉtape 2 Eplucher les pommes de terre (sous un mince filet d''eau froide, voire carrément dans l''eau froide pour ne pas vous brûler). Les couper en tranches.\nÉtape 3 Dans un plat à gratin, mélanger les pommes de terre et les courgettes. Saler, poivrer, rajouter des herbes de Provence, la crème fraîche (ou la béchamel), la muscade et un peu de fromage (50g). Mélanger de manière à bien répartir la crème et le fromage, puis couvrir avec le reste du fromage.\nÉtape 4 Cuire 20 mn à four chaud (thermostat 7/210°C)."]' where recette_id = 'f5252e6b2e62c8e9405fa54365ce6f9b';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 20 min Repos : - Cuisson : 5 min'', "Étape 1 A l''aide d''un bon couteau, couper la butternut en cubes de 3 cm environ, et éplucher ensuite les morceaux (c''est plus facile dans cet ordre). Cuire les morceaux 5 mn à la vapeur ou dans un fond d''eau non salée. Les morceaux doivent être tendres, mais ne pas s''effondrer.\nÉtape 2 Pendant la cuisson, hacher grossièrement la poitrine fumée (ou la couper en tout petits morceaux).\nÉtape 3 Disposer les morceaux de courge et de poitrine dans un plat à gratin, en mélangeant délicatement (si la courge s''écrase un peu, ce n''est pas grave). \nParsemer d''herbes hachées et de pignons de pin à votre goût.\nÉtape 4 Assaisonner de noix de muscade et de poivre. Saler très légèrement, car la poitrine fumée est déjà salée (personnellement, je ne sale pas du tout, mais je force sur la noix de muscade). Verser une lichette de crème liquide (je dois mettre à peu près 5 cl), et finir par saupoudrer de parmesan râpé.\nÉtape 5 Enfourner 20 mn environ dans un four préchauffé à 210°C.\nÉtape 6 Servir bien chaud, accompagné d''une salade verte."]' where recette_id = 'a0784844eda3c9d36eb3464f1b7b7b61';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 15 min Repos : - Cuisson : 10 min'', "Étape 1 Cuire les coquillettes à l''eau salée.\nÉtape 2 Pendant ce temps, faire revenir les lardons.\nÉtape 3 Couper la tomate en dés et les champignons en lamelles.\nÉtape 4 Mélanger dans un plat à gratin les légumes, les lardons et les pâtes.\nÉtape 5 Ajouter la crème fraîche.\nÉtape 6 Terminer par une généreuse couche de gruyère râpé.\nÉtape 7 Enfourner à four chaud (Th7) et laisser cuire jusqu''à ce que le gruyère prenne une jolie couleur dorée."]' where recette_id = '8de0fd814bfa3baa6528d1d1ed91ea1e';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 10 min Repos : - Cuisson : 15 min'', "Étape 1 Formez des rouleaux avec les tranches de jambon et disposez les dans un plat à gratin (ou dans deux petits plats, si on veut faire le service directement dedans, ce que je conseille).\nÉtape 2 Mélangez la crème, le concentré de tomate et le madère, de sorte à obtenir un liquide assez épais et d''un joli rose. Il n''y a pas besoin de mettre beaucoup de madère, c''est juste pour parfumer.\nÉtape 3 Assaisonnez selon goût. Versez ce mélange sur le jambon et mettez dans le four préchauffé à 250°C.\nÉtape 4 Cuire 10-15 minutes et sevir aussitôt."]' where recette_id = '94ecc1332249fc457842aa1f411a86f0';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 10 min Repos : - Cuisson : 15 min'', "Étape 1 Faire revenir oignon et ail émincés dans l''huile.\nÉtape 2 Ajouter la tomate épépinée détaillée en petits cubes, le piment oiseau émincé, les lentilles lavées et égouttées, le curry selon votre goût (environ une cuillèrée à café), sel et poivre.\nÉtape 3 Couvrir d''eau jusqu''à dépasser les lentilles de 1 ou 2 cm. Porter à ébullition, couvrir et laisser cuire environ 15 minutes.\nÉtape 4 Les lentilles corail cuisent vite : il vaut mieux surveiller de près si vous préférez qu''elles gardent leur forme. Sinon, on obtient une purée qui n''est pas désagréable non plus.\nÉtape 5 Servir saupoudré d''un peu de coriandre fraîche émincée, avec du riz et une salade cela fait un repas végétarien complet."]' where recette_id = 'e14e158763945f838e7f0aa5eb42d678';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 20 min Repos : - Cuisson : 5 min'', "Étape 1 Détailler tous les légumes en fine julienne.\nÉtape 2 Faire bouillir une grande casserole d''eau salée, y jeter les nouilles, dès que l''ébullition à repris, couvrir, éteindre le feu et laisser reposer pendant 4 min.\nÉtape 3 Pendant ce temps, faire revenir les légumes dans l''huile pendant 5 mn, à feu très vif, ajouter les cinq épices et la sauce de soja.\nÉtape 4 Égoutter les nouilles, les joindre aux légumes et rectifier l''assaisonnement si besoin."]' where recette_id = 'f825f096d86daf5f524280265bca03fe';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 5 min Repos : - Cuisson : 20 min'', "Étape 1 Recette parfaite pour les nuls, les stressés ou les visites surprises, il suffit d''avoir tous les ingrédients au congélateur!\nÉtape 2 Préchauffez votre four à 180°C (thermostat 6).\nÉtape 3 Pendant ce temps, sur la plaque du four, étalez une feuille de papier aluminium assez grande.\nÉtape 4 Versez quelques goutte d''huile d''olive sur lesquels vous déposerez les filets de poisson, puis dessus les légumes, quelques rondelles d''oignons, l''aneth, sel, poivre, huile d''olive, citron avec modération.\nÉtape 5 Pliez la feuille d''aluminium en quatre, en vous assurant que le jus ne puisse pas d''échapper.\nÉtape 6 Puis, enfournez pendant 20 min environ (selon l''épaisseur du poisson).\nÉtape 7 Présentez les légumes sur le filet, sans la feuille d''alu, et accompagnez de riz ou de tagliatelles 3 couleurs."]' where recette_id = '09fddb2e3c69d235f02743e01593f535';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 15 min Repos : - Cuisson : 10 min'', "Étape 1 Éplucher les pommes de terre et les couper en forme de frites. Faire frire les pommes de terre à 160-170°C et ensuite  à 180-190°C durant 2 min.\nÉtape 2 De préférence dans un bol pas trop haut (du style bol à pâtes), y mettre les frites, ajouter le fromage en grains et verser la sauce brune chaude.\nÉtape 3 Et c''est prêt !"]' where recette_id = '078e59c67b82852e48539fa7b4e02ffe';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 15 min Repos : - Cuisson : 10 min'', "Étape 1 Cuire les pâtes à l''eau bouillante salée selon le temps indiqué sur le paquet.\nÉtape 2 Pendant ce temps, faire fondre le beurre dans une casserole et y ajouter la crème.\nÉtape 3 Quand la crème est bien chaude, y plonger les dés de saumon, ils doivent cuire à la chaleur de la crème.\nÉtape 4 Quand ils sont cuits (ils doivent se détacher), ajouter le sel, le poivre et la muscade moulue.\nÉtape 5 Egoutter les pâtes, les disposer dans un grand plat ronde et napper de crème au saumon.\nÉtape 6 Servir avec du parmesan."]' where recette_id = '0bc767e93133f00448f4b09fdccd4da1';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 10 min Repos : - Cuisson : 15 min'', "Étape 1 Faire cuire les tagliatelles.\nÉtape 2 Dans une poêle, faire revenir l''ail dans l''huile d''olive pendant 30 secondes à feu doux.\nÉtape 3 Verser la crème, la ciboulette, la moutarde, le sel et le poivre. Amener à ébulltion, baisser le feu et laisser mijoter jusqu''à épaississement.\nÉtape 4 Ajouter le saumon fumé (découpé en petits morçeaux), le jus de citron et mélanger. Faire chauffer à feu doux.\nÉtape 5 Saupoudrer de parmesan et de ciboulette et servir avec les tagliatelles."]' where recette_id = '724d686e84c6115f1b8b3e81de621774';
update fact_recette_base set etapes = '[''Préparation 25 min Préparation : 10 min Repos : - Cuisson : 15 min'', "Étape 1 Tremper les truites dans le lait froid salé puis les passer dans la farine. Tapoter légèrement afin d''ôter l''excédent de farine.\nÉtape 2 Les faire cuire dans le beurre pendant 15 minutes en les retournant à mi-cuisson.\nÉtape 3 Arroser de citron et du jus de cuisson puis servir."]' where recette_id = '68c0a5d7e9b7f261ba068f2f5c0b58b9';
update fact_recette_base set etapes = '[''Préparation 28 min Préparation : 20 min Repos : - Cuisson : 8 min'', "Étape 1 Battez les oeufs avec l''huile.\nÉtape 2 Versez les oeufs battus au centre de la farine et pétrissez, jusqu''à ce que la pâte soit homogène.\nÉtape 3 Continuez de pétrir pour développer l''élasticité de la pâte.\nÉtape 4 Couvrez et laissez reposer la pâte entre 30 min et 1 h.\nÉtape 5 Pendant ce temps, préparez la farce à raviolis: mixez la tranche de jambon et incorporez-la au fromage de chèvre frais. Assaisonnez de sel (peu), poivre et basilic.\nÉtape 6 Etendez au rouleau à pâtisserie la pâte le plus finement possible.\nÉtape 7 Couvrez-la et laissez-la reposer 1 h au moins.\nÉtape 8 A l''aide d''un couteau, commencez à tracer les carrés sur la moitié de la pâte, pour faciliter la découpe des raviolis.\nÉtape 9 Garnissez de la farce.\nÉtape 10 Passez du jaune d''oeuf sur les parties qui seront à souder (bord des raviolis).\nÉtape 11 Rabattez la seconde partie de pâte, et à l''aide de vos mains, soudez bien hermétiquement les raviolis autour de la farce.\nÉtape 12 Découpez les raviolis à l''aide d''une molette dentelée ou à défaut d''un couteau aiguisé.\nÉtape 13 Faites chauffer un grand volume d''eau salée, plongez les raviolis dedans et laissez cuire 8 à 10 min environ.\nÉtape 14 Egouttez les raviolis et servez-les accompagnés de sauce de votre choix.\nÉtape 15 Exemples:\nÉtape 16 - tomate/champignons\nÉtape 17 - sauce bolognaise\nÉtape 18 - sauce carbonnara\nÉtape 19 - parmesan/basilic/poivrons\nÉtape 20 Variantes:\nÉtape 21 Pour la farce vous pouvez mettre du parmesan ou de la chair à saucisse (accompagné de sauce tomate, excellent!).\nÉtape 22 A servir chaud.\nÉtape 23 Bon appétit !"]' where recette_id = 'db3281722632c08e62cae4c31935a6f5';
update fact_recette_base set etapes = '[''Préparation 29 min Préparation : 10 min Repos : - Cuisson : 19 min'', ''Étape 1 Épluchez puis pressez l’ail au-dessus de la cuve de votre Cookeo. Ajoutez l’huile d’olive et les paupiettes puis dorez sur le mode « dorer » / 6 min + préchauffage en remuant constamment.\nÉtape 2 Quand toutes les faces sont légèrement colorées, ajoutez le fond de veau et mouillez avec le vin blanc et l’eau. Ajoutez la moutarde, le vinaigre balsamique, salez, poivrez et lancez la cuisson sur le mode « cuisson sous pression » / 19 min.\nÉtape 3 Remuez un peu et maintenez au chaud jusqu’à dégustation.'']' where recette_id = '35ea369768c82c81a9535bbc496dd363';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 15 min Repos : - Cuisson : 15 min'', "Étape 1 Couvrez les deux faces de la côte avec du gros sel, attendez maintenant pendant 15 à 20 min ; le délai dépendra de l''épaisseur de la côte.\nÉtape 2 Au bout de ce temps retirez tout le sel avec un couteau et badigeonnez la côte d''huile d''olive. Poivrez et saupoudrez d''herbes de Provence.\nÉtape 3 Vous aurez préparé une braise bien rouge sur votre barbecue, vous pouvez donc procéder à la cuisson: entre 5 et 8 min par face (fonction de votre goût, mais pas trop cuit pour ne pas gâcher le goût de la viande!!!)."]' where recette_id = 'd8ff17fc9e28e5dc949ae7db04d39c66';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 10 min Repos : - Cuisson : 20 min'', "Étape 1 - Laver les tomates et les découper en dés. Peler les carottes, et les découper en fines rondelles.\nÉtape 2 - Dans une casserole, verser les lentilles corail et couvrir d''eau. Porter à ébullition. Laisser cuire pendant 10 min environ, jusqu''à complète absorption de l''eau. Retire du feu et laisser reposer.\nÉtape 3 - Dans une sauteuse, verser l''huile et chauffer. Y ajouter l''ail qui dorera pendant une petite minute. Verser ensuite les légumes et saupoudrer avec les épices. Ajouter enfin le concentré de tomate.\nÉtape 4 - Verser le lait de coco et laisser mijoter environ 10 min. sans couvrir.\nÉtape 5 - Enfin, ajouter les lentilles et bien remuer le tout."]' where recette_id = 'b8a7a871ef1fb33fb4de6a7f0757712e';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 15 min Repos : - Cuisson : 15 min'', "Étape 1 Retirez les feuilles abimées de endives. Découper l''arrière de l''endive (là où les feuilles sont attachées) en creusant avec un couteau pointu afin d''y enlever un cône.\nÉtape 2 Les laver.\nÉtape 3 Les faire cuire 15 mn à la vapeur en les ayant saupoudrées de sel et de poivre.\nÉtape 4 Ensuite, les rouler dans une tranche de jambon, après les avoir égouttées.\nÉtape 5 Disposer 1/2 boîte de champignons (découpés en lamelles) au fond d''un plat à gratin beurré.\nÉtape 6 Disposer les endives, entourées de leur tranche de jambon.\nÉtape 7 Parsemer le dessus du restant de champignons.\nÉtape 8 Mélanger à la béchamel le gruyère râpé (on peu aussi mélanger au fromage du beaufort et du comté).\nÉtape 9 N''oubliez pas la noix de muscade râpée dans la béchamel !!!\nÉtape 10 Versez la sauce sur les endives.\nÉtape 11 Passez au four (210°C) pendant environ 10 mn"]' where recette_id = '53a8e33ba90432c02dd93f38286181e7';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 15 min Repos : - Cuisson : 15 min'', "Étape 1 - Couper les champignons en tranches et les faire revenir dans une poêle avec un peu de beurre, à feu moyen. Saler, poivrer.\nÉtape 2 - Pendant ce temps, faire cuire le bacon dans une grande poêle, et mettre le pain à toaster.\nÉtape 3 - Rajouter dans la poêle les oeufs (au plat), saler, poivrer.\nÉtape 4 Réchauffer les haricots au micro-ondes (2 min, en remuant à mi-temps) et beurrer les tranches de pain que l''on coupera en diagonale.\nÉtape 5 - Disposer tous les ingrédients dans une grande assiette: c''est prêt!"]' where recette_id = '52f227cfb8d0be77c0dab60f96a9d37f';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 20 min Repos : - Cuisson : 10 min'', "Étape 1 Faire fondre les épinards dans le beurre jusqu''à ce qu''ils soient tombés puis les passer au moulin à légumes.\nÉtape 2 Les remettre dans la casserole avec la crème, saler, poivrer et mélanger.\nÉtape 3 Laisser réchauffer sur feu doux et servir bien chaud."]' where recette_id = 'd83012b02ab36be50f56716ba0303440';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 30 min Repos : - Cuisson : -'', "Étape 1 Préparez les sauces d''accompagnement :\nÉtape 2 Sauce tartare : mélangez 125 g de mayonnaise avec les câpres, le persil et les cornichons hachés. Salez, poivrez.\nÉtape 3 Sauce aïoli : mélangez 125 g de mayonnaise avec 2 gousses d''ail pilées. Salez, poivrez.\nÉtape 4 Sauce au céleri : mélangez la crème avec le céleri, les noix et le jus de citron. Salez, poivrez.\nÉtape 5 Sauce tomate aux anchois : mélangez la purée de tomate avec les anchois et les olives. Salez, poivrez. Réservez les sauces au frais.\nÉtape 6 Découpez la viande en cubes d''environ 2 cm de côté.\nÉtape 7 Faites chauffer l''huile dans un caquelon à fondue avec le thym et le laurier. Dès qu''elle est chaude, retirez-les et apportez l''huile à table, maintenez-la chaude. Faites cuire les morceaux de viande au fur et à mesure dans l''huile, égouttez et dégustez.\nÉtape 8 Servez avec les sauces, un grand plat de salades mélangées et des frites ou du riz."]' where recette_id = '6d1ed772f3cf89ea868828e77cd4b864';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 10 min Repos : - Cuisson : 20 min'', ''Étape 1 Etalez la préparation désirée sur votre pâte à pizza et enfournez environ 20 min à 180°C (thermostat 6).'']' where recette_id = 'bea77e3fdabc75a638b7633f2e565d97';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 15 min Repos : - Cuisson : 15 min'', ''Étape 1 Dégermer les gousses d\''ail et les hacher ; faire chauffer à feu moyen un bon fond d\''huile d\''olive dans un poêlon, mettre les coquillages et remuer pour les "mouiller" dans l\''huile ; ajouter le vin, le beurre, l\''ail, saler, poivrer généreusement.\nÉtape 2 Quand les coques s\''ouvrent, ajouter le persil, remuer, réduire le feu, laisser mijoter 5 mn, puis couvrir et réserver.\nÉtape 3 Cuire les pâtes (voir les temps de cuisson sur le paquet, mais sûrement dans les 10-12 mn).\nÉtape 4 Les mélanger aux coques en "délayant" avec 2 ou 3 cuillères à soupe d\''eau de cuisson des pâtes, réchauffer à feu doux quelques minutes puis servir.\nÉtape 5 Miam......'']' where recette_id = '88e1f0e99d98f1aa4776a2cb3ee675cf';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 10 min Repos : - Cuisson : 20 min'', "Étape 1 Le Mont d''Or est un fromage du Haut-Jura, vendu à la coupe ou dans une boîte en épicéa. Pour cette recette, choisissez le fromage en boîte.\nÉtape 2 Prenez votre Mont d''Or, faites un trou au milieu dans lequel vous verserez un peu de vin blanc.\nÉtape 3 Placez le fromage au four à 180°C (thermostat 6) jusqu''à ce qu''il soit fondu.\nÉtape 4 Accompagnez de pommes de terre vapeur, de charcuterie, et d''un vin blanc."]' where recette_id = 'e5b290fb49500621e9bd25590e2ea5d5';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 10 min Repos : - Cuisson : 20 min'', "Étape 1 Si vous utilisez des haricots secs, les faire tremper 12 heures avant de commencer.\nÉtape 2 Hacher les oignons et l''ail et les faire revenir dans une grande poêle.\nÉtape 3 Ajouter les haricots et le piment en poudre (selon votre goût, en tout cas une grosse pointe de couteau).\nÉtape 4 Ajouter la viande hachée.\nÉtape 5 Quand la viande est presque cuite, ajouter les tomates. Cuire à feu doux jusqu''à évaporation de la moitié du jus.\nÉtape 6 Saler, poivrer et rajouter du piment si nécessaire.\nÉtape 7 Mettre les nachos dans un plat à gratin, verser le mélange et parsemer de fromage râpé.\nÉtape 8 Mettre sous le grill du four jusqu''à ce que le fromage gratine.\nÉtape 9 Servir chaud avec la crème acidulée"]' where recette_id = 'bed676c1e334971abe99d12f791979dc';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 30 min Repos : - Cuisson : -'', "Étape 1 Préparer la marinade avec l''huile de sésame, la sauce teriyaki, le vinaigre de riz, le gingembre frais à râper, la coriandre (garder quelques feuilles), quelques cuillères à café de graines de sésame, le piment de Cayenne.\nÉtape 2 Verser la marinade dans le saladier contenant le saumon et bien mélanger.\nÉtape 3 Couper les avocats et la mangue en petits cubes.\nÉtape 4 Émincer finement les petits oignons.\nÉtape 5 Les mettre dans le saladier contenant le saumon et bien mélanger le tout. Placer au frais.\nÉtape 6 Faire bouillir de l''eau puis faire cuire le riz pour 4 personnes.\nÉtape 7 Égoutter le riz et le servir dans 4 petits bols, saupoudrer de graines de sésame et décorer avec quelques feuilles de coriandre.\nÉtape 8 Sortir la préparation saumon-avocat-mangue-marinade du frigo, bien mélanger à nouveau et servir à table.\nÉtape 9 Eʻai kāua ! (Bon appétit en hawaïen!)"]' where recette_id = '41ea7d8cbcda0696ee6c8fad898b3bb5';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 5 min Repos : - Cuisson : 25 min'', "Étape 1 Préchauffer le four à 220°C (thermostat 7-8).\nMettre le rôti avec barde et ficelles dans un plat qui va au four. Couper la gousse d''ail en deux et en frotter le rôti. Parsemer le haut du rôti de thym et l''arroser d''huile d''olive. Poser les gousses d''ail sur le rôti.\nÉtape 2 Enfourner pour 15 minutes de cuisson. Sortir le rôti et retirer la barde et la ficelle. Ajouter l''eau et faire tomber l''ail dans le plat\nÉtape 3 Saler et poivrer à convenance le rôti. Laisser cuire 10 à 15 minutes au four selon la cuisson désirée."]' where recette_id = 'debc57a636cf3cb56807f340810ba749';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 10 min Repos : - Cuisson : 20 min'', "Étape 1 Eplucher et couper les pommes de terre en rondelles d''environ 0,5 cm d''épaisseur.\nÉtape 2 Les faire cuire 20 mn à la vapeur.\nÉtape 3 Faire revenir les pommes de terre et les gousses d''ail écrasées dans une poêle avec un peu d''huile pendant 10 mn. Saler et poivrer.\nÉtape 4 Ajouter les lardons et faire revenir 5 mn de plus.\nÉtape 5 Ajouter le fromage coupé en morceaux et laisser fondre en remuant pendant 5 à 10 mn.\nÉtape 6 Ajouter la crème fraîche, bien mélanger pour lier le tout.\nÉtape 7 C''est prêt !"]' where recette_id = '6a7e5aaf54e8ccb2e84cf4148a0093b1';
update fact_recette_base set etapes = '[''Préparation 30 min Préparation : 10 min Repos : - Cuisson : 20 min'', "Étape 1 Mettre le beurre à fondre à feu doux dans un faitout, y faire dorer l''oignon découpé en fines tranches, ajouter le persil et mélanger.\nÉtape 2 Ajouter les palourdes, les saler et poivrer. Couvrir et remuer fréquemment.\nÉtape 3 Une fois les palourdes ouvertes (5 min), ajouter le vin blanc et mettre à feu fort 10 min tout en pensant à mélanger de temps à autre."]' where recette_id = '5c20bf64f100a0bcdbc32e103e622edb';
update fact_recette_base set etapes = '[''Préparation 32 min Préparation : 10 min Repos : - Cuisson : 22 min'', ''Étape 1 Coupez le filet mignon en morceaux de taille moyenne, puis déposez-les dans la cuve de votre Cookeo. Ajoutez le beurre, puis dorez la viande sur le mode « dorer » / 3 min + préchauffage, en remuant constamment. Réservez dans un saladier, puis essuyez sommairement la cuve.\nÉtape 2 Versez le vin blanc, le bouillon cube, le jus des champignons et 30\xa0cl de crème dans la cuve. Mélangez un peu à l’aide d’une cuillère en bois.\nÉtape 3 Badigeonnez les morceaux de filet mignon de moutarde et placez-les dans la cuve. Lancez la cuisson sur le mode « cuisson sous pression » / 22 min.\nÉtape 4 En fin de cuisson, versez dans un plat. Ajoutez le reste de crème, assaisonnez et mélangez bien.'']' where recette_id = '74c38882e014388a327e9ab0acfe4416';
update fact_recette_base set etapes = '[''Préparation 33 min Préparation : 10 min Repos : - Cuisson : 23 min'', ''Étape 1 Versez les lardons dans la cuve de votre Cookeo, puis faites dorer sur le mode « dorer » / 2 min + préchauffage en remuant constamment. Retirez ensuite les lardons et replacez la cuve sans la rincer.\nÉtape 2 Piquez les saucisses avec une fourchette. Pelez la carotte, puis coupez-la en rondelles épaisses. Versez 1,5 l d’eau froide dans la cuve. Ajoutez le bouquet garni, les carottes et les saucisses, puis lancez une première cuisson sur le mode « cuisson sous pression » / 10 min.\nÉtape 3 Versez les lardons, l’oignon blanc et les lentilles dans la cuve. Inutile de saler. Relancez la cuisson sur le mode « cuisson sous pression » / 13 min.'']' where recette_id = '932b20154a94332a95577c62aa5dcb1f';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 5 min Repos : - Cuisson : 30 min'', "Étape 1 Faire revenir les andouillettes dans un peu de beurre avec l''échalote à feu doux pendant 15 à 20 mn.\nÉtape 2 Lorsque les andouillettes sont dorées, les recouvrir 5 mn.\nÉtape 3 Dans un bol, mélanger la crème fraîche et la moutarde.\nÉtape 4 Rajouter ce mélange aux andouillettes, et faire cuire pendant encore 5 mn à feu très doux."]' where recette_id = 'e61e7c515c688012604f3c4efe38bb8d';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 30 min Repos : - Cuisson : 5 min'', "Étape 1 Cisailler la viande en tranches très fines, et faire mariner au frigo avec le curry, ail, glutamate et les sauces, au moins 30 mn.\nÉtape 2 Pendant ce temps préparer la sauce, si vous cuisinez souvent asiatique, doubler les proportions et conservez-là dans un bocal. Vous pouvez ajouter une pointe de piment (sauce chili) pour la parfumer. Faire bouillir tous les ingrédients et réserver.\nÉtape 3 Pour les vermicelles, faire bouillir une bonne casserole d''eau. Y plonger les vermicelles 3 à 4 mn. Egoutter et les ranger par poignée.\nÉtape 4 Faire revenir la viande dans un peu d''huile, à feu très fort et très brièvement : la viande doit être saisie simplement, pour la garder tendre.\nÉtape 5 Servir dans des grand bols de préférence : commencer par la batavia, le soja, puis 3 ou 4 poignées de vermicelles par personnes, 2 nems coupés petits morceaux par personne, la viande. Décorer avec la coriandre hachée, la menthe et quelques cacahuètes concassées (facultatif). Arroser de sauce et c''est prêt !"]' where recette_id = 'f1ec28f249b359d27149ab48d9de2a9e';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 20 min Repos : - Cuisson : 15 min'', "Étape 1 Mélangez l''ail, le gingembre avec la moitié de la sauce soja et la maïzena et faites mariner le boeuf pendant 1/2 heure au frais.\nÉtape 2 Faites chauffez un wok, ajoutez l''huile puis le boeuf et sa marinade : laissez cuire deux minutes en remuant de temps en temps.\nÉtape 3 Réservez le boeuf dans une assiette puis remplacez par les oignons et un petit verre d''eau : faites sauter les oignons pendant 2 ou 3 minutes puis ajoutez dans l''ordre : le nuoc-mam, le reste de sauce soja, le sucre et le jus de citron vert.\nÉtape 4 Laissez cuire 30 seconde puis ajoutez la viande et laissez cuire en remuant un peu deux ou trois minutes.\nÉtape 5 Saupoudrez de coriandre fraiche et servez accompagné de riz basmati blanc."]' where recette_id = '9c985852a9cd03d9a63dddfa17f359a9';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 15 min Repos : - Cuisson : 20 min'', "Étape 1 Faire dessaler la morue en la faisant tremper dans l''eau 36 à 48 heures avant le moment de préparer la brandade (en changeant l''eau régulièrement).\nÉtape 2 Faire cuire les pommes de terres et les écraser à la fourchette.\nÉtape 3 Émietter la morue dessalée et mélanger avec les pommes de terre écrasées, l''ail pilé et le persil haché.\nÉtape 4 Ajouter petit à petit l''huile d''olive (plus il y en a plus c''est bon).\nÉtape 5 Poivrer. Goûter et ajouter éventuellement un peu de sel.\nÉtape 6 Mettre la purée dans un plat allant au four et faire cuire 15 à 20 min. Passer sous le grill avant de servir."]' where recette_id = '74578be5e21f87084d83035e123ea1d3';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 20 min Repos : - Cuisson : 15 min'', "Étape 1 Faire revenir la viande hachée avec de l''huile d''olive et un peu d''eau.\nÉtape 2 Lorsque la viande est quasi cuite, faire griller l''oignon et le poivron hachés avec la viande.\nÉtape 3 Rajouter la pulpe de tomate; saler, poivrer et incorporer le paprika.\nÉtape 4 Lorsque la partie viande est terminée, chauffer galettes de blé au four quelques minutes.\nÉtape 5 Puis, sur chaque galette, disposer une feuille de laitue, la viande hachée par dessus, le gruyère râpé et les tomates coupées en dés.\nÉtape 6 Rouler le burrito, et déguster."]' where recette_id = 'ce809bf4b7eb552ec3b81cc75f03a571';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 20 min Repos : - Cuisson : 15 min'', "Étape 1 Battre les jaunes d''œufs en y ajoutant 1 pincée de sel, 2 pincées de poivre et 40 g de parmigiano reggiano râpé.\nÉtape 2 Remplir une grande casserole d''eau et la faire  chauffer avec deux pincées de gros sel.\nÉtape 3 Pendant ce temps, couper la pancetta en lamelles grossières et les faire dorer dans une poêle avec 1 cuillère à soupe d''huile d''olive.\nÉtape 4 Quand l’eau dans la casserole commence à bouillir mettez vos pâtes.\nÉtape 5 Prendre deux cuillères à soupe d''eau de cuisson des pâtes, les verser dans le jaunes d''œufs puis remuer.\nÉtape 6 Réservez la pancetta et laissez la poêle au chaud.\nÉtape 7 Une fois la cuisson des pâtes al dente, les égoutter sommairement et les mettre dans la poêle et remuer.\nÉtape 8 Verser le mélange dans un saladier et incorporez la préparation des jaunes d''œufs.\nÉtape 9 Ajouter la pancetta et deux pincées de poivre. Servez."]' where recette_id = '483fc31556e6c055d70eedb7c113fbda';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 10 min Repos : - Cuisson : 25 min'', "Étape 1 Préchauffer le four à 180°C (thermostat 6).\nÉtape 2 Hacher l''oignon et l''ail.\nÉtape 3 Dans une cocotte en fonte, faire fondre le beurre, et ensuite dorer doucement l''oignon et l’ail.\nÉtape 4 Incorporer le boeuf haché et laisser cuire doucement 10 min.\nÉtape 5 Mélanger le chili, le cumin, le concentré de tomates, et incorporer le tout au boeuf. Ajouter les haricots, le bouillon, du sel et du poivre.\nÉtape 6 Couvrir et cuire 25 min au four."]' where recette_id = '5ec9cf6f052aa7e7359de30c02ab0519';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 20 min Repos : - Cuisson : 15 min'', "Étape 1 Mettez de l''eau à chauffer dans une cocotte ou une grande casserole. Saler l''eau avec du gros sel.\nÉtape 2 Pendant que l''eau chauffe, coupez le choux, préalablement épluché, en quart, en huitième et ainsi de suite jusqu''à obtenir des lamelles grossières (pas trop fines).\nÉtape 3 Quand l''eau bout, faites blanchir le choux pendant 5 mn à partir du moment où l''au s''est remis en ébullition seulement de façon à ce qu''il garde une belle couleur vert-tendre.\nÉtape 4 Egouttez-le chou et passez-le à l''eau froide.\nÉtape 5 Faites revenir les lardons dans une poêle ou directement à la cocotte (attention, ne mettez ni beurre ni huile : le gras des lardons doit suffir à la cuisson et le plat sera plus diététique).\nÉtape 6 Puis quand ils sont bien dorés, ajoutez le chou et laissez-le dorer à feu vif également.\nÉtape 7 Le chou doit garder une bonne tenue et ne pas devenir mou.\nÉtape 8 Enfin, juste avant de servir, ajoutez un filet de crème et poivez selon votre goût."]' where recette_id = '234daca2adc4f88ff6a333962f89f22e';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 15 min Repos : - Cuisson : 20 min'', "Étape 1 Emincer les oignons et les champignons.\nÉtape 2 Fariner les côtes de veau et les faire dorer dans le beurre. Lorsqu''elles sont bien dorées, ajouter les champignons et les oignons.\nÉtape 3 Laisser cuire à petit feu à couvert pendant 20 minutes.\nÉtape 4 Faire chauffer le calvados dans une petite casserole puis le verser sur la viande et flamber.\nÉtape 5 Incorporer la crème, laisser réchauffer puis servir."]' where recette_id = '9c2560faac924ee88a0b49d184634735';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 5 min Repos : - Cuisson : 30 min'', "Étape 1 Mélanger dans un saladier tout les ingrédients, le citron, l''huile d''olive, le vinaigre balsamique et le miel.\nÉtape 2 Couper l''ail finement, l''ajouter à la marinade et mélanger.\nÉtape 3 Ajouter les blancs de poulet coupés en cubes.\nÉtape 4 Laisser mariner au moins 2h et plus si possible ! Voilà une marinade réalisée en moins de 5 minutes et délicieuse ! Elle est parfaite pour un barbecue et convient également pour une cuisson au four !"]' where recette_id = '0263f0970de564e045bb5c833f8ee215';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 25 min Repos : - Cuisson : 10 min'', "Étape 1 Couper les escalopes en 4 (si elles ne sont pas assez fines, les aplatir au rouleau à patisserie entre 2 feuilles de film alimentaire).\nÉtape 2 Mettre de la farine dans une assiette, l''oeuf battu avec sel et poivre dans une seconde assiette et enfin un mélange à parts égales parmesan râpé/chapelure dans une troisième assiette.\nÉtape 3 Passer les morceaux d''escalope dans la farine (enlever l''excédent de farine si besoin) puis dans l''oeuf battu et dans le mélange parmesan/chapelure.\nÉtape 4 Repasser une seconde fois les escalopes dans l''oeuf et dans le mélange chapelure/parmesan.\nÉtape 5 Mettre les escalopes au frigo pour 15 minutes (c''est très important sinon la croûte ne tiendra pas à la cuisson).\nÉtape 6 Couper les tomates épépinées en petits dés.\nÉtape 7 Les assaisoner d''huile d''olive, de sel et d''un filet de vinaigre balsamique.\nÉtape 8 Faire chauffer un mélange beurre/huile d''olive dans une poêle.\nÉtape 9 Quand la poêle est bien chaude, faire saisir les escalopes des 2 côtés.\nÉtape 10 Quand elles sont bien dorées, baisser le feu et laisser cuire encore 5 minutes.\nÉtape 11 Disposer les escalopes sur les assiettes.\nÉtape 12 Parsemer les dés de tomates (sans trop de jus) et décorer avec de la roquette.\nÉtape 13 Verser un filet de jus de citron et déguster."]' where recette_id = 'cd5959095cbf49fb0426113501ccdced';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 20 min Repos : - Cuisson : 15 min'', ''Étape 1 Saler et poivrer le filet des deux côtés. Le cuire à la poêle, 5 min de chaque côté. Laisser refroidir.\nÉtape 2 Faire revenir les oignons grossièrement hachés, les champignons en morceaux et les herbes dans de l’huile. Ensuite, hacher finement le mélange en duxelles.\nÉtape 3 Etaler la pâte feuilletée en une abaisse de 3 mm. Répartir la moitié de la duxelles de champignons, poser le filet dessus, puis le recouvrir du reste de duxelles. Refermer la pâte feuilletée sur le filet (souder les bords avec de l’eau), dorer avec un jaune d’oeuf battu.\nÉtape 4 Mettre cuire à four chaud (250°C) pendant 15 à 20 min, selon la cuisson désirée.\nÉtape 5 Servir avec une sauce au vin blanc et aux herbes.\nÉtape 6 Accompagnement : petits légumes, carottes, brocolis, pois mange-tout et croquettes de pommes de terre.\nÉtape 7 Pour les croquettes, cuire 1 kg de pommes de terre à l’eau, bien égoutter et sécher au four. Les réduire en purée. Ajouter 5 oeufs entiers, sel et poivre et 50 gr de farine. Façonner les croquettes à la main, puis rouler dans la farine, dans 1 oeuf entier battu et dans la chapelure. Faire frire à la poêle jusqu’à ce qu’elles soient dorées.'']' where recette_id = 'ceb154a306fe39fcc15ca2a9ce00f8b0';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 25 min Repos : - Cuisson : 10 min'', "Étape 1 Éplucher les pommes de terre et l''oignon et les râper finement. Il faut retirer l''excédent d''eau.\nÉtape 2 Ajouter la farine, l’œuf, un peu de sel et de poivre. Bien mélanger l''ensemble.\nÉtape 3 Dans une poêle, porter à ébullition un peu d''huile puis y déposer 4 cuillères à soupe de la préparation.\nÉtape 4 Faire bien dorer les galettes d''un côté, les retourner et laisser dorer sur l''autre face. Les sortir.\nÉtape 5 Recommencer jusqu''à épuisement de la pâte.\nDisposer les galettes sur un plat de service. Les servir bien chaudes avec une sauce aux champignons."]' where recette_id = 'c0b4407970999e598b59f72c81acc847';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 15 min Repos : - Cuisson : 20 min'', "Étape 1 Faire revenir les gambas, l''échalote et l''oignon hachés à feu vif dans de l''huile d''olive.\nÉtape 2 Flambez au Whisky ou au Cognac hors du feu.\nÉtape 3 Remettre à feu doux et mouiller avec le vin blanc, ajouter l''ail pilé, le persil haché, le coulis de tomate et la crème fraîche.\nÉtape 4 Saler et poivrer. Laisser mijoter à feu doux 20 min.\nÉtape 5 Servir avec du riz ou des pâtes."]' where recette_id = 'a533238c0a594c8e5b609458ba1fbdae';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 15 min Repos : - Cuisson : 20 min'', ''Étape 1 Faire bouillir de l\''eau en y ayant jeté préalablement le bouillon de volaille et un peu de sel.\nÉtape 2 Ajouter les crozets et laisser cuire environ 20 min.\nÉtape 3 Pendant ce temps, râper le Beaufort. Préchauffer le four à 200°C.\nÉtape 4 A la fin de la cuisson des crozets, les égoutter. Dans un plat à gratin, verser la moitié des crozets, poivrer, "émietter" grossièrement le jambon.\nÉtape 5 Ajouter la moitié du beaufort sur toute la surface.\nÉtape 6 Ajouter la crème fraîche en l\''étalant.\nÉtape 7 Ajouter le reste de crozets, poivrer.\nÉtape 8 Ajouter le reste de beaufort.\nÉtape 9 Enfourner jusqu\''à ce que le beaufort fonde'']' where recette_id = 'f1a488429dc71411eb07822f291afee6';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 20 min Repos : - Cuisson : 15 min'', "Étape 1 Il suffit de faire cuire le filet dans une casserole remplie d''eau et de lait par moitié. Faire frissonner pendant 10 minutes, servir avec un jus de citron et du beurrre frais !"]' where recette_id = '671d863588022ee3228630ae91bf6f09';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 5 min Repos : - Cuisson : 30 min'', ''Étape 1 Préchauffez le four à 250°C (thermostat 8).\nPoser les magrets (peau sur le dessus) dans un plat à four.\nÉtape 2 Mettre les magrets dans le four chaud pendant 15 min.\nÉtape 3 Sortir et retourner les magrets puis cuire 15 min à 180°C (thermostat 6).'']' where recette_id = 'cec5c31dbd2661e68506516101624f73';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 15 min Repos : - Cuisson : 20 min'', ''Étape 1 Faire revenir les oignons dans un grand faitout ou une cocotte-minute. Lorsqu’ils sont transparents, versez-les moules pour les faire ouvrir avec du vin blanc et du poivre.\nÉtape 2 Pendant ce temps, monter un roux avec le beurre et la farine.\nÉtape 3 Récupérez le jus des moules ouvertes en les conservant dans la cocotte pour les maintenir au chaud.\nÉtape 4 Délayer petit à petit le roux avec le jus des moules.\nÉtape 5 Ajoutez l’ail pilé et laissez épaissir.\nÉtape 6 Ajoutez la crème fraîche et le persil haché et laissez bien réchauffer pour lier le tout (la sauce ne doit pas bouillir).\nÉtape 7 Vérifier l’assaisonnement (attention au sel, les moules suffisent généralement à saler l’ensemble du plat).\nÉtape 8 Versez la sauce sur les moules.\nÉtape 9 Mélanger sur le feux environ 2 mn et servez aussitôt dans le plat de cuisson.\nÉtape 10 Plat à servir avec du riz, des pommes de terre ou bien encore de la semoule nature.'']' where recette_id = 'd26b42c34b7a915c66f95368e59389f8';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 20 min Repos : - Cuisson : 15 min'', "Étape 1 Faites revenir l''oignon haché dans une casserole ou une poêle.\nÉtape 2 Pendant ce temps faites cuire les pâtes, une fois celle-ci cuites, égouttez-les et rincez-les.\nÉtape 3 Quand les oignons sont bien dorés, ajoutez-y les crevettes, faites revenir 5 min puis ajoutez les tomates coupées en dés.\nÉtape 4 Laissez mijoter le tout 5 min puis ajoutez la crème fraiche puis salez et poivrez.\nÉtape 5 Ajoutez la garniture aux pâtes et laissez mijoter 5 min (si le plat est trop sec vous pouvez ajouter de la crème ou du lait).\nÉtape 6 Servez chaud et régalez vous !"]' where recette_id = 'b13dd944f18fa01e23723a09786d4ba9';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 15 min Repos : - Cuisson : 20 min'', "Étape 1 Epépinez et découpez le poivron en dés, pilez l''ail.\nÉtape 2 Hachez les oignons, faites-les suer dans l''huile chaude dans une sauteuse. Ajoutez le riz et remuez jusqu''à ce qu''il devienne transparent et légèrement coloré.\nÉtape 3 Mouillez avec 2 fois le volume du riz en eau (ou bouillon, ou fumet), salez, poivrez et ajoutez le poivron et l''ail. Portez à ébullition puis baissez le feu, couvrez et laissez mijoter 10 min.\nÉtape 4 Ajoutez les crevettes et laissez cuire encore 10 minu puis servez."]' where recette_id = '6c1b592d177a4b2e66d9cb71c2b3b857';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 20 min Repos : - Cuisson : 15 min'', "Étape 1 Rincer le riz à l''eau froide jusqu''à ce que l''eau qui s''écoule soit claire. Laisser égoutter.\nÉtape 2 Faire cuire le riz dans 15 cl d''eau : porter à ébullition 2 minutes et laisser gonfler 10 minutes à petit feu couvert. Laisser refroidir.\nÉtape 3 Faire bouillir le vinaigre de riz avec le sucre et le sel. Laisser refroidir. Incorporer l''assaisonnement au riz.\nÉtape 4 Emincer en fines et longues lamelles le concombre et l''avocat.\nÉtape 5 Etaler 1 cm de riz sur chacune des feuilles de nori.\nÉtape 6 Saupoudrer de graines de sésame.\nÉtape 7 Retourner la feuille de nori (pour que le riz se retrouve à l''extérieur du rouleau) et étaler un peu wasabi.\nÉtape 8 Garnir avec le concombre, l''avocat et le crabe, puis rouler pour former le rouleau (plus facile si vous poséder un makisu : natte de bambou à rouler).\nÉtape 9 Couper chaque rouleau en 8."]' where recette_id = '65d18568eb9f721c8b49be8dd7b7dac2';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 15 min Repos : - Cuisson : 20 min'', "Étape 1 Faire revenir l''oignon avec les épices et l''ail.\nÉtape 2 Quand l''oignon devient translucide, le retirer du feu et réserver.\nÉtape 3 Préchauffer le four à 210°C (thermostat 7).\nÉtape 4 Couper les pommes de terre en tranches d''environ1/2 centimètre et les frire légèrement.\nÉtape 5 Mettre la moitié des oignons dans un plat allant au four, mettre les 2 filets de truites par dessus (avec la peau vers le bas) et étaler par-dessus les pommes de terres frites et le reste de oignons.\nÉtape 6 Ajouter le vin blanc et le beurre.\nÉtape 7 Mettre au four à température maximum pendant une vingtaine de min."]' where recette_id = 'deada1269016ee595c85e906c6621598';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 5 min Repos : - Cuisson : 30 min'', "Étape 1 Préchauffer le four à 180°C - 200°C (Th 6-7), (la température sera moins élevée pour une cuisson à four ventilé et la cuisson plus rapide), nous recommandons cependant la cuisson traditionnelle.\nÉtape 2 Disposer dans le fond du plat à gratin les plaques de ravioles entières, saler et poivrer légèrement.\nÉtape 3 Recouvrir ensuite entièrement avec les courgettes coupées en rondelles peu épaisses, ajouter de la noix muscade râpée.\nÉtape 4 Verser la crème fleurette sur l''ensemble de la préparation.\nÉtape 5 Recouvrir le tout de fromage râpé.\nÉtape 6 Enfourner pour 30 mn à mi-hauteur.\nÉtape 7 Avant la fin de la cuisson faire gratiner légèrement le fromage râpé."]' where recette_id = 'c3b1a2dde673f5b47e7bc4ca95d95e2a';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 20 min Repos : - Cuisson : 15 min'', "Étape 1 Dans une jatte mélangez les cubes de poulet avec le gingembre, l''ail, le chili, la curcuma, le sel, le yaourt, le jus de citron et le coriandre ; couvrir et laissez mariner au moins 2h.\nÉtape 2 Mettre le poulet bien à plat dans un plat résistant à la chaleur et revêtu d''aluminium, et badigeonez avec l''huile. Réchauffez le grill du four à une chaleur moyenne et grillez le poulet pendant 15-20 mn en retournant les morceaux et badigeonnant avec l''huile 2-3 fois.\nÉtape 3 Servir dans un plat sur un lit de salade avec les quartiers de citron vert."]' where recette_id = '37b41da5b220f8366da1b533c4373d9e';
update fact_recette_base set etapes = '[''Préparation 35 min Préparation : 15 min Repos : - Cuisson : 20 min'', ''Étape 1 Faire sauter les champignons 7 mn à feu vif dans 10 g de beurre, saler, poivrer.\nÉtape 2 Mettre le restant de beurre (50 g) dans une sauteuse, quand il est très chaud, faire revenir le rognon coupé en fines tranches durant environ 15 mn.\nÉtape 3 Saupoudrer de farine, laisser blondir en remuant, mouiller avec le Madère, le bouillon, la moutarde, saler, poivrer, donner 1 bouillon.\nÉtape 4 Ajouter les champignons et le jus de cuisson, parsemer de persil.\nÉtape 5 Servir aussitôt.'']' where recette_id = '66c76c0119b4cb8297338e0869e5b889';
update fact_recette_base set etapes = '[''Préparation 38 min Préparation : 10 min Repos : - Cuisson : 28 min'', "Étape 1 Couper les poivrons en petits morceaux. Les faire frire à feux doux jusqu''à ce qu''ils soient presque cuits.\nÉtape 2 Pendant ce temps, couper également les oignons en petits morceaux. Les faire cuire.\nÉtape 3 Une fois qu''ils seront quasiment cuits, les ajouter aux poivrons puis continuer à faire cuire à toujours à feux doux.\nÉtape 4 Assaisonner : mettre sel et poivre, puis piment de cayenne selon vos goûts.\nÉtape 5 Couper le poulet en petits morceaux.\nÉtape 6 Retirer les poivrons et oignons du feu.\nÉtape 7 Faire cuire le poulet.\nÉtape 8 Une fois cuit ajouter le jus d''un citron ainsi que les oignons et les poivrons et laisser à feux doux quelques instants puis éteindre.\nÉtape 9 Au moment de servir, faire réchauffer le poulet. Couper les tomates en petits dés. Pour garnir les fajitas : mettre de la crème fraîche sur la pâte, du guacamole, quelques dés de tomate ainsi que quelques petits morceaux de salade. Rajouter de la préparation au poulet, rouler, manger ! ! !"]' where recette_id = '147464c4a0ebf083c4e9f83c98d100cd';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 5 min Repos : - Cuisson : 35 min'', "Étape 1 Coupez chaque aubergine en 2 dans le sens de la longueur (ne pas les éplucher). Zébrez la chair avec un couteau.\nÉtape 2 Tartinez d''une 1/2 cuillère d''huile d''olive la chair de chaque 1/2 aubergine.\nÉtape 3 Ajoutez les herbes, salez, poivrez.\nÉtape 4 Mettre au four à 200°C (thermostat 6-7) jusqu''à ce que la chair soit molle. Ce plat se mange ''à la coque'' avec une petite cuillère."]' where recette_id = 'a35eaaf00df62201de3add8f7797a168';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 15 min Repos : - Cuisson : 25 min'', "Étape 1 Préchauffer le four à 180°C (thermostat 6). \nHuiler un plat à four rectangulaire dont la diagonale correspond à la taille du poisson. \nDisposer sur cette diagonale la moitié du citron coupé en rondelles, poser le poisson dessus après lui avoir rempli le ventre de thym et laurier. \nRépartir le reste des tranches de citron sur le poisson.\nÉtape 2 De part et d''autre du poisson, mettre l''oignon en rondelles et les tomates coupées en deux, face bombée vers le dessus.\nÉtape 3 Saler, poivrer et arroser d''un filet d''huile d''olive.\nÉtape 4 Enfourner pour 10 mn, puis arroser avec le vin blanc et poursuivre la cuisson 10-15 mn.\nÉtape 5 Répartir le poisson, les tomates et oignons dans des assiettes chaudes, arroser du jus de cuisson."]' where recette_id = '90ffd134ad22f387bf93b1e3f4b9c478';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 30 min Repos : - Cuisson : 10 min'', "Étape 1 Tranchez de fines lamelles d''emmental afin de recouvrir la partie inférieure de votre pain à burger. Mettez ensuite au four sur le mode grill le temps de faire fondre le fromage.\nÉtape 2 Coupez l''oignon de manière à obtenir de fines et grandes lamelles. Coupez la tomate en grandes tranches également. Coupez 2 à 3 grandes feuilles de salade en lamelles fines et longues.\nÉtape 3 Hachez en tout petits morceaux les cornichons et mélangez-les à la mayonnaise préalablement préparée.\nÉtape 4 Mettez au four la partie supérieure de votre pain à burger.\nÉtape 5 Faites ensuite cuire à votre convenance votre steak haché dans une poêle avec du beurre ou de l''huile ou utilisez un grill. Assaisonnez généreusement en sel et poivre.\nÉtape 6 Sortez ensuite les deux parties de votre pain à burger. Disposez sur la partie avec le fromage fondu votre steak haché sur lequel vous allez étaler votre mayonnaise. Déposez ensuite une à deux grandes tranches de tomate puis la salade verte.\nÉtape 7 Sur la partie supérieure de votre pain, étaler du ketchup de manière à le recouvrir complètement, puis disposez vos lamelles d''oignons.\nÉtape 8 Refermez. Bon appétit !"]' where recette_id = '0c556c2f27bd7000aa2627a8f0800303';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 20 min Repos : - Cuisson : 20 min'', ''Étape 1 Eplucher (gratter) les carottes et couper-les en petites rondelles.\nÉtape 2 Dans une casserole, préparer un bouillon de poulet. La quantité d\''eau doit être suffisante pour recouvrir les carottes.\nÉtape 3 Dans une poêle, faire fondre le beurre puis, ajouter le sucre. Remuer jusqu\''à obtention d\''une légère "mousse", et ajouter les carottes. Remuer un peu puis, y ajouter le bouillon (les carottes doivent être recouvertes).\nÉtape 4 Laisser à petit feu sans couvrir afin de permettre à l\''eau de s\''évaporer pendant 20/25 minutes.'']' where recette_id = '70213abca7eabb45d5a24275f0687346';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 10 min Repos : - Cuisson : 30 min'', "Étape 1 Inciser l''écorce des châtaignes.\nÉtape 2 Faire bouillir une grande casserole d''eau salée avec le fenouil. Y plonger les châtaignes et laisser cuire à ébullition pendant 30 minutes.\nÉtape 3 Vérifier la cuisson, elles doivent s''éplucher facilement, tout en étant farineuses et fondantes.\nÉtape 4 Servir les châtaignes en accompagnement ou en plat."]' where recette_id = '639274a16d9fa096fe30eee49e09daf6';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 15 min Repos : - Cuisson : 25 min'', "Étape 1 Préchauffer le four (210°C).\nFaire décongeler les épinards suffisamment longtemps à l''avance. Préchauffer le four (210°C).\nÉtape 2 Mettre un peu de beurre dans un plat rectangulaire ou carré allant au four, puis une couche de lasagnes, une couche de saumon, une couche d''épinards et un peu de parmesan. Recommencer l''opération jusqu''à la fin des ingrédients.\nÉtape 3 Verser la crème liquide préalablement salée et poivrée.\nÉtape 4 Remettre un peu de parmesan puis cuire à four chaud pendant 25 mn."]' where recette_id = '485af202865eedca59f59a37d2aa5f2e';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 20 min Repos : - Cuisson : 20 min'', "Étape 1 Préparer une béchamel bien lisse. Saler, bien poivrer et mettre de la muscade.\nÉtape 2 Ajouter la ricotta dans la béchamel chaude et mélanger.\nÉtape 3 Beurrer un petit plat à gratin, couvrir d''une couche de lasagne, une couche d''épinards (bien salés, poivrés), une couche de béchamel et du gruyère râpé.\nÉtape 4 Puis à nouveau lasagnes, épinards, béchamel, et gruyère.\nÉtape 5 Faire une dernière couche.\nÉtape 6 Terminer par un peu de béchamel et recouvrir de gruyère (être généreux). Saupoudrer de muscade (Donc au total : 4 couches de lasagnes).\nÉtape 7 Mettre au four bien chaud 200°C pendant 20 min."]' where recette_id = '4fc36c60de093a5f74dbd85094cfe749';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 30 min Repos : - Cuisson : 10 min'', "Étape 1 - Coupez votre poulet en petits dés ou fines lamelles selon votre préférence.\nÉtape 2 - Préparez ensuite une marinade pour le poulet en mélangeant 3 cuillères à soupe de sauce nuoc mam (sauce de poisson) avec 3 cuillères à soupe de sauce soja et 1 cuillère à soupe de sucre roux.\nÉtape 3 - Ajoutez à cette préparation 2 gousses d''ail pressées et une pointe de gingembre en poudre (+/- 1/4 cuillère à café ou selon votre goût)\nÉtape 4 - Versez le poulet dans la marinade et laissez poser 1/2h au frais.\nÉtape 5 - Faites bouillir une grande casserole d''eau salée et faites y cuire les nouilles selon les indications du paquet (veillez à ce qu''elles soient fermes)\nÉtape 6 - Émincez une échalote\nÉtape 7 - Coupez le poivron en petits dés et le poireau en fines lamelles\nÉtape 8 - Dans un wok, faites chauffer 2 cuillères à soupe d''huile d''arachide. Une fois l''huile bien chaude, faites blanchir votre échalote et ajoutez le poulet mariné avec sa sauce.\nÉtape 9 - Faites sauter le poulet en remuant constamment jusqu''à ce qu''il prenne une belle teinte dorée.\nÉtape 10 - Une fois le poulet bien doré, ajoutez les légumes émincés et continuez de faire revenir quelques minutes (2-3 mn suffisent).\nÉtape 11 - Ajoutez les germes de soja selon votre goût\nÉtape 12 - Ajoutez les nouilles cuites dans le wok et faites sauter le tout une minute en mélangeant bien tous les ingrédients.\nÉtape 13 - Poivrez.\nÉtape 14 - Servez bien chaud dans des assiettes tiédies au four. Proposez à vos invités sauce soja pour accompagner voter plat."]' where recette_id = '718349f98fff7f272c4bafe1f1cc7938';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 5 min Repos : - Cuisson : 35 min'', "Étape 1 Couper les champignons et les oignons en lamelles.\nÉtape 2 Les faire revenir séparément dans l''huile d''olive.\nÉtape 3 Faire dorer les paupiettes a la poêle avec le beurre puis une fois dorées ajouter les oignons et les champignons. Mélanger.\nÉtape 4 Incorporer la crème fraiche, remuer, saler, poivrer.\nÉtape 5 Mettre le tout dans un plats a gratin puis mettre a cuire 15 min au four à 210°C (thermostat 7).\nÉtape 6 Bon appétit !"]' where recette_id = 'fe146ac4241b330f83e4bdc9b02a1e84';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 15 min Repos : - Cuisson : 25 min'', "Étape 1 Faire décongeler les épinards au micro-onde ou à la poêle.\nÉtape 2 Faire cuire le saumon (vapeur ou eau non salée).\nÉtape 3 Dans un saladier, casser les oeufs, ajouter la crème, le parmesan, le sel, poivre et un pincée de muscade (c''est l''appareil).\nÉtape 4 Disposer la pâte dans un moule.\nÉtape 5 Etaler les épinards puis le saumon cuit haché. Saupoudrer avec les herbes.\nÉtape 6 Verser l''appareil sur le saumon, saupoudrer de gruyère râpé (facultatif).\nÉtape 7 Faire cuire au four préchauffé (Th 9 four à gaz) pendant 25 à 30 mn jusqu''à ce que la quiche soit bien dorée."]' where recette_id = '8fa08494d1735e096c2466abd1a0be21';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 10 min Repos : - Cuisson : 30 min'', ''Étape 1 Mixez tous les ingrédients sauf le jambon, le découper en morceaux et mélanger ensuite avec le reste.\nÉtape 2 Placez dans un plat a tarte beurré et faites cuire une dmi-heure à 200°C.'']' where recette_id = '2e79e0ae9cb63657a1a1923c98b6fe07';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 20 min Repos : - Cuisson : 20 min'', "Étape 1 Laver les pommes de terre, et les faire cuire en robe des champs avec du sel.\nÉtape 2 Pendant que les pommes de terre cuisent, préparer le plat de fromage en coupant des tranches de la grandeur des poêlons.\nÉtape 3 Quand les pommes de terre sont cuites, enclencher l''appareil à raclette...\nÉtape 4 Chacun fait fondre son fromage dans le poêlon et le déguste ensuite avec une pomme de terre et les accompagnements de son choix."]' where recette_id = '5f46fdd16dd83a2d56298039cd66c5c2';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 10 min Repos : - Cuisson : 30 min'', "Étape 1 Pelez la gousse et coupez la en plusieurs lamelles\nÉtape 2 Piquez le rôti et glisser les lamelles\nÉtape 3 Badigeonnez le rôti de beurre ramolli\nÉtape 4 Saisir le rôti au four très chaud pendant 7 à 8 min, puis ramener la température à 220°C.\nÉtape 5 Laissez cuire pendant 20 à 25 min pour un rôti saignant (+4 min pour un rôti à point).\nÉtape 6 Salez et poivrez en fin de cuisson.\nÉtape 7 Arrêtez le four et laissez le rôti reposer 6 à 8 min en laissant la porte entre ouverte. Sortez le rôti, le découper en fines tranches, le déposer dans un plat chaud.\nÉtape 8 Dans le plat de cuisson, ajoutez un verre d''eau et grattez les sucs de cuisson.\nÉtape 9 Faites chauffer cette sauce sur une source de chaleur directe.\nÉtape 10 Plus qua napper les tranches de rosbeef ! \nBon appétit !"]' where recette_id = '93ee0ef2cc33c60712a85d14df45dddd';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 20 min Repos : - Cuisson : 20 min'', "Étape 1 Piquez les saucisses et mettez les dans l''eau bouillante pendant 10 mn, dans la même marmite qui vous servira à la préparation du plat afin de garder les saveurs.\nÉtape 2 Videz la marmite. Réservez les saucisses. Faites-y chauffer de l''huile d''olive.\nÉtape 3 Faites revenir les oignons émincés et l''ail écrasé sans qu''ils soient trop colorés.\nÉtape 4 Coupez les saucisses en troncons de 1,5 cm puis faites les revenir avec les oignons. Au bout de 5 mn, ajoutez les tomates coupées en petits morceaux et les aromates (le piment en morceaux).\nÉtape 5 Mélangez le tout puis laisser mijoter sur feu doux en ôtant le couvercle de temps à autre pour éliminer l''excès d''eau.\nÉtape 6 Servez avec du riz thai"]' where recette_id = '0d24902ad25d6cd260b4c7fb25665fd3';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 15 min Repos : - Cuisson : 25 min'', "Étape 1 Dans une poêle, faites revenir les morceaux de sauté de porc avec l''huile d''olive.\nÉtape 2 Pendant ce temps, éplucher les carottes et les couper en petites rondelles, émincer les oignons, puis faites les revenir dans la cocotte minute.\nÉtape 3 Une fois qu''ils commencent à dorer, ajouter l''eau et le vin blanc, puis le sauté de porc.\nÉtape 4 Refermer la cocotte et laisser cuire 25 min a partir du moment où la vapeur s''échappe.\nÉtape 5 Retirer le sauté de porc de la cocotte puis ajouter la moutarde et la crème épaisse. Bien mélanger le tout.\nÉtape 6 Ajouter doucement la faine et remuer pour faire épaissir la sauce.\nÉtape 7 Remettre le sauté de porc et couvrir 5 min pour que la viande s''imprègne de la sauce.\nÉtape 8 Servir avec des pommes de terres sautées ou des pâtes fraîches.\nBon appétit !"]' where recette_id = 'db27a60a75cede279d8112c00fce2fd3';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 20 min Repos : - Cuisson : 20 min'', "Étape 1 Mettre une casserole d''eau salée à bouillir.\nÉtape 2 Couper les carottes en rondelles puis les mettre à chauffer quand l''eau est bouillante pour faire une précuisson.\nÉtape 3 Émincer les oignons et écraser l''ail, les faire revenir dans sauteuse avec de l''huile d''olive.\nÉtape 4 Rincer plusieurs fois les lentilles. Les ajouter dans la sauteuse, puis le curry. Égoutter et ajouter les carottes pour qu''elles finissent leur cuisson, ajouter la coriandre, le sel et le poivre.\nÉtape 5 Recouvrir d''eau puis faites cuire environ 20 min à feu doux, en mélangeant de temps en autre.\nÉtape 6 Quand les lentilles et les carottes sont tendres, la soupe est prête à être mixée.\nÉtape 7 Au moment de servir, ajouter de 10 cl à 20 cl de lait de coco ou le laisser à disposition pour que chacun puisse doser selon son goût (plus ou moins sucré), il est aussi possible d''ajouter de la coriandre."]' where recette_id = 'a87e0cdbd5c95bc7bc7dfe5fd3c4e0fc';
update fact_recette_base set etapes = '[''Préparation 40 min Préparation : 25 min Repos : - Cuisson : 15 min'', "Étape 1 Couper le cheddar en petits cubes. Couper le pain en tranches bien épaisses. Faire en sorte qu’au niveau largeur elles passent dans les plats à welsh. Dans la limite du possible garder la croute des tartines.\nÉtape 2 Verser quelques goutes de bière sur chaque tartine (vraiment quelques gouttes, il faut garder environ 20 cl pour le reste de la recette). Puis les badigeonner d’un peu de moutarde (environ 2 cuillères à soupe) et les placer dans le fond des plats.\nÉtape 3 Poser sur chaque tartine une tranche de jambon recourbée sur elle-même.\nÉtape 4 Dans une grande sauteuse, faire fondre les cubes de cheddar sans ajouter de matière grasse.\nÉtape 5 Mélanger constamment à l’aide d’une cuillère en bois (ça fait des fils, c’est normal tant que ça n’attache pas à la sauteuse).\nÉtape 6 Quand la consistance est relativement homogène et qu’elle recouvre bien la cuillère quand on mélange, ajouter toute la bière et continuer à mélanger. Il faut remuer sans arrêt de façon à bien incorporer la bière au fromage.\nÉtape 7 Une fois le tout bien homogène et onctueux, ajouter le reste de la moutarde, un peu de poivre et remuer encore.\nÉtape 8 Quand la préparation est homogène, la verser dans les plats pour napper les tartines au jambon. Enfourner à 210°C (thermostat 7) pour une 10-12 minutes (il faut que ce soit bien doré).\nÉtape 9 Pendant ce temps cuire les 4 oeufs au plat dans une poêle (il est aussi possible de les faire au four, directement sur les Welshs, mais la cuisson du jaune est très délicate. C''est pourquoi à la poêle c''est très bien).\nÉtape 10 Quand le fromage est bien doré, sortir les plats du four, placer un oeuf au plat sur le dessus de chacun d’entre eux, tourner un coup de moulin à poivre et servir rapidement avec des frites et/ou de la salade verte. Et surtout une  bière !"]' where recette_id = 'fcd2b34d0774b85a24337e7ab4310c2f';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 10 min Repos : - Cuisson : 35 min'', "Étape 1 Préparer d''abord les choux de Bruxelles : les nettoyer, puis les laver en les plongeant dans plusieurs bains d''eau froide.\nÉtape 2 Les mettre ensuite à cuire 15 à 20 min dans une casserole d''eau bouillante salée. En fin de cuisson, les passer sous l''eau froide courante afin de les refroidir, puis les mettre à égoutter.\nÉtape 3 Détailler le lard en lardons.\nÉtape 4 Faire revenir les lardons dans une cocotte beurrée et les laisser rissoler.\nÉtape 5 Peler puis hacher les échalotes.\nÉtape 6 Jeter les échalotes dans la cocotte avec les lardons pour les faire colorer.\nÉtape 7 Ajouter enfin les choux de Bruxelles. Assaisonner en saupoudrant de sel, poivre et noix de muscade, et les faire revenir avec le reste de la préparation.\nÉtape 8 Bien remuer et servir immédiatement."]' where recette_id = 'ea277c15001fe1b01b95f72aebc11f24';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 30 min Repos : - Cuisson : 15 min'', "Étape 1 Prévoir un bon saladier plein de pâte à crêpe et les faire cuire à la poêle\nÉtape 2 Découper les divers ingrédients en lamelles, en faire 4 portions et les répartir dans chaque crêpe.\nÉtape 3 Les refermer (par exemple en pliage en 4 : déposer au centre les aliments, et refermer cette crêpe comme une enveloppe).\nÉtape 4 Mettre dans un plat adapté et faire chauffer au four à 150°C (thermostat 5) pendant environ 1 bon quart d''heure.\nÉtape 5 Servir les différentes crêpes avec de la salade verte."]' where recette_id = 'be4ba869d7374708cda4cefb1b5d2c51';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 10 min Repos : - Cuisson : 35 min'', "Étape 1 Faire préchauffer le four à 210°C (thermostat 7).\nDéposer les cuisses de poulet dans un plat allant au four.\nÉtape 2 Eplucher l''oignon, le couper en quatre. Le mettre dans le plat avec les cuisses. Ajouter, la gousse d''ail, le thym, les feuilles de laurier, le bouillon de cube coupé en quatre, les baies de genièvre, et le clou de girofle.\nÉtape 3 Ajouter l''eau. Arroser les cuisses d''huile d''olive.\nÉtape 4 Enfourner à 210°C pendant 35 minutes. Arroser les cuisses de temps en temps pendant la cuisson."]' where recette_id = 'dce7c43ed563bf20727cc3dc8600226a';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 15 min Repos : - Cuisson : 30 min'', "Étape 1 Dans une marmite faites revenir les diots dans un peu de beurre afin que ça roussisse, ensuite les retirer.\nÉtape 2 Dans le beurre faire revenir les oignons et échalote (feu fort au début, puis doucement).\nÉtape 3 Quand ceux-ci sont transparents ajouter la farine puis le vin blanc, puis le bouquet garni pour faire un roux, remuer jusqu''à ce que la sauce s''épaississe, puis ajouter les saucisses et laisser mijoter pendant 20 mn en remuant de temps en temps."]' where recette_id = '148063253c99dbb3f37cb70288f074a7';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 25 min Repos : - Cuisson : 20 min'', "Étape 1 La pâte : les Sud-Américains la font avec de la pâte à pain, mais c''est plus croustillant avec une pâte brisée.\nÉtape 2 La farce : faire revenir dans un peu d''huile d''olive les oignons émincés.\nÉtape 3 Ajouter la viande émincée elle-aussi, puis assaisonner.\nÉtape 4 Epaissir avec farine et bouillon puis ajouter les raisins.\nÉtape 5 Vérifier l''assaisonnement et parsemer de thym ou basilic en été ou selon le goût de persil ou autre.\nÉtape 6 L''assemblage : étaler la pâte sur 1/2 cm et y découper des ronds de la grandeur d''une soucoupe.\nÉtape 7 Mettre de la farce sur une moitié ainsi que des olives, mouiller les bords, replier et souder pour obtenir un chausson.\nÉtape 8 Faire une cheminée pour laisser échapper la vapeur. Eventuellement dorer à l''oeuf.\nÉtape 9 Cuire 20 minutes à four chaud (thermostat 8/240°C)."]' where recette_id = 'db372149ad7a0e0cbb2c3c6ee84f9d6b';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 15 min Repos : - Cuisson : 30 min'', "Étape 1 Préchauffer le four à 200°C (thermostat 6-7).\nÉtape 2 Huiler le fond d''un plat qui va au four avec l''huile d''olive.\nÉtape 3 Déposer les filets de lieu noir, saler et poivrer.\nÉtape 4 Dans un saladier, mélanger la crème, la moutarde et les herbes aromatiques.\nÉtape 5 Recouvrir les filets avec cette préparation de tel manière que l''on ne voit plus les filets.\nÉtape 6 Découper la petite tomate en dés et poser sur la préparation pour décorer.\nÉtape 7 Enfourner 30 minutes."]' where recette_id = 'b20d77cb280861b2d1a868349d7bc9ea';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 15 min Repos : - Cuisson : 30 min'', "Étape 1 Tout d''abord, coupez en morceaux vos filets mignon.\nÉtape 2 Faites revenir dans un plat les oignons émincés dans de l''huile d''olive à feu normal. Mélangez.\nÉtape 3 Une fois revenus, mettez les champignons de Paris émincés ainsi que le filet mignon préalablement coupé et laissez cuire toujours à feu normal.\nÉtape 4 Diluez le fond de veau dans un petit verre d''eau chaude puis incorporez-le. Mélangez.\nÉtape 5 Mettez la crème UHT, mélangez bien, portez le feu à pleine puissance jusqu’à ébullition de la crème pendant 1 à 2 min tout en mélangeant.\nÉtape 6 A feu doux, laissez mijoter 15 min environ."]' where recette_id = 'e0a6175fb189c1c7946598bc0f28063c';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 25 min Repos : - Cuisson : 20 min'', "Étape 1 Hacher l''oignon et l''ail.\nLes faire revenir dans le beurre jusqu''à ce qu''ils soient tendres.\nÉtape 2 Ajouter les tomates coupées en dés, la viande hachée, la farine, du sel, du poivre et les herbes de Provence.\nÉtape 3 Quand tout est cuit, couper le feu et ajouter le jaune d''oeuf et un peu de parmesan. Bien mélanger.\nÉtape 5 Préchauffer le four à 200°C (thermostat 6-7). \nEtaler au fond du plat à gratin. Préparer la purée. L''étaler au dessus de la viande. Saupoudrer de fromage râpé et faire gratiner."]' where recette_id = '8c7f46b92aa05c27039f68e03e835105';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 20 min Repos : - Cuisson : 25 min'', "Étape 1 Préchauffer le four sur 7 .\nÉtape 2 Dans une casserole, faire bouillir l''eau avec le beurre et le sel. A la première ébullition, retirer la casserole du feu et verser la farine d''un seul bloc ; tourner rapidement, puis dessécher la masse en la travaillant sur le feu avec une cuillère en bois jusqu''à ce qu''elle se détache complètement des parois et du fond de la casserole. Hors du feu, ajouter les oeufs, un par un, en travaillant chaque fois la préparation avec la cuillère en bois. La pâte terminée doit être molle, mais tenir en un seul bloc.\nÉtape 3 En faire des petits tas et les disposer sur une plaque recouverte de papier sulfurisé.\nÉtape 4 Faire cuire environ 25 min."]' where recette_id = '7019f829aa07485fcd539da71d4ca91d';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 30 min Repos : - Cuisson : 15 min'', "Étape 1 Faire chauffer un wok ou une grosse poêle.\nÉtape 2 Ajouter 1 cuillère d''huile, ajouter le basilic, le laisser frire pendant une minute.\nÉtape 3 L''enlever et l''essorer sur du papier.\nÉtape 4 Ajouter un autre cuillère d''huile à la poêle, faire revenir le poulet, ajouter le sel et le paprika, faire cuire pendant 4 à 5 minutes.\nÉtape 5 Ajouter les œufs et bien mélanger (ça doit ressembler à des œufs brouillés).\nÉtape 6 Enlever le tout et mettre dans un plat. Ajouter la dernière cuillère d''huile dans la poêle. Mettre l''ail, le vinaigre le nuoc nam et le sucre, faire cuire pendant 2 minutes.\nÉtape 7 Ajouter les pâtes (que vous avez fait cuire) dans cette sauce. Mettre le piment et les arachides, rajouter le poulet et les légumes au tout et bien mélanger.\nÉtape 8 Mettre le tout dans un plat, décorer avec le basilic frit et des tranches de citron."]' where recette_id = 'f03efa1b1c452e10724a6661136839a9';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 20 min Repos : - Cuisson : 25 min'', "Étape 1 Lavez et épluchez les pommes de terre, et mettez-les à cuire dans un grand volume d''eau salée.\nÉtape 2 Réchauffez les cuisses de canard au bain-marie pour les extraire de leur graisse.\nÉtape 3 Conservez une cuillère à soupe de graisse de canard.\nÉtape 4 Découpez et hachez grossièrement les cuisses confites (surtout pas de mixer !).\nÉtape 5 Emincer les échalotes et les oignons.\nÉtape 6 Dans une large poêle ou une sauteuse, faites blondir les oignons et les échalotes hachés dans la cuillère à soupe de graisse de canard, à feu très doux.\nÉtape 7 Lorsque ce mélange oignons + échalotes est bien blond, ajoutez le hachis de canard et mettez à feu vif, en mélangeant vivement, pendant 5 minutes. Le hachis de canard doit être finement grillé en surface, mais rester moelleux. Réservez hors du feu.\nÉtape 8 Ecrasez vos pommes de terre à la fourchette (pitié, pas de presse-purée !) et faites une purée moelleuse en ajoutant 50 % d''eau et 50 % de lait.\nÉtape 9 Salez, poivrez, ajoutez une pincée de muscade et la crème fraîche.\nÉtape 10 Préchauffez le four à 200°C (thermostat 6-7).\nÉtape 11 Dans un plat suffisamment haut, étalez la moitié de votre hachis de canard.\nÉtape 12 Mélangez la moitié qui reste avec le même volume de purée, et étalez cette deuxième couche sur la première. Finissez par une troisième couche de purée.\nÉtape 13 Striez le sommet de votre purée avec le dos d''une fourchette.\nÉtape 14 Laissez cuire à four chaud (200°C) pendant 25 min. Vous pouvez également finir la cuisson 3 minutes sous le gril pour obtenir un joli gratiné.\nÉtape 15 Servez avec une salade (mâche, par exemple) et un Cahors léger: ce plat ne paye pas de mine, mais vos convives seront très agréablement surpris !"]' where recette_id = '46b05f9d99a314b07792741b0bbea28b';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 15 min Repos : - Cuisson : 30 min'', "Étape 1 Dans une sauteuse, faire chauffer l''huile d''olive avec la gousse d''ail finement coupée, à feu moyen.\nÉtape 2 Lorsque c''est bien chaud, mettre les paupiettes à dorer quelques minutes de chaque côté.\nÉtape 3 Quand toutes les faces sont légèrement colorées, ajouter le fond de veau et mouiller avec le vin blanc et l''eau.\nÉtape 4 Ensuite mettre la moutarde, le vinaigre balsamique et bien mélanger en retournant les paupiettes pour qu''elles s''imbibent bien de la sauce.\nÉtape 5 Laisser cuire 5 minutes à feu moyen, pour que l''alcool du vin blanc s''évapore, puis mettre à feu doux et couvrir. Laisser mijoter 20 minutes environ, en retournant les paupiettes de temps en temps.\nÉtape 6 S''accommode avec toutes sortes de légumes ainsi que des féculents."]' where recette_id = 'c3f914490fa379671ca31138b737e94d';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 10 min Repos : - Cuisson : 35 min'', "Étape 1 Laver les poireaux et les couper en rondelles (tout le blanc et une partie du vert, environ 3 centimètres).\nÉtape 2 Faire fondre les poireaux dans une poêle avec l''huile, couvercle fermé, pour ne pas qu''ils grillent (environ 15 min).\nÉtape 3 Avant la fin de la cuisson, ajouter sel poivre et curry à sa guise.\nÉtape 4 Disposer ensuite ces poireaux dans un plat allant au four, les recouvrir des pavés de saumon, que l''on peut poivrer si l''on aime, et recouvrir le tout de crème fraîche.\nÉtape 5 Fermer le plat le plus hermétiquement possible avec un papier d''aluminium, et mettre au four à thermostat 6-7 (180°C/190°C), pendant environ 20 min, selon la grosseur du saumon.\nÉtape 6 Bon appétit!"]' where recette_id = '9d913851b7523ae06ead81e744478b09';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 15 min Repos : - Cuisson : 30 min'', "Étape 1 Le poulet:\nÉtape 2 Entailler les blancs de poulet. Badigeonner le poulet de jus de citron, d''ail émincé puis de paprika.\nÉtape 3 Préparer une marinade avec le yaourt et les 3 cuillères de Tandoori. Mettre les blancs dans la marinade, et laissez mariner dans le frigo de 30 min à 12h. (Plus le poulet marine, meilleur il est).\nÉtape 4 Quand le poulet a fini de mariner, préchauffer le four à 250°c (thermostat 8). Mettre une feuille d''aluminium sur la plaque du four. Laisser cuire le poulet 30 min pour des blancs épais. (Le temps de cuisson varie en fonction de l''épaisseur des blancs) en retournant à mi-cuisson.\nÉtape 5 Pendant ce temps, préparer la sauce:\nÉtape 6 Dans une poêle, mettre un filet d''huile puis les tomates en boite, le Tandoori, le miel, le beurre et la crème fraîche.\nÉtape 7 Quand le poulet est cuit, le couper en lamelles et l''incorporer à la sauce. Laisser mijoter quelque minutes.\nÉtape 8 C''est prêt !"]' where recette_id = 'c6124811ac7816bbbf7bb48552fe95aa';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 15 min Repos : - Cuisson : 30 min'', "Étape 1 Mélanger la farine et le sel dans un plat (et le sucre si sucre il y a).\nÉtape 2 Ajouter le beurre puis l''incorporer à la farine en pétrissant rapidement et légèrement du bout des doigts. On doit obtenir une sorte de semoule grossière en 2 ou 3 min.\nÉtape 3 Incorporer rapidement le lait ou l''eau. Il en faut très peu pour permettre à la pâte de se lier et de faire boule. Le lait ou l''eau ? C''est selon les goûts.\nÉtape 4 Pour étaler sans problème, étaler la pâte sur du papier cuisson et cuire tel quel dans la platine."]' where recette_id = '3dfaf18fb4d0e8d07fc8913bbd59cbc1';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 35 min Repos : - Cuisson : 10 min'', "Étape 1 Faire bouillir de l''eau (pour les ramens). Quand l''eau boue, y mettre les ramens pendant 3 min pas plus. Ensuite égoutter les ramens et les laisser dans leur plat avec un couvercle.\nÉtape 2 Faire bouillir 1.5 L d''eau avec les 2 cubes de bouillon.\nÉtape 3 En attendant que l''eau boue. Couper les steaks en morceaux carrés d''environ 2cm, les placer dans une assiette puis les recouvrir de sauce Yakitori pour les faire mariner avant de les mettre dans le bouillon.\nÉtape 4 Couper le chou, les échalotes, les oignons, la coriandre et le gingembre en petits morceaux.\nÉtape 5 Quand l''eau bout y mettre les ingrédients dans l''ordre suivant : La coriandre > le gingembre > les échalotes > les oignons >  le chou. (Entre chaque ingrédients attendre 1 min)\nÉtape 6 2 min après avoir mis le choux, mettre dans l''eau les 2 œufs et les morceaux de steak pour 3 min de cuisson. Après ces 3 min de cuisson le bouillon est prêt !\nÉtape 7 Dans une grande tasse ou un mug (20 cl), mettre une noisette de sauce harissa avec 2 cuillères à soupe de sauce soja, mettre de l''eau chaude puis mélanger le tout à la cuillère.\nÉtape 8 Verser le bouillon et la sauce sur les ramens et mélanger.\nÉtape 9 Ça y est, vos ramens au bœuf sont prêtes à être dégustées.\nÉtape 10 Bon appétit !"]' where recette_id = '0b4453472b37724df7158b2476d7cb63';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 3 min Repos : - Cuisson : 42 min'', "Étape 1 Faire tremper les ris de veau la veille pour les nettoyer et enlever les peaux plus facilement.\nÉtape 2 Le lendemain, blanchir environ 10 mn les ris de veau dans une casserole d''eau bouillante avec 1 bouillon cube.\nÉtape 3 Faire revenir les oignons dans un peu d''huile d''olive.\nÉtape 4 Ajouter les ris de veau égouttés et nettoyés. Faire revenir avec les oignons, saler et poivrer.\nÉtape 5 Ajouter les champignons, mélanger délicatement.\nÉtape 6 Saupoudrer de fond de veau et couvrir avec de l''eau. Laisser cuire environ 20 mn.\nÉtape 7 Retirer les ris et les champignons, mettre dans un plat de service. Faire réduire la sauce et ajouter la crème épaisse.\nÉtape 8 Rectifier l''assaisonnement et verser la sauce sur les ris et champignons. Bon appétit !"]' where recette_id = 'd7ee0946406f1fea1839ccd5884474b6';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 15 min Repos : - Cuisson : 30 min'', "Étape 1 Dénerver les rognons et les couper en petits morceaux.\nÉtape 2 Faire fondre le beurre dans une sauteuse et y faire saisir les rognons pendant 5 min.\nÉtape 3 Ajouter dans la sauteuse, les champignons et les échalotes émincées.\nÉtape 4 Saupoudrer le tout de farine et verser le porto. Couvrir et laisser mijoter doucement pendant 15 min.\nÉtape 5 Assaisonner de sel et de poivre. Mélanger la crème à la moutarde et l''ajouter aux rognons.\nÉtape 6 Laisser réduire un peu pendant 10 min te servir."]' where recette_id = 'bf4f77a4e380d87db4e0de88ef8e3495';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 15 min Repos : - Cuisson : 30 min'', ''Étape 1 Malaxer à la main la viande, la moutarde, la chapelure, l’œuf, le sel et le poivre. Former les steaks selon la taille et la forme désirée et les rouler dans la farine. Faire cuire à la poêle avec un peu d’huile.'']' where recette_id = 'bbb00d6626fbf69043eb8fbe6596e5fc';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 15 min Repos : - Cuisson : 30 min'', "Étape 1 Dans un premier temps, faire revenir dans une casserole avec un peu d''huile d''olive l''échalote et l''ail hachés finement.\nÉtape 2 Juste avant coloration, incorporer le vin blanc et porter à ébullition.\nÉtape 3 Ajouter alors les fruits de mer décongelés et baisser le feu. Mettre un peu de piment de Cayenne en poudre.\nÉtape 4 Dans un second temps, dissoudre le court-bouillon de poisson dans un peu d''eau (1 bol) que vous aurez fait bouillir.\nÉtape 5 Si vous avez choisi l''option crevettes, ajouter au bouillon les têtes  de crevettes et maintenir l''ébullition quelques minutes. Passer à la passoire et incorporer au mélange de fruits de mer.\nÉtape 6 Ajouter la crème fraîche et le parmesan et maintenir une ébullition faible pendant 10 min environ.\nÉtape 7 Pendant ce temps, faire cuire les pâtes, les égoutter et les mélanger à la préparation hors du feu.\nÉtape 8 Enfin, ajouter le persil haché et servir."]' where recette_id = 'd67da02487c390406f3bbc30a62fa5bd';
update fact_recette_base set etapes = '[''Préparation 45 min Préparation : 20 min Repos : - Cuisson : 25 min'', "Étape 1 Faire les oeufs durs.\nÉtape 2 Faire égoutter les épinards en boîte ou faire revenir dans un faitout les épinards surgelés.\nÉtape 3 Préparer la béchamel: faire fondre le beurre dans un casserole sans faire roussir, puis verser la farine et le lait et faire monter ; si la béchamel est trop liquide, mettre un peu de Maïzena puis ajouter la noix de muscade selon votre goût. Saler et poivrer.\nÉtape 4 Mettre les épinards au fond d''un plat à gratin et verser la béchamel, puis mélanger.\nÉtape 5 Incorporer les oeufs durs écalés.\nÉtape 6 Mettre du gruyère selon votre goût.\nÉtape 7 Mettre à four chaud à 200°C pendant 25 mn.\nÉtape 8 Et voilà c''est prêt!!!"]' where recette_id = 'b63aec66352ef77fd7dc298cc4152df6';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 25 min Repos : - Cuisson : 25 min'', "Étape 1 Préchauffer le four à 180°C (thermostat 6). Laver, essorer et ciseler l''aneth. Peler et émincer la gousse d''ail finement. Réserver.\nÉtape 2 Emincer les champignons après les avoir nettoyés.\nÉtape 3 Couper les tomates cerise en deux.\nÉtape 4 Déposer au centre de chaque feuille de papier cuisson un pavé de saumon,\nÉtape 5 ajouter les tomates\nÉtape 6 et les champignons tout autour.\nÉtape 7 Parsemer les pavés de saumon d''aneth et d''ail\nÉtape 8 et les arroser d''un filet de jus de citron.\nÉtape 9 Poivrer, saler et terminer par un filet d''huile d''olive.\nÉtape 10 Fermer les papillotes\nÉtape 11 et les mettre au four pendant 25 à 30 minutes.\nÉtape 12 Déguster."]' where recette_id = '717178a64f8aa02a2930c427226fa14e';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 20 min Repos : - Cuisson : 30 min'', "Étape 1 Faire fondre le bouillon dans de l''eau, dans une casserole, à feu doux. Ajouter le citron et le beurre. Porter à légère ébullition tout en mélangeant de temps en temps.\nÉtape 2 Disposer le poisson dans un plat allant au four, avec l''echalote coupée en rondelles.\nÉtape 3 Recouvrir le tout du mélange bouillon/eau/citron/beurre.\nÉtape 4 Faire cuire à 230°C (th 7-8), pendant 30 à 40 min."]' where recette_id = 'c86905072470b43c087b8e336e9ca561';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 10 min Repos : - Cuisson : 40 min'', "Étape 1 Faire cuire la courge spaghetti entière, 30 min dans une cocotte-minute ou 1h dans une casserole d''eau bouillante.\nÉtape 2 Une fois bien cuite, couper la courge en deux dans le sens de la longueur, enlever les graines et récupérer la chair à l''aide d''une fourchette. Laisser égoutter.\nÉtape 3 Dans un wok ou une poêle, faire revenir les lardons et les oignons.\nÉtape 4 Ajouter les spaghettis de courge et la crème. Saler et poivrer et enfin saupoudrer de parmesan.\nÉtape 5 Servir bien chaud."]' where recette_id = '8fee206f985fdeb1254cd92bb4296beb';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 30 min Repos : - Cuisson : 20 min'', "Étape 1 Épluchez les carottes et les navets puis coupez-les en morceaux de taille moyenne. Rincez la courgette et coupez-la en rondelles épaisses. Égouttez les pois chiches. Coupez les tomates en quartiers.\nÉtape 2 Versez 1 c. à café d’huile dans la cuve de votre Cookeo et faites cuire les merguez sur le mode « dorer » / 15 min + préchauffage en remuant constamment. Laissez tiédir puis réservez au frais. Essuyez sommairement la cuve.\nÉtape 3 Versez ensuite les 2 autres c. à café d’huile d’olive. Déposez les pilons de poulet, puis faites dorer sur le mode « dorer »  / 4 min + préchauffage en remuant constamment.\nÉtape 4 Versez 1 l d''eau et le cube de bouillon sur le poulet. Ajoutez le concentré de tomate, les carottes, navets et tomates, les épices à couscous et l’harissa. Lancez la cuisson sur le mode « cuisson sous pression » / 10 min.\nÉtape 5 Ajoutez les courgettes et les pois chiches, puis relancez la cuisson sur le mode « cuisson sous pression » / 10 min.\nÉtape 6 Déposez les merguez au-dessus de la préparation pour les réchauffer. Salez et poivrez, mélangez et refermez la cuve pendant une dizaine de minutes, robot éteint. Pendant ce temps, préparez à votre convenance un saladier de semoule en grains."]' where recette_id = 'ff3866dfcee38e02bedbf67320a128a2';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 10 min Repos : - Cuisson : 40 min'', "Étape 1 Faire cuire les crozets dans l''eau bouillante salée pendant 20 minutes.\nÉtape 2 Au bout de 10 minutes de cuisson des crozets, couper l''oignon et le faire revenir dans du beurre. Faites-la caraméliser.\nÉtape 3 Mettre les oignons de coté et faire revenir les lardons.\nÉtape 4 Mettre les oignons cuits lardons crème dans la poêle et faire réduire.\nÉtape 5 Égoutter les crozets.\nÉtape 6 Mettre dans le plat à gratin une couche de crozet, une couche de crème/lardons/oignons.\nÉtape 7 Remplir le plat de cette manière et mettre au-dessus le reblochon coupé en 2.\nÉtape 8 Faire cuire au four pendant 20 minutes à 200°C."]' where recette_id = 'afe87c043317f21b16894afef9aaf2bc';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 20 min Repos : - Cuisson : 30 min'', "Étape 1 Détaillez le chou romanesco en bouquets et faites-le cuire 5 min à l''autocuiseur.\nÉtape 2 Préparez votre béchamel en faisant fondre le beurre à feu doux, puis en versant dedans la farine en pluie.\nÉtape 3 Laissez cuire à feu doux 2 min en remuant sans arrêt.\nÉtape 4 Retirez du feu et versez le lait froid, petit à petit.\nÉtape 5 Remettez à feu doux et toujours en remuant, faites chauffer jusqu''à l''épaississement souhaité (environ 5 min).\nÉtape 6 Ajoutez du sel, du poivre et la muscade.\nÉtape 7 Faites revenir vos pignons dans une poêle chaude, sans ajout de matières grasses jusqu''à ce qu''ils soient dorés.\nÉtape 8 Mettez votre four à préchauffer à 210°C, thermostat 7.\nÉtape 9 Dans un plat à gratin, versez les bouquets de chou, la béchamel, les pignons de pin puis le parmesan.\nÉtape 10 Faites cuire 25 min au four et dégustez."]' where recette_id = '03c2bb7b5ac76f727cc760b017669eee';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 20 min Repos : - Cuisson : 30 min'', "Étape 1 Faire cuire le chou-fleur dans l''eau bouillante salée 10 mn.\nÉtape 2 Faire une sauce béchamel : dans une casserole, faire fondre le beurre et y ajouter la farine. on fait un roux avec le fouet et on ajoute le lait petit à petit en faisant réduire la sauce.\nÉtape 3 On ajoute noix de muscade, sel et poivre pour l''assaisonnement.\nÉtape 4 Dans un plat à gratin, on fait une couche de chou-fleur, une couche de lardons, une autre couche de choux, on ajoute la sauce par dessus, puis enfin du gruyère pour gratiner le tout.\nÉtape 5 Mettre dans un four chaud pendant 30 mn."]' where recette_id = '6a9e55aa2e11f078638609bc7bb9162d';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 20 min Repos : - Cuisson : 30 min'', "Étape 1 C''est une recette facile et pratique pour les mamans ainsi qu''un plat unique pour l''hiver et pas cher à réaliser.\nÉtape 2 Eplucher et couper les pommes de terres en 4, les carottes en tronçons de 1 cm.\nÉtape 3 Dans une cocotte-minute, faire revenir l''oignon émincé ainsi que 2 gousses d''ails (si vous aimez l''ail) avec les lardons ou les chipolatas dans un fond d''huile tournesol ou d''olive.\nÉtape 4 Ensuite, une fois que ces légumes sont un peu cuits, ajouter les pommes de terre, les carottes, les haricots verts. Faire de nouveau revenir un peu, saler et poivrer. Puis couvrir de moitié d''eau en ajoutant le concentré de tomates, le cube de bouillon émietté et le beurre.\nÉtape 5 Fermer la cocotte et laisser cuire environ 15 à 20 min à partir du moment où la cocotte chuchote.\nÉtape 6 En fin de cuisson, ouvrir la cocotte et rajouter les petits pois et laisser cuire encore 5 minutes sans couvercle."]' where recette_id = '369c508b076cbe9df0a7917727b8a557';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 10 min Repos : - Cuisson : 40 min'', "Étape 1 Découper le porc en bouchées.\nÉtape 2 Faire chauffer 50 cl d''eau. Ajouter les deux cubes de bouillon de poule, 1 cuillère à soupe de gingembre moulu, 1 cuillère à soupe de mélange quatre épices et 3 cuillères à soupe de sauce soja.\nÉtape 3 Dans une sauteuse, préparez votre caramel avec le sucre et l''eau.\nÉtape 4 Une fois le caramel prêt, ajouter le bouillon et tourner très vite pour faire dissoudre le caramel (qui va se durcir) dans le bouillon.\nÉtape 5 Une fois le caramel dissout, rajouter la viande et l''oignon coupé en gros morceaux et mettre à feu très vif. Laisser réduire jusqu''à ce que tout le liquide se soit évaporé (environ 25 min) et que la viande se mêle au mélange épais caramel-épices.\nÉtape 6 Déguster !"]' where recette_id = 'db655158e0dfb7368fa529f8482e638d';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 20 min Repos : - Cuisson : 30 min'', "Étape 1 Etaler la pâte dans un moule à tarte et tapisser le fond de râpé.\nÉtape 2 Faire revenir les lardons (sans les faire dorer) et étaler les sur le râpé.\nÉtape 3 Battre les 3 oeufs, ajouter la crème fraîche et assaisonner.\nÉtape 5 Verser le mélange sur les lardons et recouvrer de râpé.\nÉtape 6 Faire cuire environ 30 min, th.6 (180°) : jusqu''à ce que le râpé soit fondu et légèrement doré."]' where recette_id = '0a563eedb710fe759f6631012a2415a1';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 20 min Repos : - Cuisson : 30 min'', "Étape 1 Faire cuire le riz et le rincer à l''eau froide.\nÉtape 2 Couper le jambon en dés, émincer finement les oignons. Mettre à chauffer 1 cuillère d''huile dans une poêle et faire revenir l''oignon avec les petits pois (3 mn). Verser le mélange dans un plat.\nÉtape 3 Faire une omelette et la couper en lanières.\nÉtape 4 Mettre à chauffer 1 cuillère d''huile et faire revenir 1 mn les crevettes.\nÉtape 5 Ajouter le riz, petits pois, oignons, jambon, omelette. Saler et poivrer.\nÉtape 6 Faire chauffer 3 mn en remuant sans cesse. Servir très chaud"]' where recette_id = '3680ffaec21ed229a6984d51efcbcf4c';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 10 min Repos : - Cuisson : 40 min'', ''Étape 1 Coupez le rôti en quatre. Pelez et émincez les oignons en rondelles épaisses. Pelez et pressez l’ail.\nÉtape 2 Dans un bol, mélangez le miel, l’ail, la moutarde et le poivre. Badigeonnez les morceaux de rôti à l’aide de ce mélange puis déposez-le dans la cuve de votre Cookeo.\nÉtape 3 Arrosez avec 25 cl d’eau, puis émiettez le bouillon sur la préparation. Ajoutez les oignons et lancez la cuisson sur le mode « cuisson sous pression » / 40 min. \nServez accompagné d’une salade de pommes de terre primeur ou de crudités.'']' where recette_id = '0660cce887196b4513cc2c30f807f977';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 5 min Repos : - Cuisson : 45 min'', "Étape 1 Préchauffer le four à 210°C (thermostat 7) pendant 10 min.\nÉtape 2 Pendant ce temps, mettre le rôti lardé par votre boucher dans un plat à four à bord haut. Verser l''huile, mettre le beurre en noisette sur la viande et mettre l''eau et l''ail sur le côté de la viande. Saler et poivrer.\nÉtape 3 Mettre au four pendant 45 min environ. Au bout de 25 à 30 min, et régulièrement, sortir le rôti du four pour le mouiller avec le jus de cuisson et ajouter un peu d''eau le cas échéant. Au bout de 45 min votre rôti doit être bien cuit à cœur, doré sur le dessus et très tendre."]' where recette_id = '87276cc539d9a67b245ed7ed9525532b';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 20 min Repos : - Cuisson : 30 min'', "Étape 1 Faire fondre le beurre dans une cocotte minute, y faire dorer le rôti de toutes parts, puis ajouter l''oignon émincé, le sel et le poivre.\nÉtape 2 Délayer dans un bol le fond de veau, les herbes, le basilic, le vin blanc et 1 verre d''eau. Verser ce mélange dans la cocotte, ainsi que les champignons lavées et coupés en quartiers et remuer.\nÉtape 3 Fermer la cocotte et laisser chuchoter environ 30 min par kg.\nÉtape 4 Cette recette est aussi délicieuse que rapide!"]' where recette_id = '2c973dfadd20352e1eb0ab192f8ea0c7';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 20 min Repos : - Cuisson : 30 min'', "Étape 1 Faites cuire les pommes de terre dans de l''eau bouillante salée et poivrée pendant 30 minutes.\nÉtape 2 Après 30 minutes de cuisson, vérifiez avec la pointe d''une fouchette si les pommes de terre sont tendres ou non.\nÉtape 3 Si elles sont tendres, arrêtez la cuisson, sinon laissez cuire encore 5 à 10 minutes.\nÉtape 4 Une fois cuites, passez les pommes de terre immédiatement sous l''eau froide pendant 3 bonnes minutes et ensuite, la peau devrait se décoller très facilement. Sinon, pelez-les à l''aide d''un éplucheur.\nÉtape 5 Découpez ensuite les pommes de terre en gros dés et réservez-les dans un grand bol.\nÉtape 6 Pendant la cuisson, pelez et émincez l''oignon et l''échalote. Découpez les cornichons en rondelles. Réservez le tout dans un bol pour la suite.\nÉtape 7 Préparez la sauce avec l''huile, le vinaigre, la moutarde, le sel et poivre.\nÉtape 8 Mélangez les pommes de terre avec la préparation oignon-échalote-cornichons et ajoutez toute la sauce en mélangeant délicatement.\nÉtape 9 Laissez le tout refroidir au frigo pendant minimum 1h.\nÉtape 10 Une fois le mélange bien frais, préparez une deuxième portion de sauce et arrosez le tout en mélangeant afin que les pommes de terres soient bien imbibées de sauce."]' where recette_id = '93f8af963c505ebff755a60dcc47b12b';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 10 min Repos : - Cuisson : 40 min'', "Étape 1 Préchauffer le four à thermostat 5 (150°C).\nÉtape 2 Battre les oeufs avec 2 pincées de sel. Ajouter le verre de crème et bien mélanger. Incorporer la farine mélangée à la levure chimique.\nÉtape 3 Beurrer ou chemiser un moule à cake (avec du papier sulfurisé), déposer un tiers de la pâte, poser le saucisson dessus (ne pas le piquer à la fouchette sous peine de voir s''échapper le gras!), puis le recouvrir de la pâte restante.\nÉtape 4 Cuire au four à thermostat 5 pendant 40 mn."]' where recette_id = '90a06446142d56f68b77508e1c35e18b';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 20 min Repos : - Cuisson : 30 min'', "Étape 1 Laver et couper les légumes en morceaux (de la grosseur de votre choix).\nÉtape 2 Faire bouillir 3 litres d''eau. Y jeter les légumes coupés, assaisonner, puis baisser le feu pour faire cuire à feu doux.\nÉtape 3 Mixer les légumes.\nÉtape 4 Cette soupe pourra être consommée chaude ou froide, suivant les préférences."]' where recette_id = '966b0be5c5dcf57626413b7c009051bf';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 20 min Repos : - Cuisson : 30 min'', "Étape 1 Porter le bouillon à ébullition.\nÉtape 2 Incorporer les courgettes et les pommes de terre épluchées et coupées.\nÉtape 3 Lorsque les légumes sont cuits (au bout de 20 minutes environ), enlever l''eau en surplus pour ne pas que la soupe soit trop liquide.\nÉtape 4 Mixer les légumes en ajoutant la crème fraiche et le kiri ou le gruyère.\nÉtape 5 Réchauffer un peu la soupe pour l''épaissir si elle est trop liquide."]' where recette_id = '576d83ba39a875d073b74a9a5734e59f';
update fact_recette_base set etapes = '[''Préparation 50 min Préparation : 5 min Repos : - Cuisson : 45 min'', ''Étape 1 Découpez les travers en 4.\nÉtape 2 Mélangez tous les ingrédients et faites mariner la viande dedans au moins 30 min.\nÉtape 3 Egouttez et faites cuire les travers 45 min au four à 180°C (thermostat 6) ou au barbecue (ou grill) en arrosant de temps en temps avec la marinade.\nÉtape 4 Retournez-les à mi-cuisson.'']' where recette_id = 'e73022f66925ad75b946930133df1b99';
update fact_recette_base set etapes = '[''Préparation 55 min Préparation : 15 min Repos : - Cuisson : 40 min'', "Étape 1 Chauffer l''huile dans une casserole ou une cocotte\nÉtape 2 y faire revenir les oignons et l''ail, remuer.\nÉtape 3 Ajouter les épices et remuer.\nÉtape 4 Ajouter les tomates avec leur jus.\nÉtape 5 puis les pois chiches. Mélanger.\nÉtape 6 Couvrir et laisser mijoter 20 min à feu doux.\nÉtape 7 Saler, ajouter le guaram massala, remuer et prolonger la cuisson de 20 min.\nÉtape 8 Servir très chaud avec des naans ou des chapatis."]' where recette_id = '16c2a4855e44c0f361bdfe9d5f628a2c';
update fact_recette_base set etapes = '[''Préparation 55 min Préparation : 10 min Repos : - Cuisson : 45 min'', "Étape 1 Préchauffer le four à 220°C (thermostat 7-8). Mettre de la moutarde sur les deux faces des côtes de porc. Les saler et les poivrer.\nÉtape 2 Huiler un plat allant au four.\nÉtape 3 Disposer les côtelettes les unes à côté des autres puis les recouvrir légerement de thym et d''oignons surgelés (On peut très bien utliser des oignons frais mais ils ont tendance à brûler un peu).\nÉtape 4 Ensuite, faire couler un peu d''huile olive et mettre au four pendant 45 min."]' where recette_id = '9887eb93f4cefff6959e2d55250114de';
update fact_recette_base set etapes = '[''Préparation 55 min Préparation : 10 min Repos : - Cuisson : 45 min'', "Étape 1 Faire chauffer le four Th 7/8. Préparer le gigot en enlevant, à l''aide d''un couteau, le gras de la viande de façon à ce que la chair soit à vif.\nÉtape 2 Faire une pommade avec la graisse, l''ail écrasé, le romarin effeuillé et le gros sel.\nÉtape 3 Faire pénétrer cette pommade dans la chair en massant le gigot.\nÉtape 4 Mettre au four et arroser tous les 1/4 d''heure avec un mélange d''eau chaude et de graisse.\nÉtape 5 Pour ceux qui aiment l''ail confit : pensez à mettre au fond du plat quelques gousses d''ail non épluchées."]' where recette_id = 'ca729e9441bfcc03a29f0ce550277bc5';
update fact_recette_base set etapes = '[''Préparation 55 min Préparation : 10 min Repos : - Cuisson : 45 min'', "Étape 1 Préchauffer le four à 180°C / Ther 6.\nÉtape 2 Eplucher les pommes de terre, ou laisser la peau si elle est fine.\nÉtape 3 Les couper dans le sens de la longueur et les placer sur une plaque au four, face bombée contre la plaque. Saler et laisser cuire à four chaud jusqu''à ce que le dessus soit bien doré.\nÉtape 4 Servir chaud accompagnées de salade verte et de toutes sortes de fromages (du kiri pour les enfants en allant jusqu''au maroilles...).\nÉtape 5 C''est délicieux, économique et sans graisse. Délicieux avec de la cancoillotte !"]' where recette_id = 'd9724deb7bc8ea27c6c6213513e09e10';
update fact_recette_base set etapes = '[''Préparation 55 min Préparation : 10 min Repos : - Cuisson : 45 min'', "Étape 1 Dégraisser un peu la viande. La recouvrir d''eau froide agrémentée du bouquet garni, de l’oignon épluché, de la tête d’ail et de gros sel.\nÉtape 2 Cuire en pression 30 min.\nÉtape 3 Pendant ce temps, éplucher les légumes. Vider la vapeur et ajouter les légumes hormis les pommes de terre.\nÉtape 4 Cuire en pression 5 mn.\nÉtape 5 Vider à nouveau la vapeur et ajouter les pommes de terre. Cuire en pression 10 mn. C’est prêt !"]' where recette_id = '3933b54b3541be6a094a23dca6758055';
update fact_recette_base set etapes = '[''Préparation 55 min Préparation : 15 min Repos : - Cuisson : 40 min'', "Étape 1 Couper le chou en 4 et tirer les feuilles.\nÉtape 2 Couper les carottes en rondelles et les pommes de terre en morceaux.\nÉtape 3 Faire blanchir le chou à gros bouillons pendant 10 minutes.\nÉtape 4 Faire frire l''oignon avec la matière grasse dans une cocotte, y ajouter les feuilles de chou, les carottes, les pommes de terre, le lard, les saucisses, l''ail haché, le persil, du sel et du poivre.\nÉtape 5 Verser de l''eau jusqu''à mi-hauteur.\nÉtape 6 Compter 30 minutes de cuisson à partir de la rotation de la soupape puis ouvrir et laisser mijoter 10 minutes supplémentaires."]' where recette_id = 'f1ba91eda3edc3ac925207b6bde578c3';
update fact_recette_base set etapes = '[''Préparation 55 min Préparation : 10 min Repos : - Cuisson : 45 min'', "Étape 1 Préchauffer le four à 180°C (thermostat 6).\n\nEtaler la pâte dans un moule,\nÉtape 2 la piquer à la fourchette. Parsemer de copeaux de beurre.\nÉtape 3 Faire rissoler les lardons à la poêle puis les éponger avec une feuille d''essuie-tout.\nÉtape 4 Battre les oeufs, la crème fraîche et le lait.\nÉtape 5 Ajouter les lardons.\nÉtape 6 Assaisonner de sel, de poivre et de muscade.\nÉtape 7 Verser sur la pâte.\nÉtape 8 Cuire 45 à 50 min.\nÉtape 9 C''est prêt\nÉtape 10 Déguster"]' where recette_id = '1452312ba4b4b08c162dc0c4a86d3339';
update fact_recette_base set etapes = '[''Préparation 55 min Préparation : 20 min Repos : - Cuisson : 35 min'', ''Étape 1 Etalez la pâte dans le moule beurré et fariné.\nÉtape 2 Nettoyez puis émincez les blancs des 3 poireaux.\nÉtape 3 Faites dorer les lardons dont vous utiliserez la graisse pour faire revenir les poireaux ensuite.\nÉtape 4 Répartissez lardons et poireaux sur le fond de tarte.\nÉtape 5 Préchauffez le four à 180°C ( Th 6).\nÉtape 6 Dans un bol battez les oeufs, la crème et le lait. Assaisonnez à votre goût puis versez le mélange dans la tarte.\nÉtape 7 Découper le fromage de chèvre en rondelles que vous déposerez sur la quiche.\nÉtape 8 Cuisez au four de 25 à 30 mn.'']' where recette_id = '586aa8094a5edba91f25e909f2b15897';
update fact_recette_base set etapes = '[''Préparation 55 min Préparation : 10 min Repos : - Cuisson : 45 min'', ''Étape 1 Préchauffez le four à 220 °C (th.6).\nÉtape 2 Épluchez les pommes de terre et émincez-les en  fines rondelles. Placez votre saucisse de Morteau dans un plat à gratin. Recouvrez-la de pommes de terre. Salez et poivrez. Aromatisez avec du romarin.\nÉtape 3 Placez au four 25 min. Quand les pommes de terre commencent à dorer, retirez du four et mettez la crème liquide. Replacez au four et laissez ensuite cuire environ 20 minutes.\nÉtape 4 Servez chaud.'']' where recette_id = '712ca2fd6d29e46cfe98cb62aa6e4166';
update fact_recette_base set etapes = '[''Préparation 55 min Préparation : 10 min Repos : - Cuisson : 45 min'', "Étape 1 Piquer les saucisses avec une fourchette.\nÉtape 2 Après mettez-les dans 1,5 litre d''eau froide, avec le bouquet garni et la carotte coupée en rondelles. Faites cuire à gros bouillons pendant 15 à 20 min.\nÉtape 3 Pendant ce temps, faites revenir les lardons dans une poêle, juste pour qu''ils soient légèrement dorés et croquants.\nÉtape 4 Ajoutez les lardons, les oignons blancs et les lentilles dans le faitout des saucisses. Ne salez pas, les lardons le feront.\nÉtape 5 Couvrez et faites cuire le tout à feu doux de 20 à 25 min.\nÉtape 6 Égouttez, retirez le bouquet garni, disposez sur un plat avec un peu de persil haché et servez aussitôt."]' where recette_id = 'be6245a5e9deeb86fa238eb3461e8ba2';
update fact_recette_base set etapes = '[''Préparation 55 min Préparation : 10 min Repos : - Cuisson : 45 min'', "Étape 1 Précuire la pâte (percée avec une fourchette) 5 min à 450 degrés farenheit (230°C).\nÉtape 2 Pendant ce temps, couper les tomates en rondelles de 3 mm d''épaisseur.\nÉtape 3 Sortir la pâte précuite du four. badigeonner le fond de moutarde de Dijon (la classique fait l''affaire) ...en mettre suffisamment pour que le fond en pâte ne se voit plus.\nÉtape 4 Disposer les tranches de tomates. faire plusieurs épaisseurs.\nÉtape 5 saupoudrer d''herbes de Provence + 2 pincées de sel.\nÉtape 6 1 cuillère à soupe d''huile d''olive.\nÉtape 7 Enfourner pour 20 min à 450 farenheit puis couvrir avec papier d''aluminium pour 20 min supplémentaires. Après ces 20 min, enlever le papier aluminium et laisser cuire encore 5 min porte du four ouverte. \nDélicieux avec une salade verte."]' where recette_id = '8e0d9c4c97e6670c7ccd2f9ffdd83092';
update fact_recette_base set etapes = '[''Préparation 55 min Préparation : 15 min Repos : - Cuisson : 40 min'', "Étape 1 Couper les blancs de poulet en petits morceaux.\nÉtape 2 Laver vos champignons (rapidement et plusieurs fois), éplucher la tête et couper en petits morceaux.\nÉtape 3 Faire cuire le poulet dans un peu de beurre, bien saler et remuer sans cesse. Vers la fin de la cuisson, ajouter un peu de beurre et les champignons.\nÉtape 4 Faire cuire le riz. (ou la purée si vous préférez)\nÉtape 5 Faire un roux avec la farine et le beurre. Pour cela, préparer 1/2  litre de bouillon de poule (mettre un bouillon dans 1/2 litre d''eau bouillante) et du jus de citron.\nÉtape 6 Dans un poêlon, mettre le beurre, attendre qu''il fonde un peu puis, ajouter la farine et mélanger doucement pour ne pas faire de grumeaux.\nÉtape 7 Rajouter petit à petit le bouillon (la sauce va s''épaissir), puis un peu de jus de citron, du sel, un peu de poivre et goûter.\nÉtape 8 Une fois la viande et les champignons cuits, couper le feu et rajouter la sauce.\nÉtape 9 Remplir les bouchées de la préparation et mettre au four 10 min.\nÉtape 10 Servir la garniture qu''il reste dans un bol et manger avec le riz ou la purée."]' where recette_id = '6da7f7d4a0485504d4e39cc14e43e29d';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 30 min Repos : - Cuisson : 30 min'', ''Étape 2 Faites cuire les pommes de terre épluchées pendant 25 à 30 min dans une casserole d\''eau. Egouttez.\nRéduisez-les ensuite une purée et assaisonnez avec le beurre, la crème, l\''ail pilé, très peu de sel et du poivre.\nÉtape 3 Détaillez le fromage en très fines lamelles. Sur feu doux, ajoutez le fromage à la purée.\nÉtape 4 Pendant au moins 15 min, battez la masse avec une grande cuillère en bois, en formant des "huit", et en la soulevant jusqu\''à obtenir une pâte lisse qui se détache des parois de la casserole et qui file.\nÉtape 5 Servez dans chaque assiette : soulevez un grand ruban d\''aligot et coupez-le au ciseau.'']' where recette_id = '6a093789059b4610df6dc3153be2175f';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 20 min Repos : - Cuisson : 40 min'', "Étape 1 Coupez les champignons en lamelles et les quenelles égouttées en petits tronçons.\nÉtape 2 Coupez la viande en petits dés et cuisez la rapidement (rose). Réservez.\nÉtape 3 Faites fondre le beurre dans un faitout, ajoutez la farine et faites cuire en remuant pendant 3 mn.\nÉtape 4 Mouillez ensuite ce roux blond avec le bouillon de volaille et portez à ébullition.\nÉtape 5 Ajoutez la viande, les champignons, le vin blanc, poivre et noix de muscade. Continuez de faire chauffer en remuant sans arrêt.\nÉtape 6 Incorporez les quenelles et remuez délicatement.\nÉtape 7 Délayez à part les jaunes d''oeufs avec la crème fraîche dans un bol, puis versez cette liaison dans le faitout en remuant. Faites chauffer sans bouillir pendant 5 mn.\nÉtape 8 Faites chauffer les croûtes précuites dans le four à 180°C. Lorsqu''elles sont bien chaudes et très sèches, les sortir et enlever les chapeaux.\nÉtape 9 Disposez les croûtes sur assiettes individuelles (accompagnées de riz ou pâtes). Les remplir de la garniture en sauce et posez les chapeaux dessus. Servez Aussitôt."]' where recette_id = '5c88d49b6b9e0aa136ffde073cc5eb06';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 20 min Repos : - Cuisson : 40 min'', "Étape 1 Mettre dans un plat allant au four les tomates mondées (= pelées) avec un peu de sel, du paprika, et de l''huile d''olive.\nÉtape 2 Enfourner à 180°C pendant 20 min.\nÉtape 3 Mélanger à la main dans une jatte la viande hachée avec les oignons, sel, poivre, 1 belle cuillère à café de cumin et les herbes (à doser selon les goûts).\nÉtape 4 Former des boulettes de viande avec la main.\r\nLes fariner éventuellement.\nÉtape 5 Les enfoncer dans la sauce tomate.\nÉtape 6 Enfourner à nouveau pour 15 min de cuisson.\nÉtape 7 Ajouter les oeufs et poursuivre la cuisson 5 minutes.\nÉtape 8 Parsemer d''herbes.\nÉtape 9 Servir."]' where recette_id = 'c6097de41e0d0c6473784a0ff076c1d2';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 10 min Repos : - Cuisson : 50 min'', "Étape 1 Préparer la marinade avec une échalote, 4 gousses d''ail écrasées, 1 cuillère à soupe de vinaigre, 1 tasse d''eau, 1 cuillère à café de coriandre et 1 cuillère à soupe de Colombo.\nÉtape 2 La verser sur le poulet préalablement salé et poivré et laisser toute une nuit au réfrigérateur.\nÉtape 3 Dans une grande cocotte, faites revenir l''oignon émincé avec une gousse d''ail écrasée.\nÉtape 4 Ajouter le poulet le faire dorer sur toutes ses faces en ajoutant peu à peu le jus de macération.\nÉtape 5 Ajouter les pommes de terre, les aubergines et les courgettes coupées en gros cubes, le jus de citron, les herbes et le piment de Cayenne. Laisser cuire 15 minutes à couvert.\nÉtape 6 Incorporer le Colombo et bien mélanger. Laisser mijoter encore 15 min, toujours à couvert.\nÉtape 7 Verser le lait de coco et laisser cuire encore 5 minutes non couvert à feu moyen.\nÉtape 8 Rectifier l''assaisonnement et servir bien chaud avec du riz."]' where recette_id = '342ac7440ab576aceb2265760e27ba4a';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 15 min Repos : - Cuisson : 45 min'', "Étape 1 Peler et émincer les oignons.\nÉtape 2 Les faire revenir dans une sauteuse avec 20 g de beurre pendant 3 minutes environ. Les retirer de la sauteuse et les réserver.\nÉtape 3 Dans la même sauteuse, faire revenir les filets mignons de chaque côté.\nÉtape 4 Laisser cuire 10 minutes à feu doux.\nÉtape 5 Réincorporer les oignons. Poursuivre la cuisson pendant 5 minutes. Saler, poivrer. Réserver.\nÉtape 6 Dérouler les pâtes feuilletées.\nÉtape 7 Déposer sur chaque pâte deux tranches de jambon et 100 g de gruyère. Saler et poivrer.\nÉtape 8 Y déposer un filet sur chaque pâte garnie et napper de sauce aux oignons.\nÉtape 9 Replier la pâte autour de la viande et souder les bords à l''aide du jaune d''oeuf préalablement battu et d''un pinceau alimentaire.\nÉtape 10 Enfourner pour 45 minutes de cuisson à 200°C (thermostat 6-7)."]' where recette_id = 'fc3f95b04b3e10ae201334e36bc156c7';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 40 min Repos : - Cuisson : 20 min'', "Étape 1 Coupez les 3 fromages en petits dés.\nÉtape 2 Frottez le caquelon avec la gousse d''ail et laissez-la dedans.\nÉtape 3 Versez 25 cl de vin blanc et faites chauffer.\nÉtape 4 Dans un petit récipient, versez le vin blanc restant (5 cl), la Maïzena et la noix de muscade. Remuez et réservez.\nÉtape 5 Lorsque le vin ''frétille'', versez le fromage (en plusieurs fois) sans cesser de remuer (avec une spatule en bois) sur feu doux/moyen.\nÉtape 6 Lorsque le fromage est bien fondu, versez le verre vin/Maïzena/muscade et continuez de remuer doucement.\nÉtape 7 La préparation commence à être onctueuse et mousseuse, toujours un peu liquide. Poivrez et versez le kirsch. C''est prêt à servir!\nÉtape 8 Le jaune d''oeuf est à mettre dans le caquelon lorsqu''il ne reste plus de liquide, afin d erécupérer le reste du fromage au fond."]' where recette_id = 'c53eff196597ff4de0c651afc758baf6';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 20 min Repos : - Cuisson : 40 min'', "Étape 1 Laver le chou, le séparer en bouquets, puis peler les pommes de terre et les détailler en rondelles.\nÉtape 2 Dans un grand faitout, porter de l''eau salée à ébullition et y faire cuire les pommes de terre au bout de 8 minutes. Mettre ensuite le chou.\nÉtape 3 Laisser cuire les légumes en veillant à ce qu''ils ne ramollissent pas trop, puis les mettre à égoutter. Récupérer 25 cl du bouillon des légumes et le réserver.\nÉtape 4 Préchauffer votre four à 240°C (thermostat 8). Préparer ensuite la sauce : Faire fondre le beurre dans une casserole avec la farine sans cesser de remuer. Mouiller avec le bouillon récupéré, le lait et assaisonner de sel, poivre et noix de muscade à votre convenance. Laisser mijoter 10 min, le temps que la sauce prenne, puis rectifier l''assaisonnement.\nÉtape 5 Réserver 3 cuillères à soupe de gruyère râpé et incorporer le reste dans la casserole en remuant.\nÉtape 6 Dans un plat à gratin beurré, dresser les pommes de terre et le chou. Les recouvrir de sauce et parsemer le dessus des 3 cuillères à soupe de gruyère râpé réservées.\nÉtape 7 Enfourner à four chaud et laisser gratiner 10 à 15 min. Servir immédiatement."]' where recette_id = 'bf783bbcdbe214dc0c534b5aaf89586b';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : - Repos : - Cuisson : 1 h'', "Étape 1 Coupez le lapin en morceaux et badigeonnez légèrement de moutarde. Faire revenir les morceaux sans faire brûler dans un peu d''huile.\nÉtape 2 Pendant ce temps, portez à ébullition les 3/4 de la bouteille de vin blanc avec l''ail coupé en petits morceaux, le laurier, le thym, la carotte coupée en rondelles et le morceau de sucre.\nÉtape 3 Retirez les morceaux de lapin et gardez au chaud (le chaud lapin est toujours apprécié). Ajoutez un peu d''huile et faites dorer les échalotes coupées en rondelles. Ajoutez le lapin et versez dessus le vin blanc chaud. Salez, poivrez et laissez cuire à feu doux pendant 1 heure.\nÉtape 4 Dans un bol, mélangez la crème, du persil haché et une cuillère à soupe de moutarde. Profitez du temps restant pour vous préparer un kir avec le reste du vin blanc.\nÉtape 5 En fin de cuisson, placez les morceaux de lapin sur un plat de service et saupoudrez de persil.\nÉtape 6 Filtrez le jus de cuisson (facultatif) et incorporez la crème à la moutarde. Faites cuire 1 minutes sans faire bouillir et nappez les morceaux de lapin avec cette préparation."]' where recette_id = 'b8e33e715186ecf929a709baf54725da';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 15 min Repos : - Cuisson : 45 min'', "Étape 1 Faîtes revenir les oignons finement hachés dans le beurre. Ajoutez l''ail.\nÉtape 2 Les opérations suivantes doivent se faire sans cesser de remuer : ajouter la farine puis le lait progressivement.\nÉtape 3 Ajouter le saumon, l''aneth, le sel, le poivre. Rajouter de la farine ou du lait si c''est trop liquide / trop épais.\nÉtape 4 Mettre une première couche de sauce dans un plat à gratin, puis recouvrir de plaques de lasagnes, puis la sauce, et ainsi de suite. Finir par le gruyère râpé.\nÉtape 5 Faire cuire 45 min au four à 180°C (thermostat 6), jusqu''à ce qu''un couteau s''enfonce sans résistance.\nÉtape 6 Bon appétit !"]' where recette_id = '8f5c815ed7baf07a1ae5f9b01d1d6f88';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 20 min Repos : - Cuisson : 40 min'', "Étape 1 Pelez et hachez les 4 échalotes.\nÉtape 2 Pelez et pressez la gousse d''ail.\nÉtape 3 Pelez la douzaine d''oignons grelots.\nÉtape 4 Ouvrez la boîte de tomates et coupez-les.\nÉtape 5 Délayez le concentré de tomates dans les 20 cl de vin blanc.\nÉtape 6 Dans une cocotte en fonte, faites chauffer le beurre et l''huile et y faire colorer à feu vif les tranches de lotte.\nÉtape 7 Flambez-les avec le Cognac puis retirez et placez sur une assiette.\nÉtape 8 Mettez à la place les échalotes, l''ail, les oignons, les tomates et le vin dans lequel est délayé le concentré de tomates. Salez, poivrez, ajoutez le piment et laissez mijoter environ 20 min à découvert.\nÉtape 9 Remettez la lotte dans la sauce, couvrez et laissez cuire encore 20 min.\nÉtape 10 Accompagnez de légumes, pommes de terre et carottes cuites vapeur."]' where recette_id = 'b8d480ed3415bcb7f9b7613973007680';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 1 h Repos : - Cuisson : -'', "Étape 1 Préparez le Riz pour Sushis :\nÉtape 2 Rincez le riz jusqu''à ce que l''eau de rincage ne soit plus trouble. Laissez égoutter.\nÉtape 3 Plongez le riz dans 1,5 fois son volume d''eau. A ébullition donnez un coup de spatule et laissez cuire 15 min à feux doux et à couvert.\nÉtape 4 Laissez refroidir le riz quelques instants, et incorporez le sucre dissous au préalable dans le vinaigre de riz.\nÉtape 5 Puis, préparez les rouleaux :\nÉtape 6 Coupez en lamelles le saumon, le concombre, les avocats.\nÉtape 7 Etalez une feuille de célophane sur le plan de travail.\nÉtape 8 Humidifiez vos mains (avec du vinaigre de riz par exemple).\nÉtape 9 Posez la feuille d''algue dans le sens de la largeur, et recouvrez-la d''une couche de riz. Laissez un ou deux centimètres non recouvert sur la largeur supérieure afin de pouvoir ensuite refermer aisément le rouleau.\nÉtape 10 Placez dans le sens de la largeur une bande de saumon, une de concombre, une d''avocat. Saupoudrez de grains de sésame, et du persil haché.\nÉtape 11 Enroulez l''algue en vous servant du célophane. Humidifiez la bande laissée libre pour une fermeture plus facile. Placez au frais.\nÉtape 12 Reproduisez les mêmes opérations jusqu''à épuisement des ingrédients.\nÉtape 13 Avant de servir, découpez les rouleaux en lamelles de 2 à 3 cm."]' where recette_id = '5ceb227ae04642f03711565eadd5b01c';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 45 min Repos : - Cuisson : 15 min'', "Étape 1 Hachez les échalotes.\nÉtape 2 Grattez bien et lavez les moules. \nMettez-les dans une cocotte avec 1 noix de beurre, les échalotes hachées et le vin blanc.\nÉtape 3 Faites-les ouvrir dans la cocotte couverte, sur feu vif pendant quelques minutes. Mélangez 2 ou 3 fois pendant la cuisson.\nÉtape 4 Dès qu''elles sont ouvertes, retirez les moules de la cocotte en conservant le jus de la cuisson. Déposez-les dans 1 plat creux et gardez-les au chaud.\nÉtape 5 Remettez le jus sur le feu. Malaxez avec 1 fourchette 1 cuillerée à café de farine avec le même volume de beurre ou de margarine. Incorporez le tout au jus de la cuisson des moules sur le feu. Laissez bouillir un instant. Salez poivrez.\nÉtape 6 Versez sur les moules. Saupoudrez de persil haché et servez."]' where recette_id = '3c8c02974201ba3ca44ea9b721375481';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 45 min Repos : - Cuisson : 15 min'', ''Étape 1 Laver, et émincer tous les légumes.\nÉtape 2 Emincer la viande et le poulet.\nÉtape 3 Dans un Wok ou une grande sauteuse, faire chauffer l’huile.\nÉtape 4 Cuire la viande et le poulet. Saler et poivrer.\nÉtape 5 Ajouter 40 cl d’eau. Quand elle est à ébullition, ajouter les nouilles.\nÉtape 6 Quand toute l’eau est évaporée, ajouter la sauce soja (suivant goût), les scampis décongelés et les légumes.\nÉtape 7 Cuire + ou – 10 min, à feu vif, en remuant. Il faut que les légumes restent croquants !'']' where recette_id = 'cb8f61654ee35cd0285855eec7c20da8';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 15 min Repos : - Cuisson : 45 min'', "Étape 1 Couper le lard en dés, émincer l''oignon et les champignons et hacher l''ail.\nÉtape 2 Faire dorer les champignons dans un peu de beurre dans une poêle.\nÉtape 3 Dans une autre poêle, faire revenir le lard et les oignons avec un peu de beurre (si nécessaire). Saupoudrer les oignons et le lard avec la farine et remuer jusqu''à ce que la farine blondisse.\nÉtape 4 Ajouter le vin, le bouquet garni, les champignons, l''ail et le sucre. Saler et poivrer.\nÉtape 5 Laisser réduire à feu très doux pendant 45 min. La sauce doit devenir onctueuse.\nÉtape 6 Avant de servir faire revenir les croûtons dans un peu d''huile ou de beurre (version light, les faire griller au four) et les gratter légèrement avec de l''ail.\nÉtape 7 Juste avant de passer à table, faire pocher les oeufs dans une grande casserole d''eau frémissante légèrement vinaigrée.\nÉtape 8 Dans une assiette, déposer les croûtons, les oeufs pochés dessus, napper de sauce.... et bon appétit!"]' where recette_id = '35573da163503f747b4d7749b39f58cc';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 1 h Repos : - Cuisson : -'', "Étape 1 Mettre la farine tamisée et le sel dans la terrine, creuser une fontaine, y verser les 3/4 de l''eau.\nÉtape 2 Pétrir vivement du bout des doigts, sans presque travailler la pâte pour ne lui donner aucune élasticité.\nÉtape 3 La détrempe devra avoir la même consistance que le matière beurre, plutôt ferme que molle; laisser reposer 20 min.\nÉtape 4 Fariner légèrement la planche, étendre la détrempe sur 1 cm d''épaisseur, et mettre le beurre au milieu. Rabattre les quatre pans de la pâte pour l''enfermer.\nÉtape 5 Etendre la pâte au rouleau en une bande longue, étroite, régulière, que l''on amincit jusqu''à ce qu''on commence à apercevoir le beurre.\nÉtape 6 Plier la pâte en 3, en rabattant un des bouts sur le milieu de la pâte, et l''autre bout par-dessus le premier. C''est ce qu''on appelle donner un tour.\nÉtape 7 Mettre le morceau de pâte dans l''autre sens (mettre le côté plié toujours à droite), et laisser reposer la pâte au frais environ 20 min.\nÉtape 8 Recommencer à l''allonger au rouleau, puis plier en 3, c''est le 2ème tour; laisser reposer la pâte au frais environ 20 min.\nÉtape 9 Recommencer, laisser reposer au frais 20 min entre chaque tour, et donner 6 tours.\nÉtape 10 On peut donner plus de tours, la pâte gagne alors en légèreté."]' where recette_id = '48312b33fcfa96980dcb8619648805dd';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 30 min Repos : - Cuisson : 30 min'', "Étape 1 Dans une grande casserole, faire revenir les 2 oignons coupés en petits dés dans un peu de matière grasse.\nÉtape 2 Ajouter le boursin cuisine, puis le vin blanc sec, le thym, les herbes de Provence, et l''aneth; laisser réduire à feu doux environ 15 min, puis ajouter la crème épaisse. Ajouter un peu d''ail moulu, sel et poivre.\nÉtape 3 Laisser mijoter doucement tout en remuant de temps en temps.\nÉtape 4 Pendant ce temps, décortiquer les crevettes.\nÉtape 5 Faire cuire les spaghetti dans une grande casserole d''eau bouillante salée, avec une cuillère d''huile, le temps indiqué sur le paquet.\nÉtape 6 Ajouter doucement les crevettes à la sauce et laisser mijoter environ 10 min; rectifier l''assaisonnement si nécessaire.\nÉtape 7 Servir les spaghetti avec la sauce et les crevettes."]' where recette_id = '27cbdc468fa035233a5e8c0ff34bae68';
update fact_recette_base set etapes = '[''Préparation 1 h Préparation : 30 min Repos : - Cuisson : 30 min'', "Étape 1 Cuire les pommes de terre à l’eau pendant 20 minutes, puis les éplucher et les couper en rondelles.\nÉtape 2 Emincer les oignons et les faire revenir dans un peu de beurre.\nÉtape 3 Ajouter les lardons fumés et laisser également revenir à feu assez doux (une dizaine de minutes) en remuant régulièrement.\nÉtape 4 Préparer un plat de cuisson (j’utilise un plat rond en terre cuite de 40 cm de diamètre, 10 cm de haut). Frotter généreusement le fond du plat avec une gousse d’ail.\nÉtape 5 Organiser le plat en trois couches : recouvrir le fond du plat de la moitié des pommes de terre, puis ajouter le mélange oignons et lardons, ajouter enfin par dessus le reste des pommes de terre.\nÉtape 6 Verser dessus le vin blanc et la crème fleurette. Poivrer (assez copieusement) et saler (légèrement).\nÉtape 7 Préchauffer le four à 190°C (thermostat 6-7).\nÉtape 8 Gratter les reblochons, les couper en deux dans l''épaisseur et les poser (côté croûte en haut) sur le dessus des pommes de terre.\nÉtape 9 Enfourner environ 20 minutes (je mets le four en « chaleur tournante » + gril).\nAu moment de servir (dans le plat de cuisson), on peut saupoudrez d’un peu de persil haché.\nCe plat unique se déguste (c’est le mot juste !) accompagné du vin utilisé pour la recette."]' where recette_id = '13daa8b8a5b8d05205f771112fe86a1f';
update fact_recette_base set etapes = '[''Préparation 1h03 Préparation : 1 h Repos : - Cuisson : 3 min'', "Étape 1 Faites cuire les escalopes de poulet, dans une poêle beurrée.\nÉtape 2 Lorsque les escalopes sont cuites, découpez-les en petits morceaux en vue de les mixer, et réservez-les.\nÉtape 3 Faites chauffer de l''eau dans une casserole. Lorsqu''elle est chaude, plongez les champignons noirs pendant environ 15 min.\nÉtape 4 Egouttez les champignons, et ajoutez-les au poulet.\nÉtape 5 Refaites chauffer de l''eau, pour cuire les vermicelles de soja comme des pâtes (pendant environ 2 min).\nÉtape 6 Lorsqu''ils sont prêts, incorporez-les au poulet, et versez le tout dans un mixer.\nÉtape 7 Ajoutez quelques pousses de soja (en boîte).\nÉtape 8 Mixez le tout, jusqu''à ce que ce soit très finement haché. Placez la préparation sur une assiette.\nÉtape 9 Epluchez les carottes, et rapez-les au mixer. Séparez farce et carottes.\nÉtape 10 Prenez une galette de riz, passez-la sous l''eau très chaude, jusqu''à ce qu''elle devienne translucide et toute molle.\nÉtape 11 Etalez-la, et disposez une petite quantité de carottes, ainsi qu''un peu de farce (1 cuillère à soupe environ) sur une des extrémités de la galette.\nÉtape 12 N''oubliez pas la feuille de menthe, pour relever le goût.\nÉtape 13 Ensuite, prenez cette extrémité, et rabattez-la sur la farce. Essayez de fermer les coins, et formez un rouleau.\nÉtape 14 Passez les rouleau à la friteuse, ou dans une poêle avec de l''huile très chaude dedans, pendant 3 min.\nÉtape 15 Sortez-les, passez-les sur du papier absorbant, et passez-les quelques minutes au four, pour qu''ils dorent un peu."]' where recette_id = '2cd928400b77acd6c24939a13219cfaf';
update fact_recette_base set etapes = '[''Préparation 1h05 Préparation : 30 min Repos : - Cuisson : 35 min'', "Étape 1 Lavez et épluchez les carottes, les navets et les tomates et les couper en cubes.\nÉtape 2 Dans un autocuiseur, versez 3 cuillères à soupe d''huile d''olive. Mettez à chauffer et faites-y dorer les pilons de poulet. Quand ils sont dorés, versez l''équivalent d''1 litre d''eau et ajouter les cubes de bouillon de boeuf, le concentré de tomate, les carottes, navets et tomates, les épices à couscous et l''harissa.\nÉtape 3 Fermez votre autocuiseur et compter 25 mn de cuisson une fois que celui-ci est monté en pression.\nÉtape 4 En attendant, lavez et coupez les courgettes en cubes et égouttez les pois chiches.\nÉtape 5 Une fois les 25 mn écoulées, évacuez la vapeur de votre autocuiseur, ouvrez et rajouter les courgettes et les pois chiches.\nÉtape 6 Remettez au feu : comptez 10 mn de cuisson une fois votre autocuiseur sous pression.\nÉtape 7 Faites cuire vos merguez sur un grill ou à la poêle, mais pas avec les légumes.\nÉtape 8 Servez accompagné d''une semoule fine."]' where recette_id = '541777103778f0ce5125f3fd3d5111be';
update fact_recette_base set etapes = '[''Préparation 1h05 Préparation : 18 min Repos : - Cuisson : 47 min'', "Étape 1 Couper la viande en morceaux et mettre le mélange huile + beurre à chauffer.\nÉtape 2 La faire dorer dans un mélange huile + beurre dans une cocotte.\nÉtape 3 Retirer les morceaux de la cocotte et jeter le surplus de gras.\nÉtape 4 Déglacer la cocotte avec le vin blanc, le bouillon cube, le jus des champignons et la crème (2/3 du pot).\nÉtape 5 Tartiner le filet mignon de moutarde à l''ancienne et le remettre dans la cocotte avec les champignons.\nÉtape 6 Cuire environ 30 min, à feu très doux.\nÉtape 7 En fin de cuisson, ajouter le reste de crème, saler et poivrer.\nÉtape 8 Bon appétit."]' where recette_id = 'fdfd3d44e6552288efc341cb7286ded1';
update fact_recette_base set etapes = '[''Préparation 1h05 Préparation : 20 min Repos : - Cuisson : 45 min'', "Étape 1 Faire bouillir un fond d''eau légèrement salée dans une grande casserole.\nÉtape 2 Plonger les brocolis, couvrir et laisser cuire à feu doux. Battre les 2 oeufs dans un grand bol, ajouter la crème, le sel, le poivre et la noix de muscade. Mélanger.\nÉtape 3 Ajouter les 2 tranches de jambon préalablement coupées en petits morceaux ainsi que le tiers du fromage râpé. Mélanger le tout.\nÉtape 4 Lorsque les brocolis sont tendres, les égoutter le plus possible. \nPréchauffer le four (180°C). Faire chauffer un fond d''huile dans la casserole et y mettre l''oignon haché grossièrement. Faire revenir à feu très doux et ne pas faire brunir !\nÉtape 5 Y ajouter les deux gousses d''ail pressées et les brocolis. Assaisonner légèrement et bien mélanger.\nÉtape 6 Verser le contenu de la casserole dans un plat à gratin, bien étaler. Verser le mélange d''oeufs, étaler le tout de façon uniforme.\nÉtape 7 Saupoudrer de chapelure et du restant de gruyère râpé. Mettre le plat au four, toujours sur 180°C et laisser cuire pendant entre 30 et 45 min.\nÉtape 8 Vérifier la cuisson de temps en temps... L''ensemble doit être (en fin de cuisson) assez dense, un peu comme une grosse omelette."]' where recette_id = '2c2ef6e2231358187fbf6f54160ba498';
update fact_recette_base set etapes = '[''Préparation 1h05 Préparation : 25 min Repos : - Cuisson : 40 min'', "Étape 1 Couper le poivron en deux, retirer les graines et les cloisons internes, le débiter en carrés.\nÉtape 2 Eplucher et émincer le céleri en tronçons. Préchauffer le four à 180°C.\nÉtape 3 Dans une grande terrine, faire revenir 5 mn le chorizo avec les lardons, dans l''huile chaude. Remplacer par le poulet. Faire dorer sur toutes leurs faces et les retirer.\nÉtape 4 Dans la même cocotte, faire fondre l''oignon et l''ail épluchés et hachés pendant 5 mn. Ajouter le poivron et le céleri et faire cuire 8 mn. en remuant.\nÉtape 5 Ajouter ensuite le poulet, les lardons, le riz versé en pluie, le coulis et la chair de tomate concassée, le thym, la sauge, le laurier, le piment de Cayenne. Arroser du bouillon et porter à ébullition.\nÉtape 6 Enfourner et faire cuire 40 mn. Laisser la jambalaya pendant 5 mn dans le four éteint, porte entrouverte, avant de servir."]' where recette_id = '185e248003e7d655f7e8f6b981b2bc56';
update fact_recette_base set etapes = '[''Préparation 1h05 Préparation : 20 min Repos : - Cuisson : 45 min'', "Étape 1 Couper l''oignon en petits morceaux et faire revenir dans de l''huile d''olive.\nÉtape 2 Quand les oignons ont bien bruni, y ajouter les 350g de steak haché.\nÉtape 3 Faire cuire à feu moyen puis ajouter la sauce bolognaise.\nÉtape 4 Préparez la béchamel. \nFaire fondre le beurre à feu vif.\nÉtape 5 Une fois fondu, rajouter les deux cuillères à soupe de farine puis remuer avec un fouet à feu moyen.\nÉtape 6 Quand le mélange est homogène (très rapide), rajouter progressivement le lait sans arrêter de fouetter pour éviter les grumeaux.\nÉtape 7 Continuer de remuer jusqu''à ce que la béchamel s''épaississe.\nÉtape 8 Mélanger la sauce bolognaise faite précédemment avec la béchamel.\nÉtape 9 Puis dans un plat à gratin, verser une couche de cette préparation puis recouvrir de pâte à lasagne. Refaire la même chose jusqu''à épuisement de la sauce (environ 2 fois).\nÉtape 10 La dernière couche doit être une couche de sauce. Ajouter le gruyère râpé et faire cuire envrion 45 min à 180° (th.6).\nÉtape 11 Pour savoir si les lasagnes sont cuites, piquer avec un couteau, les pâtes à lasagne doivent être fondantes, donc le couteau doit s''enfoncer sans problème."]' where recette_id = '9278bc178a718f00f15507428932e469';
update fact_recette_base set etapes = '[''Préparation 1h05 Préparation : 45 min Repos : - Cuisson : 20 min'', "Étape 1 Commencez par cuire le riz façon gohan :\nÉtape 2 Lavez le riz, mouillez-le et frottez-le sans l’écraser. Couvrez-le d’eau et remuez. Jetez l''eau devenue blanche et répétez l’opération jusqu’à ce que celle-ci soit claire puis égouttez le riz.\nÉtape 3 Mettez-le dans une casserole avec deux fois son volume en eau froide. Couvrez et portez à ébullition.\nÉtape 4 Dès que l’eau bout, remuez le riz hors du feu, réduisez au minimum et laissez cuire 15 min à couvert.\nÉtape 5 Retirez du feu et laissez reposer 10 min pour que le riz gonfle dans sa vapeur.\nÉtape 6 Laisser tiédir, mais pas refroidir complètement afin que le riz reste collant.\nÉtape 7 Pendant ce temps, coupez la feuille de nori en 6 larges bandes et grillez-les légèrement. Mélangez le thon et la mayonnaise de manière homogène dans un bol.\nÉtape 8 Mouillez vos mains puis couvrez généreusement vos paumes de sel.\nÉtape 9 Prenez du riz dans le creux d’une main, faites un petit creux au milieu et placez-y un peu du mélange thon-mayonnaise en une petite boule.\nÉtape 10 Recouvrez avec autant de riz.\nÉtape 11 Pressez avec l’autre main pour refermez le tout en une forme triangulaire aux bords légèrement épais comme sur l''image.\nÉtape 12 Aplatissez les faces puis envelopper le tout d''une bande d''algue nori comme une couverture (voir l''image). Recommencez jusqu''à utiliser tous les ingrédients.\nÉtape 13 Placer les onigiris au réfrigérateur 10 min puis dégustez. Ils peuvent être conservés 1 ou 2 jours dans un récipient hermétique."]' where recette_id = '4d20ce56ce89468c4eae6cc503e4d373';
update fact_recette_base set etapes = '[''Préparation 1h05 Préparation : 20 min Repos : - Cuisson : 45 min'', "Étape 1 Fariner la viande, tapoter pour retirer l''excédent. Les faire dorer sur toutes les faces dans une cocotte-minute avec un fond d''huile.\nÉtape 2 Peler et couper les carottes en rondelles épaisses, émincer les oignons, hacher l''ail. Les ajouter dans la cocotte, ainsi que les tomates et le vin blanc. Saler, poivrer, ajouter le bouquet garni et fermer la cocotte.\nÉtape 3 Laisser cuire 45 min à partir de la mise en rotation de la soupape, à feu doux."]' where recette_id = 'a23baed35b12050fbeb35cd1a943462a';
update fact_recette_base set etapes = '[''Préparation 1h05 Préparation : 20 min Repos : - Cuisson : 45 min'', "Étape 1 Couper le veau en morceaux de taille égale.\nÉtape 2 Faire dorer dans une cocotte avec la matière grasse.\nÉtape 3 Quand les morceaux sont bien dorés, les retirer de la cocotte et ajouter la farine afin de faire un roux.\nÉtape 4 Mouiller progressivement avec le vin blanc.\nÉtape 5 Compléter avec de l''eau pour avoir une quantité de sauce suffisante pour recouvrir la viande.\nÉtape 6 Ajouter le fond de veau et bien mélanger.\nÉtape 7 Rectifier l''assaisonnement et remettre la viande dans la cocotte avec la sauce.\nÉtape 8 Laisser mijoter pendant au moins 40 min. 5 min avant de servir, ajouter les champignons."]' where recette_id = '85898afe754fa301b51248ee3a5fc24b';
update fact_recette_base set etapes = '[''Préparation 1h05 Préparation : 1 h Repos : - Cuisson : 5 min'', "Étape 1 Couper les tripes en petits morceaux, les faire revenir dans une cocote en fonte pendant 10 minutes.\nÉtape 2 Ajouter les oignons coupés en petits morceaux, les carottes coupées en rondelles et bien mélanger le tout.\nÉtape 3 Ajouter ensuite les 2 boîtes de tomates, le vin blanc, sel et poivre, ainsi que le piment oiseau.\nÉtape 4 Laisser mijoter 5 heures et ajouter dans la derniére heure de cuisson la rasade de pastis.\nÉtape 5 Servir avec des pommes de terre à l''eau."]' where recette_id = '83314ab536f2af2ed81fb2c72ed64a27';
update fact_recette_base set etapes = '[''Préparation 1h05 Préparation : 20 min Repos : - Cuisson : 45 min'', "Étape 1 Couper le chou en quatre et enlever les côtes au milieu. Laver et émincer les quatre morceaux en lamelles.\nÉtape 2 Eplucher les pommes de terre, les laver et les faire cuire à l''eau (non salée!!!).\nÉtape 3 Faire fondre le kubor dans l''eau (non salée).\nÉtape 4 Faire revenir les lardons dans un poêlon en fonte, rajouter, une fois qu''ils sont bien rissolés, les lamelles de chou. Bien mélanger et mettre un quart du bouillon.\nÉtape 5 Il faut mélanger de temps en temps le mélange chou, lardons et bouillon (en rajouter au fur et à mesure pendant les quarante minutes de cuisson).\nÉtape 6 Rajouter les pommes de terre cuites à l''eau dans le poêlon avec le chou un petit quart d''heure avant la fin de la cuisson."]' where recette_id = '80bb48c328837804e6c2850c35ae75ed';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 25 min Repos : - Cuisson : 45 min'', "Étape 1 Coupez la viande en morceaux de taille moyenne puis placez-la dans la cuve du Cookeo. Faites-la revenir avec le beurre doux jusqu''à ce que les morceaux soient un peu dorés sur le mode « dorer » / 3 min (préchauffage inclus), en remuant avec une cuillère en bois / stoppez avant l’étape 2.\nÉtape 2 Saupoudrez avec la farine. Remuez bien.\nÉtape 3 Versez 40 cl d’eau, les cubes de bouillon, le vin. Ajoutez de l''eau si nécessaire pour couvrir.\nÉtape 4 Épluchez puis coupez les carottes en rondelles. Émincez l’oignon. Versez le tout dans la cuve. Ajoutez les champignons égouttés.\nÉtape 5 Laissez mijoter doucement dans le Cookeo sur le mode « cuisson sous pression » / 45 min. Si la préparation est trop liquide, ajoutez un peu de farine.\nÉtape 6 Dans un bol, mélangez bien la crème fraîche, les jaunes d’œufs et le jus de citron. Ajoutez ce mélange en fin de cuisson, puis remuez bien."]' where recette_id = 'f6c48e817da4fd7aaded3549d542ca68';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 10 min Repos : - Cuisson : 1 h'', "Étape 1 Hacher les oignons. Peler l''ail.\nÉtape 2 Dans une cocotte minute, faire roussir la viande et les lardons dans l’huile ou le beurre.\nÉtape 3 Ajouter les oignons, les champignons égouttés et saupoudrer de fariner. Mélanger et laisser dorer un instant.\nÉtape 4 Mouiller avec le vin rouge qui doit recouvrir la viande.\nÉtape 5 Saler et poivrer.\nÉtape 6 Ajouter l’ail et le bouquet garni.\nÉtape 7 Fermer la cocotte minute.\nÉtape 8 Laisser cuire doucement 60 min à partir de la mise en rotation de la soupape."]' where recette_id = '3ea21754159802a309521029adabcf2f';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 25 min Repos : - Cuisson : 45 min'', "Étape 1 Pelez les pommes et coupez-les en 4 .\nÉtape 2 Trempez les quartiers dans le jus du citron et réservez le jus que vous agrémenterez de sucre.\nÉtape 3 Coupez les quartiers encore en 2 .\nÉtape 4 Faites revenir les quartiers dans 15 g de beurre et couvrez la poêle (pour ne pas les dessécher et qu''ils collent).\nÉtape 5 Laissez dorer et retournez assez souvent. Laisser cuire encore quelques minutes. Réservez au chaud.\nÉtape 6 Pendant ce temps, dans une autre poêle, faites revenir dans le reste du beurre, vos 2 morceaux de boudin.\nÉtape 7 Il faut le saisir (feu fort) mais attention à la suite de la cuisson qui doit rester douce pour ne pas rompre le boyau.\nÉtape 8 Faites cuire le boudin de tous les côtés.\nÉtape 9 Lorsque le boyau s''est rétracté (aux extrémités) et que la surface est bien noire, servez le boudin, accompagné des pommes."]' where recette_id = '94cfa1c6debd4fb9acde75df8e6b04dc';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 10 min Repos : - Cuisson : 1 h'', "Étape 1 Faire fondre à feu doux le beurre et le miel, puis hors du feu, ajouter la moutarde le sel et le poivre.\nÉtape 2 Badigeonner les cailles avec ce mélange onctueux dans un plat allant au four.\nÉtape 3 Recouvrir le plat d''un papier aluminium et laisser reposer 2 heures à température ambiante ou une nuit au frigo.\nÉtape 4 Allumer le four 210°C (thermostat 7).\nÉtape 5 Mettre le plat couvert d''alu dans le four chaud pendant 25 min puis retirer l''alu et poursuivre la cuisson encore 25 à 30 min en arrosant souvent avec la sauce.\nÉtape 6 Servir les cailles dorées accompagnées de tagliatelles au citron par exemple"]' where recette_id = '08d58fe3e216a29cdb9d1647947ec233';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 40 min Repos : - Cuisson : 30 min'', "Étape 1 Laissez décongeler les coquilles la veille de la préparation dans une moitié de lait et une moitié d''eau.\nÉtape 2 Mettez les coquilles dans le vin blanc avec sel et poivre et amenez à ébullition pendant 2 min.\nÉtape 3 Laissez tiédir hors du feu et retirez les coquilles pour les mettre dans un plat.\nÉtape 4 Ajoutez deux petites échalotes (ou échalote congelée) à la cuisson et faites-la réduire.\nÉtape 5 Dans une autre casserole, faites fondre le beurre. Ajoutez la farine et faites-la blondir.\nÉtape 6 Rajoutez y la crème et la cuisson aux échalotes.\nÉtape 7 Rectifiez l''assaisonnement, ajoutez le citron et, hors du feu, les jaunes d''oeufs en les fouettant.\nÉtape 8 Nappez les coquilles avec la sauce et saupoudrez le plat avec la chapelure.\nÉtape 9 Mettez le plat au four pour le faire dorer et le réchauffer."]' where recette_id = '992e3c9abbe8e82654b8c5223c97705e';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 20 min Repos : - Cuisson : 50 min'', "Étape 1 Laver les courgettes, ne pas les peler.  Les couper en deux dans le sens de la longueur pour obtenir 4 barquettes.  Evider chaque barquette avec une petite cuillère et conserver la chair à part.\nÉtape 2 Faire revenir la chair de courgette dans la moitié d''huile d''olive avec l''oignon émincé. Ajouter ensuite la viande hachée et faire revenir à nouveau en mélangeant avec une fourchette afin de bien égrener la viande hachée.\nÉtape 3 Dans un plat allant au four, disposer les barquettes de courgettes l''une à côté de l''autre, les remplir de la farce courgette - viande et arroser le tout avec le coulis de tomate ou une boîte de tomates pelées (selon que l''on désire plus ou moins de jus).\nÉtape 4 Mettre au four 200°C pendant environ 30 à 40 minutes.\nÉtape 5 Quelques minutes avant la fin de la cuisson, parsemer le plat avec le fromage râpé et poursuivre les dernières minutes de cuisson (le fromage fond).  Pour un véritable doré, passer le plat au grill quelques instants.\nÉtape 6 Bon appétit."]' where recette_id = 'c925c36594d2508f51735d19d94601e1';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 15 min Repos : - Cuisson : 55 min'', "Étape 1 Cuire les endives à l''eau bouillante pendant 45 min puis bien les égoutter.\nÉtape 2 Disposer les endives cuites sur les tranches de jambon puis rouler le tout.\nÉtape 3 Mettre les endives entourées de jambon dans un plat allant au four.\nÉtape 4 Faire une sauce Mornay en mélangeant le beurre, la farine, le lait et le fromage. Saler et poivrer.\nÉtape 5 Napper de sauce les endives au jambon et recouvrir de fromage râpé.\nÉtape 6 Gratiner pendant 10 à 15 min au four à 200°C (thermostat 6-7)."]' where recette_id = '488e8b6674a5562c9354bde846afd8f1';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 10 min Repos : - Cuisson : 1 h'', "Étape 1 En Alsace la palette de porc s''achète toute prête : viande salée dans la saumure, enrobée de moutarde emmaillotée dans un filet de crépine, la palette se met au four chaud 200°C pendant 1 h ; arroser de sauce régulièrement, 15 min avant la fin de la cuisson, l''arroser d''un petit verre de bière, elle est très savoureuse.\nÉtape 2 Elle se mange avec des pommes de terre coupées en grosses frites cuites à la vapeur dans la cocotte pendant 7 min. Dans une poêle faire revenir doucement 1 oignon émincé puis arroser de 2 cuillères de l''eau de cuisson des pommes de terre, ajouter de la crème fleurette, sel poivre et noix de muscade râpée, verser cette sauce sur les pommes de terre après leur cuisson.\nÉtape 3 Repas pas cher et fabuleux de goût et d''onctuosité."]' where recette_id = 'b82a2144895002486a7036dd2c92293e';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 35 min Repos : - Cuisson : 35 min'', "Étape 1 Découper le poulet en morceaux, nettoyer les moules, émincer le chorizo et les poivrons, peler et concasser les tomates, hacher les oignons et l''ail.\nÉtape 2 Mettre l''huile dans le plat et faire dorer les morceaux de poulet. Ajouter les calamars, les oignons tout en remuant puis mettre les tomates, les poivrons, l''ail, le safran, le sel et le poivre. Laisser cuire 5 minutes en remuant avant d''incorporer le riz, le chorizo et le bouillon.\nÉtape 3 Y plonger les crevettes et les moules, porter à ébullition puis laisser cuire environ 30-35 minutes."]' where recette_id = 'c673da0f41cf441c645405c86d294bed';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 30 min Repos : - Cuisson : 40 min'', "Étape 1 Faites cuire les pommes de terre à l''eau bouilante salée environ 30 minutes (selon la taille).\nÉtape 2 Pendant ce temps, préparez la pâte à choux : portez à ébullition 10 cl d''eau avec le beurre.\nÉtape 3 Salez et versez d''un coup la farine, remuez énergiquement à la cuillère en bois jusqu''à ce que la pâte se détache des birds de la casserole.\nÉtape 4 Laissez tiédir puis ajoutez les oeufs un à un, en mélangeant bien à chaque fois.\nÉtape 5 Egouttez et pelez les pommes de terre, écrasez-les en purée fine et ajoutez-les à la pâte à choux. Salez et poivrez, puis laissez refroidir.\nÉtape 6 Formez ensuite des petites boules de la taille d''une noix avec vos mains farinées, ou utilisez une poche à douille.\nÉtape 7 Jetez-les dans l''huile de friture bien chaude par petites quantités et laissez dorer 1 min environ."]' where recette_id = 'f5dff98d7d33a0b9b5c613513324efe0';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 15 min Repos : - Cuisson : 55 min'', ''Étape 1 Préchauffer le four à 180°C (thermostat 6).\nÉtape 2 Préparer la farce en mélangeant la chair à saucisse, le steak haché, l\''ail, le persil, l\''oeuf et un peu de sel et poivre à votre convenance.\nÉtape 3 Eplucher les pommes de terre, couper un "chapeau" sur le dessus. Creuser les pommes de terre à l\''aide d\''un couteau ou d\''une cuillère ; conserver la chair de pommes de terre retirée. Remplir les pommes de terre de farce et placer les "chapeaux" sur le dessus de chaque pomme de terre.\nÉtape 4 Emincer l\''oignon. Beurrer un plat allant au four, y placer dans le fond l\''oignon émincé puis les pommes de terre farcies. Placer la chair de pomme de terre restante dans le plat ainsi que les restes éventuels de farce. Déposez une noisette de beurre sur chaque "chapeau" de pommes de terre puis arrosez le tout du verre de bouillon.\nÉtape 5 Enfourner pour 55 minutes. Prolonger de quelques minutes la cuisson si nécessaire.'']' where recette_id = '8e4192e5fe2bdf7c154467dbe84724ec';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 1 h Repos : - Cuisson : 10 min'', "Étape 1 Tamiser les farines dans un grand récipient.\nÉtape 2 Faire une fontaine assez large et y mettre au centre les oeufs et une pincée de sel. Mélanger les ingrédients à la fourchette puis travailler énergiquement la pâte pendant une dizaine de minutes.\nÉtape 3 En faire ensuite une boule, l''envelopper dans un film transparent et laisser reposer 1/2 heure.\nÉtape 4 Diviser ensuite la pâte en 3 ou 4 parts et la passer à la machine en commençant par l''épaisseur la plus importante pour finir par la plus fine. Laisser reposer 1/2 heure les bandes de pâte ainsi obtenues.\n\nSi vous n''avez pas de machine à pâtes, étaler la pâte finement au rouleau à pâtisserie en farinant bien puis la replier sur elle-même avant de l''étaler à nouveau jusqu''à ce qu''elle soit de l''épaisseur désirée.\nÉtape 5 Les repasser alors à la machine avec le rouleau approprié de façon à obtenir des tagliatelles de la largeur désirée.\n\nSans machine à pâtes : Lorsque la pâte à l''épaisseur souhaitée, la découper de la forme désirée au couteau. Pour aller plus vite on peut rouler la pâte sur elle-même avant de la découper en lanières d''1 cm d''épaisseur pour de grosses tagliatelles. On peut aussi faire des pâtes courtes en disposant plusieurs bandes de 5 cm de large les unes au dessus des autres puis en en découpant de fines lanières.\nÉtape 6 Les étendre au fur et à mesure sur un torchon légèrement fariné. Les recouvrir d''un autre torchon lui aussi légèrement fariné et les laisser reposer jusqu''au moment de les cuire dans une grande quantité d''eau salée."]' where recette_id = 'fc86d0b6635e1abd9975316f98d9cdfc';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 10 min Repos : - Cuisson : 1 h'', "Étape 1 Mettre la rouelle dans un plat allant au four.\nÉtape 2 Disséminer tout autour des pommes de terres coupées en morceaux (moyens). Arroser d''huile d''olive.\nÉtape 3 Enfourner à 180°C - 190°C pendant environ 45 min à 1 heure, en arrosant de jus (huile chaude) régulièrement pour éviter le déssèchement.\nÉtape 4 Sortir le plat et recouvrir de fond de veau en poudre (une bonne dose, selon les goûts). Remettre au four environ 1/2 heure en arrosant régulièrement toujours pour la même raison.\nÉtape 5 Quand la rouelle a pris une couleur ambrée et les pommes de terres sont cuites, servez avec un bon vin rouge."]' where recette_id = 'ef8ecdfa75f46eb9ffde0fb1905f31f4';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 10 min Repos : - Cuisson : 1 h'', "Étape 1 Mettre dans un plat allant au four, le rôti de dinde, éplucher les échalotes, les couper en morceaux et les répartir autour du rôti. Rajouter une ou deux branches de thym.\nÉtape 2 Enfourner pendant 1h à thermostat 6 (180°C). Pour éviter que ça ne sèche, surtout couvrir d''un aluminium ou faire cuire dans une cocotte en verre.\nÉtape 3 A mi-cuisson, mettre le bouillon cube dilué dans un verre d''eau chaude et saler le rôti.\nÉtape 4 Vous pouvez le servir chaud avec des endives, des marrons ou le servir froid accompagné de salade."]' where recette_id = '83d364aeadb4a6a5f3591aa4521395c1';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 10 min Repos : - Cuisson : 1 h'', "Étape 1 Préchauffer le four à 180°C (thermostat 6).\nÉtape 2 Mélanger tous les ingrédients ensemble, sauf le rôti et les rondelles d''oignons.\nÉtape 3 Badigeonner le rôti de cette sauce et le coucher sur les oignons. Rectifier l''assaisonnement si besoin.\nÉtape 4 Ajouter le bouillon, couvrir le rôti et mettre au four pendant environ 1h30.\nÉtape 5 Pour vérifier la cuisson, piquer avec un cure-dent. S''il pénètre facilement, le rôti est à point."]' where recette_id = 'b34c74cc98016542fecc4114ee781b2e';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 10 min Repos : - Cuisson : 1 h'', "Étape 1 Cuire le rôti de porc salé et poivré dans un plat à four (Th 5/6).\nÉtape 2 Après 50 mn de cuisson, couper le rôti en tranches en gardant les tranches attachées par le bas (facile avec un couteau électrique).\nÉtape 3 Glisser entre chaque tranche une tranche de fromage et une tranche de bacon.\nÉtape 4 Replacer dans le plat de cuisson et arroser avec la crème fraîche.\nÉtape 5 Remettre au four 10 mn.\nÉtape 6 Découper complètement, servir en nappant de la sauce qui s''est formée."]' where recette_id = 'd9eb2ca33554fc7cc972a756a14db433';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 10 min Repos : - Cuisson : 1 h'', ''Étape 1 Préchauffez le four à 180°C (thermostat 6). Prétranchez le rôti en laissant environ 2 cm de fond.\nÉtape 2 Glisser entre chaque "tranche" de veau : du bacon, du cheddar et 1 tranche de tomate.\nÉtape 3 Disposez le rôti dans un plat beurré, rajoutez sur le rôti quelques noisettes de beurre, salez, poivrez.\nÉtape 4 Enfournez pour 1 heure de cuisson.'']' where recette_id = 'bd40b044a4a425dc1ea78556adf26bbb';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 10 min Repos : - Cuisson : 1 h'', "Étape 1 Détailler la carotte en rondelles, les échalotes et l''ail en fins morceaux.\nÉtape 2 Laver et couper en 2 les champignons.\nÉtape 3 Couper la viande en cubes de 3 cm de côté environ. Dans une cocotte à fond épais, faire dorer la viande.\nÉtape 4 Ajouter alors les carottes, l''ail et les échalotes. Lorsque ces derniers sont translucides, saupoudrer de farine.\nÉtape 5 Lorsque la farine a blondi, ajouter le concentré de tomate, l''eau, le vin et le bouquet garni. Saler, poivrer.\nÉtape 6 Laisser mijoter 1h30 à couvert sur feu doux.\nÉtape 7 Au bout de ce temps, ajouter les champignons et laisser cuire encore 15 min."]' where recette_id = 'cb3e56e1990b1cf2f46f6995f6986087';
update fact_recette_base set etapes = '[''Préparation 1h10 Préparation : 10 min Repos : - Cuisson : 1 h'', "Étape 1 Couper les cuisses de poulet en 2.\nÉtape 2 Les faire revenir dans l''huile pendant 20 min puis ajouter l''oignon émincé, l''ail écrasé, une bonne pincée de persil frais et une cuillère à soupe de fond de sauce volaille.\nÉtape 3 Mélanger le tout et faire revenir jusqu''à ce que les oignons soient translucides.\nÉtape 4 Ajouter la boîte de champignons avec le jus (très important) et la deuxième cuillère à soupe de fond de volaille et laisser cuire a couvert avec environ 50 cl d''eau pendant 10 min.\nÉtape 5 A part, mélanger la crème et la farine.\nÉtape 6 Verser dans la marmite avec vos ingrédients.\nÉtape 7 Laisser mijoter environ 15 min, le temps que la sauce devienne bien onctueuse."]' where recette_id = 'd2f8a97f6e40359d06237c68dfcc61b9';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 15 min Repos : - Cuisson : 1 h'', "Étape 1 Enlever la fine peau qui recouvre le corps. Couper les tentacules, couper le corps en rondelles.\nÉtape 2 Couper les oignons en 2, puis en fines rondelles.\nÉtape 3 Hacher l''ail.\nÉtape 4 Dans une cocotte, faire chauffer l''huile, faire revenir les calamars pendant 2 mn en remuant de temps en temps.\nÉtape 5 Les enlever de la cocotte puis, à feu doux, faire fondre les oignons sans qu''ils prennent couleur. Ajouter l''ail à la fin.\nÉtape 6 Remettre les calamars dans la cocotte, flamber avec le Cognac, ajouter les tomates concassées.\nÉtape 7 Saler, poivrer, mouiller avec le vin blanc.\nÉtape 8 Poursuivre la cuisson à feu doux pendant près d''une heure en laissant le couvercle. Un peu avant la fin on peut l''enlever si on préfère une sauce un peu épaisse.\nÉtape 9 On peut aussi à ce moment-là ajouter la bisque de homard si l''on veut un peu corser la sauce."]' where recette_id = '7cc30041a6738c7f36261aeaf3eedb81';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 15 min Repos : - Cuisson : 1 h'', "Étape 1 Faire revenir les crépinettes dans l''huile chaude pour qu''elles soient dorées, puis les sortir.\nÉtape 2 Faire revenir les oignons et l''ail dans la même huile pour qu''ils soit dorés.\nÉtape 3 Remettre les crépinettes et ajouter le vin blanc et les herbes, saler et poivrer.\nÉtape 4 COUVRIR, et laisser cuire à feu doux pendant 1 heure, remuer de temps en temps."]' where recette_id = 'd91ee6bdf618439846d0d761542fdacf';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 15 min Repos : - Cuisson : 1 h'', ''Étape 1 Dans un saladier, mettre la viande, l\''oignon et la carotte finement coupés, l\''ail épluché, le thym et le laurier, le poivre et le zeste d\''orange coupé.\nÉtape 2 Verser le vin et laisser macérer de 12 à 24h au frais.\nÉtape 3 Le lendemain, égoutter la viande et la faire revenir dans une sauteuse, dans l\'' huile très chaude, morceau après morceau , la déposer dans une cocotte minute.\nÉtape 4 Porter ensuite la marinade et ses ingrédients à ébullition dans la sauteuse ayant servi pour la viande pendant 5 mn.\nÉtape 5 Verser sur la viande, saler (mais pas trop car on va ajouter des olives en fin de cuisson), ajouter la sauce tomate.\nÉtape 6 Fermer la cocotte minute et laisser cuire 1h30 à partir de la rotation de la soupape qui doit tourner à vitesse lente (le feu ne doit pas être trop vif pour éviter que la viande "n\''attrape"au fond).\nÉtape 7 Laisser refroidir la cocotte, ouvrir et rajouter les olives noires et 2 cuillerées à soupe d\''huile d\''olive.'']' where recette_id = '3e6c37b20fd771158822f5f70807e8ba';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 30 min Repos : - Cuisson : 45 min'', "Étape 1 Faire revenir le poulet dans l''huile d''arachide bien chaude.\nÉtape 2 Les réserver (les retirer du feu).\nÉtape 3 Faire revenir les oignons et le piment oiseau jusqu''à coloration.\nÉtape 4 Rajouter ensuite la tomate concentrée et les deux gousses d''ail (ciselé). Laisser cuire 2 mn.\nÉtape 5 Rajouter l''eau, les pommes de terre et les patates douces. Laisser cuire pendant 20 mn.\nÉtape 6 Rajouter ensuite la pâte d''arachide, assaisonner (sel poivre).\nÉtape 7 Aprés 2 mn de cuisson ajouter le netatou et laisser cuire jusqu''à épaississemnt de la sauce (bien consistant).\nÉtape 8 Remettre le poulet dans la sauce avec les deux piments antillais (sans les écraser surtout !).\nÉtape 9 Laisser cuire à feu doux et à semi couvert pendant 30 mn."]' where recette_id = '5155a1b02d84cf60b1ef7df0236d923c';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 30 min Repos : - Cuisson : 45 min'', "Étape 1 Méthode:\nÉtape 2 - Faire revenir les oignons et les retirer quand ils sont dorés\nÉtape 3 - Faire revenir toutes les viandes, sauf les merguez, que l''on cuira au dernier moment. Réserver.\nÉtape 4 - Dans le faitout, ajouter un peu d''huile d''olive et faire revenir tous les légumes sauf les courgettes et les pois chiches s''ils sont cuits/en conserve. Ajouter les tomates coupées, puis leur jus.\nÉtape 5 - A ce stade, on ajoute les épices, dont la quantité est à ajuster au goût de chacun... Mais on trouve des épices à couscous tout prêts\nÉtape 6 Pour nous:\nÉtape 7 - cumin, paprika, safran, 4 épices, ras el hanout, gingembre et un soupçon de cannelle\nÉtape 8 Ensuite, on couvre de bouillon de viande corsé, et on laisse cuire 1h30 à petits bouillons.\nÉtape 9 10 minutes avant la fin de la cuisson, on rajoute les courgettes et éventuellement les pois chiches.\nÉtape 10 Voilà pour le plat, maintenant, il faut s''occuper de la graine... et il y a une très bonne recette sur le site!\nÉtape 11 http://www.marmiton.org/Recettes/Recette_le-couscous-d-ahmed-et-nadia-maroc_32003.aspx"]' where recette_id = '6379e20cc57751787ac5e471731cc467';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 15 min Repos : - Cuisson : 1 h'', "Étape 1 Fariner les morceaux de dinde. Dans une sauteuse, les mettre à dorer dans l''huile, puis ajouter les oignons.\nÉtape 2 Une fois dorés, verser le vin blanc et le bouillon, tourner avec une spatule an bois, puis ajouter un à un tout les autres ingrédients, bien délayer, couvrir et laisser mijoter à feu doux pendant 1 h en tournant de temps en temps.\nÉtape 3 Servir avec du riz ou des pâtes."]' where recette_id = '9bfa831225bf6c6d422d8daa47820485';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 15 min Repos : - Cuisson : 1 h'', "Étape 1 DEUX FACONS TRÈS SIMPLES DE PRÉPARER CETTE RECETTE :\nÉtape 2 1) Couper le paleron en cubes, le mettre à mariner (au moins 1 h) dans 1/2 l de vin rouge avec les légumes émincés (oignons, ail et carottes) + laurier + grains de poivre, coriandre et genièvre.\nÉtape 3 Faire revenir les morceaux de viande dans l''huile chaude et à feu vif dans un autocuiseur. Quand la viande est bien dorée ajouter la marinade et tous les ingrédients, faire bouillir le vin 2 à 3 mn, écumer, ajouter le coulis de tomate. Fermer l''autocuiseur, faire mijoter 1 h à chuchotement. Si à l''issue de la cuisson vous trouvez la sauce trop liquide, vous pouvez épaissir avec la Maïzena (moi je la trouve très bien telle qu''elle).\nÉtape 4 2) Faire la même recette mais sans marinade et dans ces conditions faire revenir la viande, ajouter les légumes et les épices, et couvrir entièrement de coulis de tomates. Le reste ne change pas.\nÉtape 5 Vous accompagnerez ce plat au choix : pâtes, pommes de terre à la vapeur ou frites, boulgour, polenta."]' where recette_id = 'a401d3823ac68cc6ea1fe2735e99a89d';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 15 min Repos : - Cuisson : 1 h'', "Étape 1 Cette recette est extrêmement simple.\nÉtape 2 Il vous suffit de mettre le poulet dans un plat à four.\nÉtape 3 Pendant ce temps-là, préchauffer le four à 210-240°C (thermostat 7-8).\nÉtape 4 Prenez le beurre et découpez-le en morceaux pour le mettre sur le poulet un peu partout.\nÉtape 5 Salez, poivrez et herbez la bête...\nÉtape 6 Ensuite, attaquez-vous au patates... Il faut les éplucher et puis les faire tremper dans l''eau pour les rincer et les essuyer.\nÉtape 7 Il faut après les découper.\nÉtape 8 Alors, là, c''est comme vous le sentez... faites de jolies formes si vous le voulez, moi, je fais simplement des carrés.\nÉtape 9 En fait, je prends la pomme de terre, la découpe en longueur, la tourne, et puis après la découpe dans l''autre longueur et puis je la tourne dans l''autre sens pour la découper en largeur... et ça, ça fait des sortes de carrés.\nÉtape 10 Et je mets toutes les pommes de terres dans le plat autour du poulet. Les sale.\nÉtape 11 Et puis direction le four après avoir arrosé le tout d''un demi-verre d''eau.\nÉtape 12 Je laisse cuire 1h15... plus ou moins en fonction du poulet et des pommes de terre.\nÉtape 13 Je le tourne régulièrement pendant la cuisson, sur chaque face... Et puis s''il le faut je réarrose d''eau... comme ça, les pommes de terre baignent dans le jus.\nÉtape 14 Une fois que c''est prêt et bien il suffit de servir !"]' where recette_id = '8186eb24352251de60c2e2f433926f2c';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 45 min Repos : - Cuisson : 30 min'', "Étape 1 Il existe sur la toile deux écoles du risotto aux champignons, à savoir celle du champignon qui cuit dans le riz, et celle des champignons poêlés ajoutés à la dernière minute. Ayant longtemps pratiqué les deux recettes, je souhaitais vous communiquer la mienne :\nÉtape 2 Séparer les champignons en deux (préférer des cèpes) : une partie servira à élaborer le bouillon et cuira avec le riz. L''autre partie sera poêlé au dernier moment pour la présentation et mettre en avant le champignon tout en conservant une texture ferme.\nEmincer un petit peu d''ail, d''échalote et de persil séparément et réserver.\nÉtape 3 Nettoyer les champignons et les couper en morceaux.\nÉtape 4 Faire blondir dans une casserole un demi-oignon émincé dans un mélange de beurre et d''huile d''olive.\nÉtape 5 Ajouter et poêler les champignons.\nÉtape 6 Ajouter du bouillon de légumes ou de poule (assez pour nourrir le risotto).\nÉtape 7 Laisser mijoter le bouillon pour qu''il s''imprègne bien du goût et des saveurs des champignons.\nÉtape 8 Chauffer une nouvelle casserole (qui accueillera le risotto), ajouter un peu d''huile d''olive et de beurre que vous ferez blondir.\nÉtape 9 Ajouter le riz carnaroli et remuer jusqu''à le rendre translucide (attention à la température, le riz ne doit pas coller).\nÉtape 10 Déglacer avec un verre de vin blanc sec. Continuer à remuer pour que le riz n''adhère pas et laisser réduire l''alcool.\nÉtape 11 Verser une louche de bouillon que vous avez laissé mijoter et continuer à remuer constamment jusqu''à l''absorption totale du riz.\nÉtape 12 Réitérer l''étape 11 jusqu''au point de cuisson (préférer al dente).\nÉtape 13 Juste avant la fin, faire fondre du beurre et un peu d''huile d''olive dans une poêle tout en remuant le risotto.\nÉtape 14 Faire blondir l''échalote émincée dans la poêle puis ajouter l''ail (attention à ne pas le brûler).\nÉtape 15 Faire poêler les champignons tout en remuant le risotto, assaisonner et ajouter le persil émincé en fin de cuisson avec un tour de moulin à poivre puis réserver.\nÉtape 16 Assaisonner le risotto juste avant la fin.\nÉtape 17 Ciseler du persil et en parsemer au dessus.\nÉtape 18 Dresser le riz dans des assiettes creuses. Placer soigneusement sur le haut les champignons poêlés.\nÉtape 19 Servir avec un tour de moulin à poivre et du parmesan.\nÉtape 20 Le gras du beurre va s''opposer au salé du parmesan et à l''amertume du cèpe en arrière plan. Les puristes privilégieront un rouge italien d''âge moyen avec une structure légère mais à la fois ronde et consistante. Personnellement, je préfère un blanc sec minéral un peu évolué au accent de sous-bois. Un bourgogne fera parfaitement l''affaire. Bon appétit"]' where recette_id = '8a80d31a028ce8acff219c58144cf807';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 15 min Repos : - Cuisson : 1 h'', "Étape 1 Faire de petites incisions dans le rôti en y mettant des lamelles d''ail.Préchauffer le four 10 min à 210°C (thermostat 7).\nÉtape 2 Verser dans un plat allant au four les champignons et le jus, poser le rôti et entourer de petits morceaux d''ail. Verser un filet d''huile de tournesol autour du rôti.\nÉtape 3 Ajouter 10 cl d''eau et mettre au four 1 h 30 (30 min par livre) en le retournant à mi-cuisson. Vérifier qu''il ne manque pas de jus sinon ajouter un peu d''eau.\nÉtape 4 A la fin de la cuisson laisser le rôti 10 min four éteint dans une assiette, la viande sera beaucoup plus tendre.\nÉtape 5 Enfin, saler et poivrer la viande. Servir avec des pommes de terre ou des petits pois."]' where recette_id = '443bfbd1656fef18d93b101efc219ecb';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 15 min Repos : - Cuisson : 1 h'', "Étape 1 Faites chauffer l''huile dans une cocotte.\nÉtape 2 Couper les oignons en lamelles.\nÉtape 3 Les faire dorer dans la cocotte à feu doux pendant environ 10 minutes en remuant souvent.\nÉtape 4 Ajouter les morceaux de porc et le curry et mélanger pendant environ 5 minutes de façon à bien dorer le tout.\nÉtape 5 Ajouter le lait de coco et la boîte de tomate non égouttée et bien remuer.\nÉtape 6 Laisser mijoter le tout à feu doux pendant environ 45 minutes en remuant de temps en temps."]' where recette_id = '05aa84ab2bd502425d21a3ad77b75828';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 15 min Repos : - Cuisson : 1 h'', "Étape 1 Verser 3/4 de cuillère à soupe d''huile dans le plat à tajine directement posé sur le feu ou la plaque.\nÉtape 2 Lorsque l''huile est bien chaude, faire revenir la viande de chaque côté (environ 10 min).\nÉtape 3 Baisser un peu le feu et placer les légumes, lavés et découpés grossièrement, en pyramide sur la viande, des plus fermes aux plus tendres (pommes de terre, puis carotte, puis courgettes, puis oignons), en les intercalant de cumin, 14 épices, sel et poivre.\nÉtape 4 Arroser d''un peu d''eau, saupoudrer de safran jaune, pour donner de la couleur et déposer les olives vertes.\nÉtape 5 Couvrir et laisser cuire à feu doux, pendant 30 mn.\nÉtape 6 Au bout de ce temps, placer sur les légumes cuits, les tomates coupées en morceaux, couvrir et laisser cuire encore 15mn.\nÉtape 7 Servir chaud, directement sur la table, accompagné de thé et de pain sans levain."]' where recette_id = '9bfde6fbdb827b750c8b3e4550168322';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 15 min Repos : - Cuisson : 1 h'', "Étape 1 Eplucher les pommes de terre, les couper en dés, bien les rincer et les essuyer dans un torchon propre.\nÉtape 2 Faire chauffer l''huile dans une poêle, y faire fondre les oignons.\nÉtape 3 Lorsque les oignons sont fondus, ajouter les pommes de terre et les faire dorer de tous les côtés.\nÉtape 4 Lorsqu''elles sont dorées, ajouter les lardons et finir de cuire. Éponger le surplus de gras avec une feuille de papier essuie-tout.\nÉtape 5 D''autre part, gratter la croûte du reblochon et le couper en deux (ou en quatre).\nÉtape 6 Préchauffer le four à 200°C (thermostat 6-7) et préparer un plat à gratin en frottant le fond et les bords avec la gousse d''ail épluchée.\nÉtape 7 Dans le plat à gratin, étaler une couche de pommes de terre aux lardons, disposer dessus la moitié du reblochon, puis de nouveau des pommes de terre. Terminer avec le reste du reblochon (croûte vers les pommes de terre).\nÉtape 8 Enfourner pour environ 20 minutes de cuisson."]' where recette_id = 'e3cbd0940d6d7c9d0602e48b3ba23e76';
update fact_recette_base set etapes = '[''Préparation 1h15 Préparation : 15 min Repos : - Cuisson : 1 h'', "Étape 1 Faire dorer les oignons dans de l''huile d''olive à feu moyen, jusqu''à ce qu''ils soit transparents.\nÉtape 2 Ajouter la moitié du curry, puis faites dorer les escalopes en remuant de temps en temps. Saler et poivrer.\nÉtape 3 Baisser le feu, et ajouter le gimgembre, puis couvrir de lait de coco, ajouter le reste du curry, et les copeaux de coco, et les champignons si souhaité.\nÉtape 4 Laisser mijoter environ 30 mn. Servir chaud accompagné de riz thaï. bon appétit!"]' where recette_id = 'c8cdec62c6d5c62b5242ddc1c0b5accc';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 20 min Repos : - Cuisson : 1 h'', "Étape 1 Dans une grande casserole, porter à ébullition 1,5 l d''eau salée avec la tablette de bouillon de volaille. Quand l''eau commence à bouillir, y mettre les morceaux de poulet et laisser cuire quinze minutes.\nÉtape 2 Dans une cocotte faire fondre 20 g de beurre, ajouter les oignons et les lardons, laisser mijoter lentement.\nÉtape 3 Retirer le poulet du feu, ajouter les morceaux dans la cocotte et réserver le jus.\nÉtape 4 Dans une casserole faire fondre le reste du beurre, ajouter la farine et remuer deux minutes puis ajouter petit à petit la moitié du jus de cuisson du poulet pour obtenir une sauce onctueuse.\nÉtape 5 Verser la sauce dans la cocotte, ajouter les champignons de paris puis saler et poivrer.Laisser mijoter à feu doux pendant trente minutes.\nÉtape 6 Pour servir, égoutter les légumes et le poulet avec une écumoire, les disposer dans un plat de service chaud. Garder la sauce dans la cocotte et mélanger une minute à feu doux puis napper le plat avec cette sauce. Parsemer de ciboulette et servir aussitôt."]' where recette_id = 'b6e54f83c7e18af58a3dd80fc8132c00';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 20 min Repos : - Cuisson : 1 h'', "Étape 1 Couper la viande en morceaux égaux. La faire revenir dans une cocotte en fonte, dans laquelle vous avez fait chauffer la matière grasse.\nÉtape 2 Une fois les morceaux revenus de tous les côtés, les retirer et faire revenir les oignons émincés et les lardons.\nÉtape 3 Préparer le bouillon de boeuf avec 1/2 litre d''eau.\nÉtape 4 Ajouter la viande dans la cocotte, y verser le bouillon, le concentré de tomates, les carottes épluchées et coupées en tronçons, l''ail et les herbes.\nÉtape 5 Assaisonner avec le sel etle poivre, mélanger et laisser mijoter 1h30 à feu doux."]' where recette_id = '0f4488cc36aa9cd12856a9b431a61f2c';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 20 min Repos : - Cuisson : 1 h'', ''Étape 1 Le soir avant, mettre la cuisse dans votre plat rectangulaire ou ovale et inciser la cuisse plusieurs fois en introduisant un bout d’ail (aidez vous du couteau en écartant la fente et pousser avec les doigts).\nÉtape 2 Enduire de moutarde douce partout, parsemer d’herbes, recouvrir d’une feuille d’alu et mettre au frigo jusqu’au lendemain.\nÉtape 3 Le lendemain, sortir du frigo au moins une bonne heure avant la cuisson.\nÉtape 4 Préchauffez votre four à 180°C (chaleur à air pulsé, 200°C four conventionnel je pense)\nÉtape 5 Enduire la marinade de partout (de préférence avec un pinceau culinaire, c’est plus facile),  saler à votre goût et versez 10 cl d’eau tout au tour. Mettre au milieu du four pendant 1 heure en arrosant avec le jus très régulièrement (ajoutez de l’eau autour quand nécessaire).\nÉtape 6 Eteindre le four, sortir le plat et recouvrir avec l’alu déjà utilisé pendant 15 min.\nÉtape 7 Coupez la cuisse en tranches, les mettre dans le plat et les retourner pour bien imbiber du jus. Recouvrir à nouveau avec l’alu et remettre dans le four pendant quelques min.\nÉtape 8 Accompagnez de légumes, riz, purée, pommes de terre rissolées ou tagliatelles (salade) d’après votre choix.\nÉtape 9 BON APPETIT !'']' where recette_id = '3233892ca2066afcde3197c9956a4374';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 25 min Repos : - Cuisson : 55 min'', "Étape 1 Faire préchauffer votre four à 200°C (thermostat 7).\nÉtape 2 Laver et éplucher les pommes de terre.\nÉtape 3 Les découper en fins bâtonnets afin d''en faire des frites.\nÉtape 4 Dans une plaque de four tapissée de papier sulfurisé, disposer vos frites, les saler, les huiler et les faire cuire au four 40 minutes à 180°C\nÉtape 5 Pendant ce temps, découper les steaks hachés en petits morceaux, les faire cuire dans une poêle.\nÉtape 6 Dans une casserole, faire chauffer 50 cl de crème. Ajouter en 2 fois les 100g de fromage rappé tout en fouettant continuellement afin d''éviter la formation de grumeaux. Poivrer et saler.\nÉtape 7 Une fois que tout est cuit et la sauce fromagère prête, disposer 2 tortillas en les faisant se chevaucher. Répartir la viande et les frites en 5 portions pour les 5 tacos.\nÉtape 8 Assaisonner vos tortillas avec la sauce et recouvrir de cuillères de sauce fromagère.\nÉtape 9 Plier les tortillas en commençant par les longueurs puis replier par dessus les largeurs.\nÉtape 10 Placer le tout dans un grill chaud pendant 5 minutes."]' where recette_id = '751cc4e749ef7a83ef23eea34b7f8b5f';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 45 min Repos : - Cuisson : 35 min'', "Étape 1 Si vous utilisez des oignons, faites-les revenir (dans une sauteuse ou un wok) jusqu''à ce qu''ils soient fondants.\nÉtape 2 Coupez les tomates, ajoutez-les aux oignons, puis faites mijoter  avec des herbes de Provence (n''hésitez pas !), sel et poivre.\nÉtape 3 Coupez les courgettes en rondelles puis incorporez-les au mélange.\nÉtape 4 Ajoutez de la sauce tomate (ou de la purée de tomate, à défaut), et 1 cuillère à café de sucre en poudre (plus en hiver, quand les tomates sont plus fades).\nÉtape 5 Laissez mijoter l''ensemble, 20 min environ, à feu moyen.\nÉtape 6 Une fois le mélange prêt, procédez à l''empilement dans un grand plat :\nÉtape 7 1 couche de lasagnes, 1 couche de préparation, 1 couche de béchamel, 1 couche de gruyère, et ainsi de suite (en rajoutant un peu de sel à chaque fois), en mettant beaucoup de gruyère sur la dernière couche.\nÉtape 8 Faites cuire à four chaud (thermostat 7-200°C), 35 minutes\nÉtape 9 Servez, lorsque c''est bien gratiné."]' where recette_id = 'efb9d9fe0acc8539a1aa3e440c2455e5';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 20 min Repos : - Cuisson : 1 h'', "Étape 1 Coupez grossièrement les oignons en lamelles, l''ail en quatre (enlever le germe vert au milieu), et ciselez le persil et la coriandre.\nÉtape 2 Mettez un fond d''huile d''olive dans une marmite (ou cocotte) et y ajoutez le poulet découpé en morceaux. salez et poivrez.\nÉtape 3 Faites légèrement dorer le poulet à feu moyen en remuant de temps en temps. Une fois le poulet doré, ajoutez dans la marmite :  20 cl d''eau, les oignons, l''ail, toutes les épices et 1 poignées d''olives vertes. Remuez.\nÉtape 4 Laisser mijoter... 20-25 min en remuant de temps en temps (pour avoir beaucoup de sauce ajoutez de l''eau au fur et à mesure de la cuisson et des épices si besoin).\nÉtape 5 Lorsque le poulet est cuit, retirez-le de la marmite et ajoutez le reste des olives, mélangez bien et laissez de nouveau mijoter à feu doux.\nÉtape 6 Au moment de servir, placez les morceaux de poulet dans un grand plat en versant la sauce (et les olives vertes) par-dessus... c''est prêt !! Vous pouvez accompagner ce plat de quelques pommes de terre cuites à l''eau mais surtout prévoyez beaucoup de pain !! Vous allez adorez la sauce !!"]' where recette_id = '6b3fd92b2dee7b7b54616a50388145eb';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 20 min Repos : - Cuisson : 1 h'', "Étape 1 Hacher l''oignon et l''ail. Couper les tomates en morceaux et détailler les poivrons en lanières.\nÉtape 2 Faire chauffer 4 cuillères à soupe d''huile dans une cocotte. Y faire dorer les oignons, l''ail et les poivron. Laisser cuire 5 min.\nÉtape 3 Ajouter les tomates à la cocotte, saler, poivrer. Couvrir et laisser mijoter 20 min.\nÉtape 4 Dans une sauteuse, faire dorer dans l''huile d''olive les morceaux de poulet salés et poivrés.\nÉtape 5 Lorsqu''ils sont dorés, les ajouter aux légumes, couvrir, ajouter le bouquet garni et le vin blanc et c''est parti pour 35 min de cuisson."]' where recette_id = 'c8e2715a707fd0596f67f7fbda1bdd80';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 25 min Repos : - Cuisson : 55 min'', "Étape 1 Coupez les tomates pelées en quartiers,\nÉtape 2 les aubergines et les courgettes en rondelles.\nÉtape 3 Emincez les poivrons en lamelles\nÉtape 4 et l''oignon en rouelles.\nÉtape 5 Chauffez 2 cuillères à soupe d''huile dans une poêle\nÉtape 6 et faites-y fondre les oignons et les poivrons.\nÉtape 7 Lorsqu''ils sont tendres, ajoutez les tomates, l''ail haché, le thym et le laurier.\nÉtape 8 Salez, poivrez et laissez mijoter doucement à couvert durant 45 minutes.\nÉtape 9 Pendant ce temps, préparez les aubergines et les courgettes. Faites les cuire séparemment ou non dans l''huile d''olive pendant 15 minutes.\nÉtape 10 Vérifiez la cuisson des légumes pour qu''ils ne soient plus fermes. Ajoutez les alors au mélange de tomates et prolongez la cuisson sur tout petit feu pendant 10 min.\nÉtape 11 Salez et poivrez si besoin."]' where recette_id = '4a03a0b484559e9bb4d6f02b2539696c';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 20 min Repos : - Cuisson : 1 h'', "Étape 1 Mettre de l''eau à bouillir et y blanchir le chou 3 à 4 minutes.\nÉtape 2 Eplucher et couper tous les légumes en morceaux.\nÉtape 3 Une fois le chou refroidi, le couper en morceaux.\nÉtape 4 Remplir à moitié une marmite d''eau et y mettre tous les légumes, le sel, le poivre, le thym, le laurier et les saucisses, ainsi que les cubes de bouillon culinaire.\nÉtape 5 Laisser mijoter 1 heure 30."]' where recette_id = '2e691dc7f2276eb3c8e0b971759ce141';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 20 min Repos : - Cuisson : 1 h'', "Étape 1 Hachez l''ail, l''oignon, puis coupez la carotte et le céleri en petits dés (enlevez les principales nervures du céleri).\nÉtape 2 Faites chauffer l''huile dans une casserole assez grande. Faites revenir l''ail, l''oignon, la carotte et le céleri à feu doux pendant 5 min en remuant.\nÉtape 3 Augmenter la flamme, puis ajoutez le boeuf. Faites brunir et remuez de façon à ce que la viande ne fasse pas de gros paquets.\nÉtape 4 Ajoutez le bouillon, le vin rouge, les tomates préalablement coupées assez grossièrement, le sucre et le persil haché. Portez à ébullition.\nÉtape 5 Baisser ensuite le feu et laissez mijoter à couvert 1h à 1h30, de façon à ce que le vin s''évapore.\nÉtape 6 Faites cuire les spaghetti, puis mettez-les dans un plat.\nÉtape 7 Ajoutez la sauce bolognaise."]' where recette_id = 'ba9ab052b4a0fa25dda8e596b7a29e22';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 20 min Repos : - Cuisson : 1 h'', "Étape 1 Faites tremper les 500 g pruneaux dans du thé chaud. Faites revenir les oignons émincés dans l''huile d''olive. Quand ils sont dorés, retirez-les et remplacez-les par la viande.\nÉtape 2 Lorsque les morceux sont bien dorés, mettez-les dans une cocotte avec les oignons. Salez et poivrez. Ajoutez l''ail écrasé, la cannelle, le gingembre, la safran et les grains de coriandre.\nÉtape 3 Couvrez d''eau et faites cuire 1 heure à feu doux.\nÉtape 4 Ajoutez ensuite les pruneaux égouttés, puis poursuivez la cuisson 20 min à couvert.\nÉtape 5 Faites revenir les amandes dans un peu de beurre chaud. Egouttez-les puis ajoutez-les à la viande avec le miel.\nÉtape 6 Laissez cuire encore 5 min sans couvrir.\nÉtape 7 Servez accompagné de semoule de couscous."]' where recette_id = '9a84654923bc51db9ba4a580e3836722';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 20 min Repos : - Cuisson : 1 h'', "Étape 1 Eplucher et hacher les oignons. Eplucher et hacher les gousses d''ail.\nÉtape 2 Mettre la moitié des oignons dans la chair à saucisse. Ajouter l''ail, le sel, le poivre et un peu de persil.\nÉtape 3 Couper le haut des tomates et les évider. Poivrer et saler l''intérieur. Mettre la farce à l''intérieur et remettre les chapeaux.\nÉtape 4 Mettre le reste des oignons dans un plat avec la chair des tomates.\nÉtape 5 Mettre les tomates farcies dans le plat. Parsemez d''un peu de thym et mette une noisette de beurre sur chaque tomates. Faire cuire au four chaud à 180°C (thermostat 6) pendant 1 heure environ.\nÉtape 6 Servir avec du riz."]' where recette_id = '6561a6202f0163243f30f53e22fae31f';
update fact_recette_base set etapes = '[''Préparation 1h20 Préparation : 20 min Repos : - Cuisson : 1 h'', "Étape 1 Déposer la tête de veau dans une marmite remplie de l''eau bouillante salée avec l''oignon émincé et le bouquet garni.\nÉtape 2 Faire cuire pendant 20 min, ajouter les carottes en rondelle et les navets en dés.\nÉtape 3 Laisser mijoter à feu doux pendant 1 h 10.\nÉtape 4 Dans un bol, mélanger la moutarde, le vinaigre et l’huile. Assaisonner et incorporer un œuf écrasé, les radis finement émincés et le cerfeuil à la vinaigrette."]' where recette_id = 'b3b065df011093b18854b9c89b2311c4';
update fact_recette_base set etapes = '[''Préparation 1h25 Préparation : 25 min Repos : - Cuisson : 1 h'', "Étape 1 Eplucher, laver et couper les pommes de terre en rondelles fines (NB : ne pas les laver APRES les avoir coupées, car l''amidon est nécessaire à une consistance correcte).\nÉtape 2 Hacher l''ail très finement.\nÉtape 3 Porter à ébullition dans une casserole le lait, l''ail, le sel, le poivre et la muscade puis y plonger les pommes de terre et laisser cuire 10 à 15 min, selon leur fermeté.\nÉtape 4 Préchauffer le four à 180°C (thermostat 6) et beurrer un plat à gratin à l''aide d''une feuille de papier essuie-tout.\nÉtape 5 Placer les pommes de terre égouttées dans le plat. Les recouvrir de crème, puis disposer des petites noix de beurre sur le dessus.\nÉtape 6 Enfourner pour 50 min à 1 heure de cuisson.\n\nUtiliser le lait restant de la cuisson des pommes de terre pour faire une soupe ou une purée dans la foulée."]' where recette_id = '2eb71d945dfed4e4bbf0c5852ae5ed6d';
update fact_recette_base set etapes = '[''Préparation 1h25 Préparation : 25 min Repos : - Cuisson : 1 h'', ''Étape 1 Hacher finement oignons, ail et persil.\nÉtape 2 Tremper le pain de mie dans du lait tiède pour le ramollir.\nÉtape 3 Mélanger le mélange pain/lait avec tous les autres ingrédients.\nÉtape 4 Laver les poivrons et évider les (par le haut).\nÉtape 5 Farcir les poivrons et les mettre dans un plat à four.\nÉtape 6 Faire cuire au four à 200° pendant 1h. Retourner à mi-cuisson. Bon appétit !'']' where recette_id = '308999fa0b2033b4138ba4cbc9af6828';
update fact_recette_base set etapes = '[''Préparation 1h30 Préparation : 20 min Repos : 10 min Cuisson : 1 h'', "Étape 1 Chauffer l''huile d''olive dans une poêle, et faire dorer l''oignon et l''ail 10 min à feu doux, en remuant de temps en temps.\nÉtape 2 Mélanger la viande hachée et la chair à saucisse, à l''aide d''un robot.\nÉtape 3 Dans un saladier, mélanger la viande, les œufs, le sel et le poivre.\nÉtape 4 Puis, faire cuire le tout dans la poêle, pendant 10 bonnes min. Égoutter le plus de jus possible.\nÉtape 5 Beurrer un plat et étaler 1/3 de la sauce tomate au fond du plat.\nÉtape 6 Déposer la farce obtenue dans les cannelloni, à l''aide d''une cuillère à soupe, et les déposer dans le plat.\nÉtape 7 Verser le reste de la sauce sur les cannelloni, et parsemer le tout de mozzarella.\nÉtape 8 Enfourner 35 à 40 min au four à 180°C (th 6), jusqu''à ce que les cannelloni soient dorés, et que la sauce bouillonne.\nÉtape 9 Laisser reposer 10 min avant de servir. Bon appétit !"]' where recette_id = 'bef08ec28f787501e3369a79b02e3893';
update fact_recette_base set etapes = '[''Préparation 1h30 Préparation : 30 min Repos : - Cuisson : 1 h'', "Étape 1 Faire revenir les oignons préalablement émincés en rondelles dans la cocotte-minute. Ajouter les lardons.\nÉtape 2 Dans une poële, faire revenir le filet mignon sur tous les côtés.\nÉtape 3 Quand les oignons sont blonds et les lardons légèrement grillés, déposer le filet mignon au fond de la cocotte. Y verser 2 l de bouillon de boeuf. Déposer une branche de thym et deux feuilles de laurier.\nÉtape 4 Fermer la cocotte et faire cuire le tout pendant 45 minutes à partir de la rotation de la soupape.\nÉtape 5 Pendant ce temps, couper les pommes de terre en 6 et les carottes en grosses rondelles. Les faire revenir 5 min dans la poële.\nÉtape 6 Au bout de 45 minutes, laisser s''échapper la vapeur , ouvrir la cocotte et ajouter carottes et pommes de terre (elles doivent être recouvertes par le bouillon, sinon ajouter un peu d''eau).\nÉtape 7 Laisser cuire encore 10 à 15 minutes a partir de la rotation de la soupape.\nÉtape 8 Pendant ce temps préchauffer le four à 210°C (thermostat 7).\nÉtape 9 Après avoir fait évacuer la vapeur de la cocotte, en sortir le filet mignon et le déposer dans un plat à four. L''arroser du jus de cuisson.\nÉtape 10 Faire encore cuire 10 minutes à un quart d''heure au four.\nÉtape 11 Au dernier moment, ajouter au jus de cuisson la crème fraîche et mélanger délicatement.\nÉtape 12 C''est prêt!\nÉtape 13 Servir chaque tranche avec pommes de terre, carottes et arroser de jus (bouillon, lardons, oignons, crème fraîche)."]' where recette_id = 'fd9804c6ec2c109b03856bbef74708e9';
update fact_recette_base set etapes = '[''Préparation 1h30 Préparation : 30 min Repos : - Cuisson : 1 h'', "Étape 1 Couper les cuisses de poulet en séparant le pilon du haut.\nÉtape 2 Peler puis couper les carottes en rondelles. Peler puis émincer l''oignon et l''ail. Rincer les olives et les champignons.\nÉtape 3 Faire revenir les morceaux de poulet pour qu''ils soient bien dorés dans un mélange d''huile de tournesol, huile d''olive et beurre.\nÉtape 4 Une fois doré, le réserver dans un plat.\nÉtape 5 Dans le jus de cuisson, faire dorer puis réduire les oignons avec l''ail.\nÉtape 6 Incorporer ensuite le vin blanc et à la reprise de l’ébullition ajouter la farine en pluie tout en délayant.\nÉtape 7 Ajouter l''eau (chaude de la bouillotte) puis quand ébullition, ajouter le fond de veau en pluie et délayer.\nÉtape 8 Ajouter ensuite les champignons, les olives ainsi que les carottes.\nÉtape 9 Laisser mijoter quelques minutes (5) puis ajouter les morceaux de poulet.\nÉtape 10 Laisser mijoter doucement (couvert) pendant 30 min puis retourner les morceaux en remuant la sauce et laisser mijoter à nouveau 30 min (toujours couvert, ajuster la durée de mijotage en fonction de la nature du poulet (blanc, fermier etc...).\nÉtape 11 Servir ensuite accompagné en garniture de pâtes ou riz blanc en ajoutant la sauce sur le garniture.\nÉtape 12 Bon Appétit !"]' where recette_id = '5ea8ad6006b2df249de2d03ffad7a589';
update fact_recette_base set etapes = '[''Préparation 1h30 Préparation : 30 min Repos : - Cuisson : 1 h'', "Étape 1 Faire revenir le poulet à feu moyen pour qu''il soit un peu doré.\nÉtape 2 Pendant ce temps, peler et couper les légumes : couper les carottes en 2 , puis dans le sens de la longueur. Idem pour les courgettes. Couper les oignons en lamelles et les pommes de terres en 4.\nÉtape 3 Mettre les légumes avec le poulet, rajouter les épices à tajine et le cumin. Mettez également un peu d''eau (3/4 verre d''eau).\nÉtape 4 Laisser cuire environ 1 heure et voilà, c''est prêt !"]' where recette_id = '16e56f83ddbded506796883cd4047bbf';
update fact_recette_base set etapes = '[''Préparation 1h35 Préparation : 10 min Repos : - Cuisson : 1h25'', "Étape 1 Couper le chou en fine lamelles.\nÉtape 2 Faire blanchir dans de l''eau bouillante pendant 15 à 30 minutes.\nÉtape 3 Epelucher et emincer l''oignon.\nÉtape 4 Eplucher et couper en 4 les pommes de terres.\nÉtape 5 Dans une grosse cocotte minute, insérer l''huile d''olive et faire dorer l''oignon. Incorporer les lardons, les saucisses de morteaux et montbéliard ainsi que le rôti fumé, préalablement coupé en tranches. Faire dorer le tout pendant 10 minutes.\nÉtape 6 Une fois la viande dorée, ajouter les pommes de terres ainsi que le choux blanchi. Saler, poivrer, ajouter les bouquet garnis et laisser cuire le tout cocotte fermée au minimum 1h00.\nÉtape 7 Une fois cuit, sevir dans des assiettes et ajouter la crème."]' where recette_id = 'ab62931e00e15b7057d8257c8bcd293c';
update fact_recette_base set etapes = '[''Préparation 1h40 Préparation : 1 h Repos : - Cuisson : 40 min'', "Étape 1 Mélanger dans un bol la crème et le jus de citron avec une pincée de sel et de poivre (vous pourrez assaisonner plus si besoin). Réserver.\nÉtape 2 Faire chauffer l''huile dans une sauteuse et y mettre l''oignon émincé pendant 1 à 2 min.\nÉtape 3 Ajouter les aiguillettes. Saler, poivrer et laisser cuire à couvert 10 min.\nÉtape 4 Avec une fourchette, retourner les aiguillettes et terminer la cuisson à couvert 5 à 10 min.\nÉtape 5 Quand le poulet est cuit, arrêter le feu et verser la crème au citron. Assaisonner si besoin.\nÉtape 6 Servir avec du riz et des courgettes sautées ou vapeur."]' where recette_id = 'db1c3743f5aca2b30dcf7b4c56b1aea4';
update fact_recette_base set etapes = '[''Préparation 1h40 Préparation : 10 min Repos : - Cuisson : 1h30'', "Étape 1 Dans une cocotte, faire bouillir de l''eau additionnée de gros sel.\nÉtape 2 Couper le chou en 4, retirer le trognon, émincer et rincer à grande eau.\nÉtape 3 Blanchir le chou 15 à 20 min à compter de la reprise de l''ébullition.\nÉtape 4 Égoutter le chou et jeter l''eau de cuisson.\nÉtape 5 Dans la même cocotte, faire dorer, dans la matière grasse, l''oignon préalablement émincé avec les lardons.\nÉtape 6 Ajouter le chou précuit et poser les saucisses dessus.\nÉtape 7 Recouvrir au 3/4 d''eau.\nÉtape 8 Laisser cuire à feu moyen 1 à 2h selon si vous utilisez une cocotte-minute ou classique."]' where recette_id = 'd75b9d6d8bb176ec0ebaa4ae1d858aa1';
update fact_recette_base set etapes = '[''Préparation 1h40 Préparation : 10 min Repos : - Cuisson : 1h30'', "Étape 1 Dans un grand plat allant au four, mettre le beurre coupé en morceaux, poser les branches de thym et de laurier.\nÉtape 2 Tartiner les filets mignons de moutarde (sur tous les côtés), les poser dans le plat sur les branches de thym et laurier.\nÉtape 3 Saler et poivrer et mettre au four préchauffé à 210°C pendant 45 mn (retourner à mi-cuisson).\nÉtape 4 Pendant ce temps, éplucher les pommes de terre (les couper si elles sont grosses).\nÉtape 5 Faire cuire les pommes de terre à la vapeur.\nÉtape 6 Sortir le plat du four, retourner les filets mignons, ajouter 1 grand verre d''eau pour délayer la sauce, mettre les pommes de terre autour des filets mignons. Enfourner de nouveau pour environ 30 mn.\nÉtape 7 Bon appétit !"]' where recette_id = 'b290829287ab66be18a3d77515c4c1b4';
update fact_recette_base set etapes = '[''Préparation 1h40 Préparation : 40 min Repos : - Cuisson : 1 h'', "Étape 1 Éplucher les oignons et les couper en carrés. Faire cuire les cuisses de poulet à la poêle jusqu''à ce qu''elles soient bien dorées.\nÉtape 2 Pendant ce temps, préparer une marinade dans un saladier avec le\nÉtape 3 vinaigre, la moutarde, le poivre et le jus de citron, y mettre les oignons et bien mélanger. Laisser mariner 15 minutes.\nÉtape 4 Ensuite, faire revenir les oignons dans 2 cuillères à soupe d''huile, verser le reste de marinade, ajouter un peu d''eau et cuire un dizaine de minutes à feu doux. Ajouter le piment (à doser en fonction du piquant désiré) et le cube maggi écrasé.\nÉtape 5 Mélanger et cuire jusqu''à ce que les oignons soient bien fondants (ne pas hésiter à mettre un peu d''eau s''ils attachent en cours de cuisson).\nÉtape 6 Une fois les oignons cuits, ajouter le poulet et laisser sur le feu le temps qu''il réchauffe.\nÉtape 7 Cuire le riz à la vapeur et servir dans un grand plat avec les cuisses de poulet et la sauce aux oignons."]' where recette_id = 'aede02b54120ff951b1ab251e53e1208';
update fact_recette_base set etapes = '[''Préparation 1h45 Préparation : 45 min Repos : - Cuisson : 1 h'', "Étape 1 Désosser le gigot d''agneau, le découper en cubes de 4 cm. Les mettre à mariner dans de l''huile d''olive et des herbes de provences pendant 1 heure.\nÉtape 2 Badigeonner le poulet d''huile d''olive et le recouvir de fleur de sel, le faire cuire à la tourne broche dans le four pendant 1h à 1h30.\nÉtape 3 Eplucher tous les légumes et les oignons, les détailler en gros cubes.\nÉtape 4 Faire revenir les morceaux de collier dans le couscoussier à l''huile d''olive, les retirer et y mettre tous les légumes à revenir sauf les courgettes.\nÉtape 5 Couvrir d''eau, saler, y ajouter le concentré de tomate, les tomates pelées, le safran, le paprika, le Ras el hanout et les morceaux de collier.\nÉtape 6 Laisser mijoter le tout durant 1h à 1h30, ajouter les courgettes au bout de 30 minutes de cuisson et les pois chiches 20 minutes avant la fin de la cuisson.\nÉtape 7 Préparer la semoule en la faisant cuire à la vapeur dans le haut du couscoussier et en la roulant plusieurs fois, y ajouter du beurre à la fin.\nÉtape 8 Piquer les morceaux d''agneaux marinés sur des brochettes en alternant avec un ou deux morceaux d''oignons.\nÉtape 9 Les faire cuire au grill viande ou au barbecue.\nÉtape 10 Faire cuire les merguez au grill viande ou au barbecue.\nÉtape 11 Découper le poulet.\nÉtape 12 Servir le tout accompagné de harrissa( selon les goûts)."]' where recette_id = 'b6c5de95206f04b26c01b6b9812d4e43';
update fact_recette_base set etapes = '[''Préparation 1h45 Préparation : 15 min Repos : - Cuisson : 1h30'', "Étape 1 Mettez le beurre à fondre dans une cocotte en fonte.\nÉtape 2 Faites blondir les échalotes finement coupées.\nÉtape 3 Ajoutez la viande et faites-la dorer.\nÉtape 4 Rajoutez les gousses d''ail, salez et poivrez la viande.\nÉtape 5 Versez le vin, mettez le laurier dans la sauce et saupoudez la viande de thym.\nÉtape 6 Rajoutez l''eau.\nÉtape 7 Laissez mijoter 1h30 environ à feu doux.\nÉtape 8 Tournez la viande de temps en temps."]' where recette_id = 'abb1d68732f006814f3356e8a8748755';
update fact_recette_base set etapes = '[''Préparation 1h45 Préparation : 15 min Repos : - Cuisson : 1h30'', ''Étape 1 Pour cette recette prévoir un plat à tajine (ou à défaut 1 cocotte en fonte). Faire cuire à feu moyen dans l’huile d’argan les oignons en lamelles et 2 gousses d’ail hachées.\nÉtape 2 Saler et poivrer les morceaux de poulet, puis les ajouter aux oignons et à l’ail pour les faire dorer 5 à 10 minutes en les retournant plusieurs fois.\nÉtape 3 Ajouter les épices, le jus de citron, le verre d’eau et les 3 gousses d’ail restantes en chemises.\nÉtape 4 Couvrir la tajine ou la cocotte et la mettre dans le four à 150°C (thermostat 5) pendant une heure.\nÉtape 5 La sortir du four et ajouter les olives, les citrons confits coupés en 4 et la coriandre.\nÉtape 6 La remettre au four 30min à 150°C (thermostat 5).\nÉtape 7 Servir très chaud avec de la semoule nature ou des pommes de terre vapeur.'']' where recette_id = '99867a6339050f9865a7f1ed15651774';
update fact_recette_base set etapes = '[''Préparation 1h50 Préparation : 20 min Repos : - Cuisson : 1h30'', "Étape 1 Découper la viande en morceaux comme pour un bœuf bourguignon.\nÉtape 2 Dans une cocotte minute, faire revenir la viande et les lardons dans le beurre.\nÉtape 3 Ajouter les oignons émincés, les champignons et les carottes coupées en morceaux.\nÉtape 4 Saupoudrer de farine. Mélanger.\nÉtape 5 Laisser revenir un instant.\nÉtape 6 Mouiller avec le vin rouge qui doit recouvrir la viande.\nÉtape 7 Saler et poivrer.\nÉtape 8 Ajouter l''ail et le bouquet garni.\nÉtape 9 Fermer la cocotte minute et laisser cuire à feu doux 1h30 à partir de la mise en rotation de la soupape.\nÉtape 10 On peut servir ce bourguignon avec une purée."]' where recette_id = 'f68a2f6a1b4bff5d4037bfba2b22fce4';
update fact_recette_base set etapes = '[''Préparation 1h55 Préparation : 15 min Repos : - Cuisson : 1h40'', "Étape 1 Préchauffer le four à 200°C (thermostat 6).\n Placer à l''intérieur du poulet deux gousses d''ail et les feuilles de laurier.\nÉtape 2 Préparer la sauce en mélangeant le jus de citron et le verre de bouillon de volaille. Arroser copieusement le poulet et verser le reste du jus dans le plat.\nÉtape 3 Saupoudrer le gros sel sur le poulet.\nÉtape 4 Placer le poulet dans le plat, avec les oignons coupés en quatre et les tomates cerises.\nÉtape 5 Placer le poulet au four durant environ 1 heure 40 à 200°C. (Au bout de 20 min de cuisson, retourner le poulet et laisser cuire 20 min, puis le replacer à l''endroit pour la suite de la cuisson)\nÉtape 6 Attention : Arroser le poulet avec son jus le plus souvent possible durant la cuisson (ajouter de l''eau si nécessaire). Le poulet n''en sera que plus moelleux !\nÉtape 7 Récupérer le jus à la fin de la cuisson, avec les tomates et les oignons, dans un bol, et placer sur la table, avec une belle salade verte et une poêlée de pommes de terres nouvelles."]' where recette_id = '287485923ab6da9e763c2824ed3a4f0e';
update fact_recette_base set etapes = '[''Préparation 2 h Préparation : 1 h Repos : - Cuisson : 1 h'', "Étape 1 La veille faire dessaler la morue si besoin, et cuire les bulots.\nÉtape 2 Le lendemain préparer les légumes. Eplucher pommes de terre et carottes, défaire le chou fleur.\nÉtape 3 Cuire les légumes à la cocotte-minute le temps indiqué pour chaque légume.\nÉtape 4 Réserver dans un plat.\nÉtape 5 Faire l''aïoli :\nÉtape 6 écraser la ou les gousses d''ail dans un bol puis monter une mayonnaise : fouetter les jaunes d''oeuf avec l''huile jusqu''à ce que la sauce monte. Assaisonner. Mettre au frais jusqu''au moment de servir.\nÉtape 7 Cuire la morue ou le cabillaud au court bouillon.\nÉtape 8 Peut se manger froid. Sinon faire réchauffer les légumes.\nÉtape 9 Présenter le poisson au milieu du plat entouré des légumes sans oublier les oeufs durs, les bulots, et l''aïoli..."]' where recette_id = 'ebf2792eea24e79ce72496fd486b1fc6';
update fact_recette_base set etapes = '[''Préparation 2h05 Préparation : 5 min Repos : - Cuisson : 2 h'', ''Étape 1 Dans une cocotte en fonte, déposer les cuisses de canard.\nÉtape 2 Verser la graisse de canard par dessus les cuisses.\nÉtape 3 Faire mijoter à couvert pendant 2 heures, en tournant régulièrement les cuisses.'']' where recette_id = '4dd9900e0075e817cb9aec0e84d3d0ad';
update fact_recette_base set etapes = '[''Préparation 2h05 Préparation : 30 min Repos : - Cuisson : 1h35'', "Étape 1 Faire revenir gousses hachées d''ail et les oignons émincés dans un peu d''huile d''olive.\nÉtape 2 Ajouter la carotte et la branche de céleri hachée puis la viande et faire revenir le tout.\nÉtape 3 Au bout de quelques minutes, ajouter le vin rouge. Laisser cuire jusqu''à évaporation.\nÉtape 4 Ajouter la purée de tomates, l''eau et les herbes.\nSaler, poivrer, puis laisser mijoter à feu doux 45 minutes.\nÉtape 5 Préparer la béchamel : faire fondre 100 g de beurre.\nÉtape 6 Hors du feu, ajouter la farine d''un coup.\nÉtape 7 Remettre sur le feu et remuer avec un fouet jusqu''à l''obtention d''un mélange bien lisse.\nÉtape 8 Ajouter le lait peu à peu.\nÉtape 9 Remuer sans cesse, jusqu''à ce que le mélange s''épaississe.\nÉtape 10 Ensuite, parfumer avec la muscade, saler, poivrer. Laisser cuire environ 5 minutes, à feu très doux, en remuant. Réserver.\nÉtape 11 Préchauffer le four à 200°C (thermostat 6-7).\nHuiler le plat à lasagnes. Poser une fine couche de béchamel puis des feuilles de lasagnes, de la bolognaise, de la béchamel et du parmesan.\nRépéter l''opération 3 fois de suite.\nÉtape 12 Sur la dernière couche de lasagnes, ne mettre que de la béchamel et recouvrir de fromage râpé. Parsemer quelques noisettes de beurre.\nÉtape 13 Enfourner pour environ 25 minutes de cuisson.\nÉtape 14 Déguster"]' where recette_id = 'bc9926e4f43e3b003d8c52f0de2aff81';
update fact_recette_base set etapes = '[''Préparation 2h10 Préparation : 40 min Repos : - Cuisson : 1h30'', "Étape 1 Séparer les feuilles de choux.\nÉtape 2 Faire blanchir les feuilles 10 min dans l''eau bouillante.\nÉtape 3 Préparer la farce du chou. \nMélanger les viandes dans un saladier. Saler et poivrer. \nAjouter les biscottes émiettées, le persil ciselé et l''ail haché. Bien mélanger.\nÉtape 4 Egoutter les feuilles du chou.\nÉtape 5 Etaler par 2 ou 3.\nDisposer dessus un quart de la farce.\nÉtape 6 Rouler avec soin en enfermant bien la farce.\nÉtape 7 Ficeler.\nÉtape 8 Faire dorer ces paquets dans la cocotte avec la margarine.\nÉtape 9 Peler les carottes et les oignons.\nÉtape 10 Ajouter les carottes et les oignons et mouiller avec de l''eau ou du vin blanc.\nÉtape 11 Cuire à feu doux pendant 1 h15"]' where recette_id = '9580846df14827435ca54855530f194b';
update fact_recette_base set etapes = '[''Préparation 2h10 Préparation : 10 min Repos : - Cuisson : 2 h'', "Étape 1 Dans un bol, mélangez huile d''olive, harissa, fleur de sel et poivre.\nÉtape 2 Badigeonnez la viande avec le mélange.\nÉtape 3 Mettez la viande dans un plat avec les herbes aromatiques. Couvrez d''une feuille d''aluminium et faites cuire 45 min dans un four préchauffé à 180°C (thermostat 6).\nÉtape 4 Au bout de 45 min ajoutez l''ail et l''échalote. Couvrez à nouveau, baissez la température à 150°C (thermostat 5), et faites cuire encore 45 min en arrosant de temps en temps avec son jus.\nÉtape 5 Au bout de 45 min, retirez la feuille d''aluminium et laissez dorer environ 30 min."]' where recette_id = 'f4a949c09b1741477aaf6e93a021f34b';
update fact_recette_base set etapes = '[''Préparation 2h15 Préparation : 15 min Repos : - Cuisson : 2 h'', "Étape 1 Faire revenir la viande dans un peu de beurre doux jusqu''à ce que les morceaux soient un peu dorés.\nÉtape 2 Saupoudrer de 2 cuillères de farine. Bien remuer.\nÉtape 3 Ajouter 2 ou 3 verres d''eau, les cubes de bouillon, le vin et remuer. Ajouter de l''eau si nécessaire pour couvrir.\nÉtape 4 Couper les carottes en rondelles et émincer les oignons puis les incorporer à la viande, ainsi que les champignons.\nÉtape 5 Laisser mijoter à feu très doux environ 1h30 à 2h00 en remuant.\nÉtape 6 Si nécessaire, ajouter de l''eau de temps en temps.\nÉtape 7 Dans un bol, bien mélanger la crème fraîche, le jaune d’oeuf et le jus de citron. Ajouter ce mélange au dernier moment, bien remuer et servir tout de suite."]' where recette_id = '5b9c4d777460d2ec2c5d28b3b6e953fc';
update fact_recette_base set etapes = '[''Préparation 2h15 Préparation : 15 min Repos : - Cuisson : 2 h'', "Étape 1 Faire fondre le beurre dans une cocotte, y faire revenir la viande.\nÉtape 2 Incorporer les oignons avec l''ail, le sel et le poivre.\nÉtape 3 Déglacer avec le vin blanc, gratter les sucs de cuisson puis rajouter le concentré de tomate.\nÉtape 4 Emietter les cubes de bouillon dans la cocotte et mouiller avec un peu d''eau.\nÉtape 5 Laisser cuire 1h15.\nÉtape 6 Rajouter les carottes pelées et coupées en rondelles et prolonger la cuisson 45 minutes."]' where recette_id = 'd3ebaebf6fe772e8ff6d2f8737b5fb2f';
update fact_recette_base set etapes = '[''Préparation 2h15 Préparation : 15 min Repos : - Cuisson : 2 h'', "Étape 1 Rincer la choucroute sous l’eau froide, l’égoutter, puis en verser la moitié dans un faitout.\nÉtape 2 Incorporer ensuite le lard fumé et la palette, puis les recouvrir du reste de choucroute.\nÉtape 3 Ajouter le saindoux, les gousses d''ail non pelées, le genièvre, le bouquet garni et l''oignon piqué.\nÉtape 4 Arroser le tout de vin blanc et laisser cuire à couvert à feu doux pendant 1 heure.\nÉtape 5 Ajouter les pommes de terre et poursuivre la cuisson pendant 50 minutes.\nÉtape 6 Incorporer les saucisses, poursuivre la cuisson encore 10 minutes puis servir."]' where recette_id = '3d297a900683427902ae4b71492c0274';
update fact_recette_base set etapes = '[''Préparation 2h15 Préparation : 15 min Repos : - Cuisson : 2 h'', "Étape 1 Dans une cocotte en fonte sur feu vif, placer les cuisses côté peau d''abord afin de récupérer la graisse (pas d''ajout de matières grasses nécessaire).\nÉtape 2 Les retourner afin de les colorer et ajouter l''ail en chemise écrasé sous la paume.\nÉtape 3 Ajouter thym, laurier, poivre, sel et un verre de vin blanc.\nÉtape 4 Enfourner la cocotte avec son couvercle dans le four préchauffé à 190°C.\nÉtape 5 Après 40 min ajouter les pommes de terre coupées en gros quartiers, les saler et laisser cuire encore 45 min.\nÉtape 6 Sortir du four, vérifier la cuisson, et placer les cuisses sur les pommes de terre côté peau vers le haut et passer 5 min sous le grill à puissance max.\nÉtape 7 Retourner les cuisses et faire dorer en surveillant."]' where recette_id = '44de9e78de760ed9050b42f1df0730ea';
update fact_recette_base set etapes = '[''Préparation 2h15 Préparation : 30 min Repos : - Cuisson : 1h45'', "Étape 1 Faire tremper la langue toute une nuit dans une cocotte remplie d''eau pour la dégorger.\nÉtape 2 Dans une cocotte minute, mettre la langue, couvrir d''eau, ajouter la moitié du vinaigre. Faire bouillir pendant 15 min. Egouter.\nÉtape 3 Pendant ce temps, faire bouillir de l''eau. Remettre la langue dans la cocotte, y verser l''eau bouillante, le reste du vinaigre, 1 oignon piqué de 3 clous de girofle, 2 bouillon cubes, le thym, le laurier, sel et poivre. Laisser cuire 1h30 à partir de l''ébullition.\nRetirer la langue de la cocotte et ôter la peau, garder le bouillon.\nÉtape 4 Sauce : faire fondre le beurre dans une grande casserole, ajouter un oignon émincé, faire fondre, ajouter la farine.\nÉtape 5 Puis ajouter petit à petit environ 1 l de bouillon de cuisson, 1 cuillère à café d''arôme Patrelle pour coloré la sauce. Goûter la sauce.\nÉtape 6 Ajouter sel et poivre si besoin, les cornichons coupés en rondelles.\nÉtape 7 Dans un plat de service, déposer la langue coupée en tranches et napper de sauce.\nÉtape 8 Bonne appétit."]' where recette_id = 'fc4798652f9a7f70bd611d396717affb';
update fact_recette_base set etapes = '[''Préparation 2h15 Préparation : 15 min Repos : - Cuisson : 2 h'', "Étape 1 Faire bouillir une casserole d''eau puis y faire cuire le chou coupé en morceaux durant environ 45 minutes à 1 heure.\nÉtape 2 Egoutter le chou dans une passoire.\nÉtape 3 Dans une cocotte mettre de l''huile d olive avec le thym et le laurier.\nÉtape 4 Une fois l''huile chaude, mettre les lardons et remuer régulièrement pour que ça ne colle pas.\nÉtape 5 Une fois les lardons presque cuits, mettre les chipolatas avec l''oignon et l''échalote émincés.\nÉtape 6 Remuer une fois les chipolatas presque cuites et mettre le lard gras que vous aurez couper en petit morceaux ainsi que le choux.\nÉtape 7 Saler un petit peu car les lardons, le lard gras et les chipolatas le sont déjà.\nÉtape 8 Remuer de temps en temps pendant que les chipolatas finissent de cuire et que le chou s''imprègne de saveur.\nÉtape 9 Servir bien chaud."]' where recette_id = 'db9019c53bea7df9ec4a2e52a901fa53';
update fact_recette_base set etapes = '[''Préparation 2h15 Préparation : 10 min Repos : - Cuisson : 2h05'', "Étape 1 Dans un poêlon, faites fondre l''huile d''olive avec le miel jusqu''à l''obtention d''un mélange homogène.\nÉtape 2 Disposez les souris d''agneau dans une cocotte allant au four, salez et poivrez-les selon votre goût. Enduisez-les du mélange huile d''olive-miel. Ajoutez les gousses d''ail non épluchées et le thym.\nÉtape 3 Couvrez la cocotte et enfournez-la pendant 2 bonnes heures à 170°C (150°C si four à chaleur tournante)\nÉtape 4 A partir d''une heure de cuisson, surveillez la cuisson de temps en temps afin d''ajouter ou non un peu de liquide : eau, vin ou bouillon (cela dépend de la matière du plat que vous utilisez). Bon appétit !"]' where recette_id = 'a5e8bacf1fab4a38dba2d3c55d75cc1a';
update fact_recette_base set etapes = '[''Préparation 2h20 Préparation : 20 min Repos : - Cuisson : 2 h'', "Étape 1 Couper l''échine de porc, l''épaule de mouton et le gîte de boeuf en cubes de 5 cm de côté. Les réfrigérer 24h dans un grand plat avec les ingrédients de la marinade.\nÉtape 2 Eplucher les pommes de terre et les carottes, les couper un très fines rondelles. Emincer les oignons. Egoutter les 3 viandes et réserver le jus de la marinade.\nÉtape 3 Dans la terrine beurrée, disposer successivement : 1 couche d''oignons, 1 couche de pommes de terre et carottes, les morceaux de viande, le pied de porc fendu en 2, 1 couche de pommes de terre et carottes, le poireau. Saler et poivrer à chaque couche.\nÉtape 4 Verser le jus de la marinade jusqu''au niveau des pommes de terre. Poser le couvercle et le souder avec un cordon de pâte fait avec la farine et 1 cuil. à soupe d''eau.\nÉtape 5 Cuire à four chaud (200°C/thermostat 6/7) environ 2h30."]' where recette_id = 'ecd39bc14cc63ae24d9ddacd4c60ae5b';
update fact_recette_base set etapes = '[''Préparation 2h20 Préparation : 20 min Repos : - Cuisson : 2 h'', "Étape 1 - pré-cuire le jarret 45mn à la cocotte minute, avec un fond d''eau et un peu de gros sel et de poivre.\nÉtape 2 - éplucher et émincer l''ail, l''oignon et les échalotes\nÉtape 3 - peler et laver les pommes de terre\nÉtape 4 - faire revenir à la poêle les lardons, les dégraisser à la passoire.\nÉtape 5 - dans la même poêle faire revenir : ail, oignons, échalotes, rajouter les lardons,le beurre et les pommes de terre coupées en deux, laisser mijoter à feux très doux en couvrant 10/15mn. Rectifier l''assaisonnement si nécessaire.\nÉtape 6 - sortir le jarret de la cocotte en fin de pré-cuisson, le passer au grill 15mn dans un plat avec 2cm d''eau (c''est facultatif mais ça permet de rendre la peau épaisse du jarret +croustillante et plus jolie).\nÉtape 7 - préparer une cocotte en fonte et y mettre la poêlée de légumes et la boite de champignons avec son jus.\nÉtape 8 - faire chauffer une tasse (25cl) d''eau et y mélanger le fond de veau. Verser dans la cocotte en fonte, sur les légumes.\nÉtape 9 - sortir le jarret du grill, le déposer dans la cocotte en fonte\nÉtape 10 - badigeonner le jarret avec le miel, ajouter une pincée de thym et de laurier, arroser avec la crème fraiche.\nÉtape 11 - couvrir et laisser mijoter à feux très doux dans la cocotte pendant 45mn.\nÉtape 12 (on peut démarrer à feux vif, pour que la cocotte prenne la chaleur et baisser ensuite le feu).\nÉtape 13 *** L''objectif est de faire cuire le jarret à feux très très doux pendant longtemps, ce qui donne une viande ultra tendre et parfumée des aromates qui composent le plat.\nÉtape 14 ---- bon appétit ! ----"]' where recette_id = '9afd0768505274be8502025da2460556';
update fact_recette_base set etapes = '[''Préparation 2h20 Préparation : 20 min Repos : - Cuisson : 2 h'', "Étape 1 Faire revenir l''agneau dans une sauteuse dans 2 cuillères d''huile d’olive, ajouter des épices couscous et un peu de sel.\nÉtape 2 Quand les morceaux sont dorés, ajouter l’ail écrasé et le concentré de tomates.\nÉtape 3 Retirer la viande et la réserver, faire dorer la farine dans le jus et ajouter le bouillon chaud en le fouettant.\nÉtape 4 Mettre la viande dans cette sauce, qui ne doit pas être trop liquide, en ajoutant le bouquet garni. Faire cuire à feu doux, au four ou dans une cocotte.\nÉtape 5 Au bout de 3/4 d’heure, couper les carottes et les navets en deux, les faire sauter avec les oignons dans 1 cuillère d’huile d’olive, avec des épices à couscous et du sel.\nÉtape 6 Quand ils sont dorés, les rajouter à la viande et prendre une louche de sauce de cuisson pour déglacer la sauteuse, remettre ce jus dans le plat de cuisson.\nÉtape 7 La sauce ne doit pas être trop liquide et doit juste couvrir les légumes et la viande. Cuire à feu doux pendant 1/2 heure.\nÉtape 8 Rajouter les pommes de terre coupées en deux si nécessaire, et vérifier l’assaisonnement.\nÉtape 9 Au bout de 3/4 d’heure, dégraisser la sauce et servir avec un hachis de persil frais."]' where recette_id = '5719133a190eb1925a50454f8d5e0d69';
update fact_recette_base set etapes = '[''Préparation 2h20 Préparation : 20 min Repos : - Cuisson : 2 h'', "Étape 1 Si nécessaire (certains bouchers fournissant la viande déjà déssalée), faire déssaler la viande (la tremper pendant 2 heures dans l''eau froide, en changeant l''eau de temps en temps). L''égoutter. La mettre dans un faitout, couvrir d''eau, poivrer. Faire cuire à petits bouillons pendant deux heures.\nÉtape 2 Éplucher les carottes et les oignons. Planter les clous de girofle dans les oignons.\nÉtape 3 Mettre carottes, oignons, bouquet garni et lentilles dans une cocotte minute, bien recouvrir d''eau, saler légèrement et poivrer. Faire cuire sous pression entre un quart d''heure et une vingtaine de minutes.\nÉtape 4 A la fin de la cuisson de la viande, la sortir du faitout, l''égoutter, et la découper en gros morceaux. Mettre ces morceaux, ainsi que les saucisses préalablement piquées à la fourchette, dans la cocotte-minute contenant déjà les lentilles. Rajouter 2 verres du bouillon du faitout (pour donner le goût de la viande).\nÉtape 5 Faire cuire (sans pression, avec la cocotte ouverte) pendant 20 à 30 minutes à petit feu, en faisant attention que les lentilles n''attachent pas."]' where recette_id = 'b4a117a19615d1ac50d566bdcac6ef20';
update fact_recette_base set etapes = '[''Préparation 2h25 Préparation : 5 min Repos : 2 h Cuisson : 20 min'', "Étape 1 Verser la farine dans un saladier. Au milieu, faire un puits et y casser les 2 oeufs. Fouettez le tout en ajoutant au fur et à mesure le lait ainsi que l''eau. Terminer en ajoutant le beurre fondu. Poivrer et saler (peu!)\nÉtape 2 Laisser reposer cette préparation 2h avant de l''utiliser\nÉtape 3 Faire chauffer une poêle à crêpe avec l''huile. Quand elle est bien chaude, y verser la pâte à crêpes.\nÉtape 4 Faire cuire le premier côté, et retourner la crêpe. Casser l''oeuf par dessus, poivrer et laisser légèrement blanchir, puis ajouter le fromage râpé ainsi que la tranche de jambon. Rabattre deux côtés et replier les deux autres.\nÉtape 5 Renouveler l''opération jusqu''à épuisement de la pâte.\nÉtape 6 C''est prêt, vous pouvez déguster cela accompagné d''une petite salade verte !"]' where recette_id = 'd3df079c001e13fcba601d3977590859';
update fact_recette_base set etapes = '[''Préparation 2h25 Préparation : 5 min Repos : - Cuisson : 2h20'', ''Étape 1 Dégraisser la viande.\nÉtape 2 Faire revenir la viande dans un mélange beurre-huile (pour ne pas que le beurre brûle). La sortir de la casserole avec le jus et conserver.\nÉtape 3 Faire revenir ensemble les lardons et les oignons.\nÉtape 4 Rajouter une cuillère à soupe de miel, puis remettre la viande. Ajouter la bière, saler (légèrement à cause des lardons), poivrer.\nÉtape 5 Mettre un couvercle et laisser mijoter 2h en surveillant.\nÉtape 6 Bon appétit !'']' where recette_id = '37b92be8e67ed758562bfe44fa3cd110';
update fact_recette_base set etapes = '[''Préparation 2h30 Préparation : 30 min Repos : - Cuisson : 2 h'', "Étape 1 La veille : mettez le coq à mariner : placez-le dans un grand saladier avec l''oignon et les carottes. Versez le vin, posez le bouquet garni et ajoutez les grains de poivres.\nÉtape 2 Couvrez et laissez mariner une nuit au réfrigérateur. (ou toute la journée si c''est pour le soir).\nÉtape 3 Le jour même : égouttez les morceaux de coq et les légumes, épongez-les bien avec du papier absorbant.\nÉtape 4 Filtrez la marinade et réservez.\nÉtape 5 Faites chauffez l''huile dans une cocotte, jetez-y les morceaux de coq et laissez-les bien dorer sur toutes les faces.\nÉtape 6 Retirez-les de la cocotte une fois dorés, mettez les légumes à la place. Laissez-les revenir à feu doux 5 minutes. Saupoudrez le tout de farine, remuez pour bien enrober les légumes.\nÉtape 7 Remettez les morceaux de coq dans la cocotte, ajoutez les gousses d''ail écrasées. Faites chauffer le cognac, versez-le et flambez.\nÉtape 8 Mouillez le tout avec le vin de la marinade, ajoutez le fond de veau, salez et poivrez. Portez à ébullition, puis couvrez et baissez le feu. Laissez mijoter 2 h 30 à feu doux.\nÉtape 9 Emincez les champignons. Faites-les dorer dans une poêle avec les lardons pendant environ 5-10 minutes. Rajoutez-les dans la cocotte 15 minutes avant de servir. Goûtez et rectifiez l''assaisonnement."]' where recette_id = '72c3f58c5b68bda28afce59862ebce7c';
update fact_recette_base set etapes = '[''Préparation 2h30 Préparation : 20 min Repos : - Cuisson : 2h10'', "Étape 1 Couper si necessaire les morceaux de joue de boeuf en carré de 4 cm sur 4 environ.\nÉtape 2 Éplucher les 2 oignons, et les carottes. \nÉmincer finement un oignon, les carottes et les champignons de Paris.\nPiquer le deuxième oignon de 2 clous de girofle.\nÉtape 3 Dans une cocotte minute, verser 2 cuillères à soupe d''huile d''olive et faire revenir l''oignon émincé avec une poignée de lardon.\nÉtape 4 Lorsque les oignons sont translucides, faire revenir les morceaux de joue de boeuf puis y ajouter 2 cuillère à soupe de maïzena ou de farine.\nBien mélanger le tout.\nÉtape 5 Ajouter le vin rouge jusqu''à hauteur de la viande puis ajouter l''oignon piqué des deux clous de girofle, l''ail écrasé, le bouquet garnis, le bouillon de cube, les carottes et les champignons émincés.\nÉtape 6 Refermer la cocotte et laisser cuire à feu doux pendant 2 heures. Plus le temps de cuisson sera long plus la viande sera tendre.\nÉtape 7 Pour l''accompagnement, 1h30 après, vous pouvez ajouter des pommes de terre à la cuisson."]' where recette_id = '29c6ae88c7c4d61c6b8ca40ba3e55f63';
update fact_recette_base set etapes = '[''Préparation 2h30 Préparation : 30 min Repos : - Cuisson : 2 h'', "Étape 1 Faire revenir environ 10 minutes les joues de porc dans un mélange huile + beurre, puis les mettre de côté.\nÉtape 2 Peler les pommes de terre et les couper en quartiers. Les sécher pour enlever l''excès d''amidon.\nÉtape 3 Peler en couper l''oigon (en morceaux relativement gros). Désosser le lard (conserver la couenne) et le couper en gros lardons.\nÉtape 4 Faire revenir à feu vif le lard et les oignons dans un mélange huile + beurre, ajouter ensuite les pommes de terre et laisser revenir environ 10 minutes.\nÉtape 5 Ajouter ensuite les joues de porc réservées. Assaisonner à votre goût (sel, poivre, herbes de provence). Arroser le tout avec le cidre.\nÉtape 6 Réduire le feu et laisser mijoter 1h30 à couvert en écumant de temps à autre.\nÉtape 7 Oter le couvercle et continuer à cuire au moins 30 minutes.\nÉtape 8 La sauce doit enrober les pommes de terre. Si la sauce n''est pas assez réduite et si on manque de temps, la prélever, la transférer dans une casserole et la faire réduire, puis en arroser la viande.\nÉtape 9 Servir chaud avec une salade verte."]' where recette_id = 'df60b1707ceb83967cf35099f98903d5';
update fact_recette_base set etapes = '[''Préparation 2h30 Préparation : 30 min Repos : - Cuisson : 2 h'', "Étape 1 Laver, éplucher tous les légumes, et les couper en morceaux assez gros.\nÉtape 2 Piquer l''oignon entier avec les clous de girofle.\nÉtape 3 Faire bouillir 3 litres d''eau, ajouter tous les légumes, puis le bouquet garni, l''ail, sel, poivre puis la viande.\nÉtape 4 Faire cuire le tout pendant environ 2 h 30-3 h, écumer de temps en temps.\nÉtape 5 1 h avant la fin, ajouter les os à moelle, et mettre du gros sel aux extremités pour conserver la moelle.\nÉtape 6 Egoutter les légumes et la viande, et servir bien chaud avec de la moutarde."]' where recette_id = 'd690e60b66b6dde75411f1f7378d3b08';
update fact_recette_base set etapes = '[''Préparation 2h30 Préparation : 30 min Repos : - Cuisson : 2 h'', "Étape 1 Pour cette recette, vous devez avoir une cocotte en fonte qui puisse passer directement au four et qui soit assez grande pour contenir le poulet entier.\nÉtape 2 Vérifier qu''il ne reste pas de petites plumes sur le poulet et enlevez-les si besoin.\nÉtape 3 Couper un des oignons en quatre et le glisser à l''intérieur du poulet avec quelques feuilles de laurier et quelques branches de thym.\nÉtape 4 Saler l''intérieur du poulet.\nÉtape 5 Saler et poivrer l''extérieur du poulet en massant légèrement pour bien fixer sur la peau.\nÉtape 6 Préchauffer le four à 200°C (thermostat 6-7).\nÉtape 7 Préparer le bouillon de volaille si vous le réalisez à partir d''un cube de bouillon déshydraté.\nÉtape 8 Dans la cocotte, sur feu doux, faire fondre le beurre avec un peu d''huile et faire colorer le poulet sur chacune de ses faces.\nÉtape 9 Lorsque le poulet est un peu coloré (pas besoin qu''il soit grillé), ajouter le deuxième oignon coupé en rondelles, encore quelques feuilles de laurier et quelques branches de thym, et les gousses d''ail en chemise juste écrasées avec la paume de la main.\nÉtape 10 Terminer enfin en ajoutant le bouillon de volaille.\nÉtape 11 Enfourner la cocotte fermée avec son couvercle dans le four chaud à environ 200°C.\nÉtape 12 Laisser cuire environ 2h en tournant le poulet au milieu de la cuisson.\nÉtape 13 Après cuisson, sortir le poulet de la cocotte pour le découper.\nÉtape 14 S''il en reste, faire réduire le reste de bouillon.\nÉtape 15 Déglacer le fond de la cocotte avec 1 verre d''eau pour réaliser le jus d''accompagnement."]' where recette_id = '97161968b2aae8af5ac6073c05203d32';
update fact_recette_base set etapes = '[''Préparation 2h30 Préparation : 30 min Repos : - Cuisson : 2 h'', "Étape 1 Faire blanchir les olives pendant 15 secondes, dans de l''eau portée à ébullition.\nÉtape 2 Les égoutter et les réserver.\nÉtape 3 Peler l''oignon (et l''émincer), la gousse d''ail (que l''on écrase).\nÉtape 4 Faire chauffer une cocotte, et y faire dorer les morceaux de veau et les lardons, sur feu doux.\nÉtape 5 Ajouter l''oignon et l''ail, et prolonger la cuisson de 2 ou 3 min.\nÉtape 6 Saupoudrer légèrement de farine, et mélanger pendant encore 2 ou 3 min.\nÉtape 7 Verser le vin blanc, l''anis (ou les graines de fenouil), et ajouter de l''eau, jusqu''à hauteur de la viande.\nÉtape 8 Incorporer 1 cuillère à soupe de concentré de tomate, le bouquet garni, saler et poivrer.\nÉtape 9 Laisser mijoter, en remuant délicatement de temps en temps, pendant 1h30.\nÉtape 10 Ajouter les olives, et prolonger la cuisson de 30 min."]' where recette_id = 'fc64fb476900d874e0a07a5c71239f43';
update fact_recette_base set etapes = '[''Préparation 2h35 Préparation : 30 min Repos : - Cuisson : 2h05'', "Étape 1 Préparer la viande et le poisson en les détaillant en lamelles, et en retirant les excédants de gras sur la viande. Réserver tous les déchets pour le bouillon.\nÉtape 2 Préparer les coquillages et crustacés, et réserver encore une fois tous les déchets pour le bouillon.\nÉtape 3 Préparation du bouillon.\nDans une grande casserole, porter un grand volume d''eau à ébullition avec tous les ingrédients et les déchets de viande et de poisson. \nLaisser mijoter 2h.\nÉtape 4 A la fin de la cuisson, filtrer et écumer le bouillon.\nÉtape 5 Préparation de la sauce pékinoise. \nMélanger énergiquement tous les ingrédients, goûter et rectifier l''assaisonnement si besoin.\nÉtape 6 Préparation de la sauce huître. Ciseler finement la ciboulette et mélanger intimement tous les ingrédients.\nÉtape 7 Préparation de la sauce cacahuètes. \nFaire griller les cacahuètes dans une poêle bien chaude, sans ajouter de matière grasse.\nÉtape 8 Mixer les cacahuètes puis mélanger avec le jus de citron et la sauce soja. Ajouter un peu d''eau si nécessaire.\nÉtape 9 Préparation de la sauce nuoc mam. \nMélanger tous les ingrédients jusqu''à dissolution complète des morceaux de sucre.\nÉtape 10 Préparation de la sauce au gingembre. \nMélanger les 2 vinaigres et le gingembre haché.\nÉtape 11 Maintenir le bouillon chaud durant tout le repas, c''est en trempant les morceaux de viande / poisson dedans qu''ils vont cuire. \nServir accompagné de toutes les sauces."]' where recette_id = 'bc67b74526e71d2b8df31959ef66c597';
update fact_recette_base set etapes = '[''Préparation 2h38 Préparation : 30 min Repos : - Cuisson : 2h08'', "Étape 1 Ôter les éventuelles plumes restant sur le chapon.\nHacher le persil, la gousse d''ail et l''échalote finement.\nÉtape 2 Pocher les épinards 8 min dans de l''eau bouillante salée, et bien les essorer sur du papier absorbant.\nÉtape 3 Tremper rapidement la mie de pain dans le lait et l''émietter grossièrement.\nÉtape 4 Hacher le foie du chapon, couper le foie gras en petits morceaux.\nÉtape 5 Mettre tous les ingrédients dans un grand saladier, y compris l’oeuf, saler et poivrer à votre convenance.\nBien mélanger, mais surtout ne pas utiliser de mixer, tout doit être haché grossièrement.\nÉtape 6 Préchauffer le four à 180°C (thermostat 6).\nFarcir le chapon et le coudre. Penser à trouver une âme charitable pour vous aider !\nÉtape 7 Huiler la bête avec un pinceau (ou amoureusement avec les mains); le déposer dans un plat en déposant sur le dessus de fines lamelles de beurre (pas trop, c''est déjà assez gras comme viande).\nÉtape 8 Couvrir avec de l''aluminium, et enfourner pour 1 heure de cuisson, en l''arrosant régulièrement et en remettant bien l''aluminium à chaque fois.\nÉtape 9 Au bout d''une heure, ôter l''aluminium, et faire dorer le chapon sous toutes les coutures en le retournant et l''arrosant tous les 1/4 pendant encore 1 h... Ça fait 2 heures en tout.\nÉtape 10 Vérifier que le chapon est bien cuit partout, et servir sans attendre accompagné de fagots de haricots verts et d''une cuillerée de farce par personne; et éventuellement de pommes duchesse pour faire joli."]' where recette_id = 'd203eac61852299bc7b1f54f2b5df515';
update fact_recette_base set etapes = '[''Préparation 2h40 Préparation : 10 min Repos : 2h10 Cuisson : 20 min'', ''Étape 1 Sortir la viande du réfrigérateur 2h à l’avance pour qu’elle revienne à température ambiante.\nÉtape 2 Préchauffer le four à 200°C (thermostat 6-7).\nÉtape 3 Enduire la côte de boeuf huile puis la saisir dans une cocotte ou une grande poêle 5 minutes de chaque côté. En la retournant, attention à ne pas la percer avec une fourchette.\nÉtape 4 Placer les brins de thym au fond d’un plat à four puis y déposer la côte de boeuf.\nÉtape 5 Enfourner pour 10 minutes de cuisson en retournant la pièce à mi-cuisson.\nÉtape 6 Retirer du four puis laisser reposer sur une planche recouverte un temps égal au temps de cuisson. Ce temps de repos est essentiel, il va permettre à la viande de se détendre et au jus de bien se répartir dans la viande.\nÉtape 7 Découper la viande en tranches d’environ 1 cm d’épaisseur. Saler et poivrer.'']' where recette_id = '047e6d6b68a9c9e91ddcd21ca301aced';
update fact_recette_base set etapes = '[''Préparation 2h40 Préparation : 40 min Repos : - Cuisson : 2 h'', "Étape 1 Nettoyer tous les légumes, les éplucher.\nÉtape 2 Mettre la poule dans une grande marmite et couvrir d''eau. Porter à ébulition et écumer.\nÉtape 3 Ajouter les légumes (plier les poireaux en deux), l''oignon piqué, les fines herbes, saler et poivrer.\nÉtape 4 Couvrir et laisser cuire 2 h à 2 h 30. La chair de la poule doit se détacher.\nÉtape 5 Servir d''abord le bouillon dégraissé, puis la viande entourée de légumes."]' where recette_id = '6bd84c4855a1f19da15bd99e42263810';
update fact_recette_base set etapes = '[''Préparation 2h50 Préparation : 20 min Repos : - Cuisson : 2h30'', "Étape 1 dégraisser le morceau de jarret, le couper en morceaux et les faire revenir dans la matière grasse.\nÉtape 2 une fois revenus, enlever-les de la cocotte et mettre l''oignon ciselé à la place (ne pas faire bruler!)\nÉtape 3 ajouter le bouillon de boeuf en cube et déglacer avec le vin\nÉtape 4 laisser l''alcool s''évaporer et réduire d''1/3 environ avant de remettre les morceaux de viande dans la cocotte avec l''oignon et la carotte coupée en fines lamelles\nÉtape 5 ajouter de l''eau si pas assez de liquide et laisser mijoter à feu doux pendant au moins 2h (la viande doit être fondante, enfin c''est mieux!)"]' where recette_id = '8d8fcecb066f2e926421c546900ef59d';
update fact_recette_base set etapes = '[''Préparation 2h50 Préparation : 35 min Repos : 2 h Cuisson : 15 min'', "Étape 1 Dans un saladier, placez les 300 g de farine, puis la levure, puis le bicarbonate de soude, la pincée de sel et celle de poivre. Ajoutez aussi le paprika et le sel d''ail selon votre goût. Mélangez à sec pour homogénéiser les ingrédients.\nÉtape 2 Versez ensuite la moitié des 20 cl d''eau, remuez avec votre doigt. Versez enfin le reste de l''eau puis remuez, lorsque la pâte est collante, utilisez votre main pour mélanger le tout, jusqu''à obtenir une pâte collante sans reste de farine.\nÉtape 3 Ajoutez alors un peu de farine à la main, mélangez et pétrissez. Recommencez l''opération (farine plus pétrissage) jusqu''à obtenir une boule de pâte que ne colle plus.\nÉtape 4 Mettez un peu de farine au fond de votre saladier et sur ses côtés, puis remettez la boule dedans, et couvrez avec un torchon propre.\nÉtape 5 Laissez reposer la pâte environ 2 heures (ou moins voire pas du tout si vous êtes pressés).\nÉtape 6 Préparation de la pizza.\nMettez votre four à préchauffer à 220°C.\nSur votre plan de travail, étalez un peu de farine afin que la boule de colle pas.\nÉtape 7 Saupoudrez votre boule d''un peu de farine et sortez là du saladier. Avec un rouleau à pâtisserie, faites-en un disque d''environ 35 cm de diamètre.\nÉtape 8 Posez la pâte ainsi formée sur votre plaque, avec en dessous du papier sulfurisé ou à défaut de la farine, pour que la pâte ne reste pas collée sur la plaque à la cuisson.\nÉtape 9 Étalez la sauce tomate sur la pâte, jusqu''à ne presque plus voir la pâte au travers (2 à 3 mm d''épaisseur de sauce).\nÉtape 10 Repartissez ensuite la viande sur la surface. Faites de même avec le fromage, jusqu''à couvrir correctement toute la surface. Enfin placez les olives. Saupoudrez d''une belle pincée d''herbes de Provence.\nÉtape 11 Enfournez au milieu du four pendant 8 min pour une pâte moelleuse, 10 à 12 min pour une pâte plus croustillante.\nÉtape 12 Sortez la pizza quand le fromage est bien fondu et commence à faire des bulles et à dorer. Découpez et servez."]' where recette_id = 'bab7bc0e7bfee27dc4d0ce64741086f2';
update fact_recette_base set etapes = '[''Préparation 2h55 Préparation : 20 min Repos : - Cuisson : 2h35'', "Étape 1 Préparation de la sauce tomate.\nEmincer les oignons et les faire blondir dans une petite casserole.\nÉtape 2 Ajouter les tomates coupées en gros dés et 2 bonnes cuillères à soupe d''huile d''olive, la cannelle, le miel, saler et poivrer. Laisser réduire le tout 25 minutes (ou plus, jusqu''à arriver à la préparation de la viande) à feu moyen.\n\nOn doit obtenir une sauce, que l''on peut homogénéiser avec du coulis de tomate tout prêt.\nÉtape 3 Préparation des aubergines. \nDécouper les aubergines en rondelles (sans les peler), saler généreusement, et les laisser dégorger le temps de l''étape suivante.\n\nConseil pour faire dégorger les aubergines : dans un plat, alterner une couche de tranches d''aubergine salées et une couche de papier absorbant ou les laisser dans une passoire.\nÉtape 4 Préparation des pommes de terre. \nEplucher et découper les pommes de terres en fines rondelles.\nÉtape 5 Disposer les rondelles de pommes de terre au fond d''un plat à gratin assez haut, huilé.\nArroser les pommes de terres d''un peu (3 cuillères à soupe) du jus rendu par les tomates qui mijotent.\nÉtape 6 Passer le plat de pommes de terre sous le grill 5 à 15 min selon votre four, pour qu''elles dorent.\nÉtape 7 Maintenant qu''elles ont dégorgé, passer les rondelles d''aubergine à la poêle à feu fort pour les faire griller un peu de chaque côté, réserver.\nÉtape 8 Préparation de la viande. \nDans un faitout, faire revenir la viande hachée au beurre à feu assez fort, saler, poivrer et retirer l''eau rendue par la viande.\nÉtape 9 Ajouter la sauce tomate-oignons et baisser le feu (très doux).\nÉtape 10 Sortir le plat de pommes de terres du four et le préchauffer le four à 200°C (thermostat 6-7).\nÉtape 11 Préparation de la béchamel. \nDans une petite casserole sur feu doux, faire blondir les 20 g de beurre, ajouter la farine et mélanger pour obtenir un appareil homogène.\nÉtape 12 Incorporer petit à petit le lait en n''arrêtant jamais de remuer, ça peut prendre 10 bonnes minutes, on doit obtenir une sauce assez épaisse.\nÉtape 13 Saler, poivrer et râper un peu de noix de muscade (c''est fort, il faut en mettre peu).\nÉtape 14 Montage de la moussaka.\nPar dessus la couche de pommes de terre, étaler la moitié de la viande hachée avec la tomate, puis la moitié des aubergines, puis l''autre moitié de viande, puis l''autre moitié des aubergines, un filet d''huile d''olive et terminer par la béchamel.\nÉtape 15 Enfourner le tout dans le four à 200°C (thermostat 6-7) et laisser cuire 1h (la béchamel doit croustiller et être dorée)."]' where recette_id = 'c9108fcf33bd95e4a3b688e99cc97283';
update fact_recette_base set etapes = '[''Préparation 3h15 Préparation : 15 min Repos : - Cuisson : 3 h'', ''Étape 1 Préchauffez le four ou le barbecue à 160°C (th. 5-6).\nÉtape 2 Préparez la sauce barbecue : mélangez tous les ingrédients.\nÉtape 3 Faites chauffer votre huile dans la cocotte et colorer la viande sur toutes ses faces.\nÉtape 4 Epluchez et émincez les oignons. Ajoutez-les à la cocotte. Mélangez.\nÉtape 5 Ajoutez de sauce barbecue, versez 2 verres d’eau et couvrez.\nÉtape 6 Enfournez pour 3 h de cuisson en retournant la viande à mi-cuisson.\nÉtape 7 Sortez la cocotte du four, effilochez la viande à l’aide d’une fourchette et mélangez-la bien à la sauce barbecue. Servez avec des frites maison ou des pommes de terre cuites au barbecue.'']' where recette_id = '393b9d2c16c794d064f1dcb78385280d';
update fact_recette_base set etapes = '[''Préparation 3h20 Préparation : 20 min Repos : - Cuisson : 3 h'', "Étape 1 Faire revenir la viande dans une marmite (ou un autocuiseur) avec un peu de matière grasse.\nÉtape 2 Pendant ce temps, éplucher les poireaux, carottes, navets et céleri et les couper en gros morceaux.\nÉtape 3 Verser d''un seul coup sur la viande 3 l d''eau, ajouter les légumes coupés, le bouquet garni, saler et poivrer.\nÉtape 4 Laisser cuire 3h à très petit feu (1h30 à l''autocuiseur).\nÉtape 5 Faire cuire séparément les pommes de terre. 30 min avant la fin de cuisson du pot au feu, ajouter l''os à moelle et  les pommes de terre.\nÉtape 6 Servir chaud avec des cornichons et de la moutarde."]' where recette_id = '50174d5fddbb46a48cd9092a5487ab55';
update fact_recette_base set etapes = '[''Préparation 3h40 Préparation : 30 min Repos : - Cuisson : 3h10'', "Étape 1 Couper la viande en cubes de 2 à 3 centimètres de côté. \nDécouper grossièrement les oignons et couper le lard en gros lardons.\nÉtape 2 Faire fondre le beurre et faire suer les oignons dedans 10 minutes pour les ramollir (feu au mini à couvert).\nÉtape 3 Ajouter le lard en augmentant légèrement le feu, remuer régulièrement en essayant de garder couvert le plus possible.\nÉtape 4 Une fois le lard bien rose, retirer le tout (sauf le jus) et le réserver dans un plat.\nÉtape 5 Mettre le feu au maxi et mettre la viande dans la cocotte. Remuer régulièrement (ne pas couvrir), la viande doit se colorer de tous les côtés, elle va finir par rendre pas mal de jus.\nRetirer la cocotte du feu, mettre la viande dans un plat en conservant le jus dans la cocotte.\nÉtape 6 Diluer la cassonade dans le jus de viande et mettre sur le feu à fond pour le réduire de moitié.\nÉtape 7 Une fois réduit, mettre le feu au mini et remettre le mélange lard-oignons en le mêlant au ''sirop'', ajouter la viande et re-mélanger, ajouter le bouquet garni et recouvrir de bière entre (80 cl et 1 litre), saler très légèrement.\nÉtape 8 Recouvrir délicatement toute la surface avec le pain d''épices ''moutardé''. \nLaisser mijoter à couvert 3 heures sans remuer, tant que le pain d''épices n''est pas fondu (retirer le bouquet après 1 heure ou 2 maxi).\nÉtape 9 En cours de ''mijotage'', rectifier l''assaisonnement si besoin.\nÉtape 10 Si après trois heures, le jus est encore trop liquide, laisser encore mijoter en laissant le couvercle en partie ouvert, la sauce doit être légèrement collante en surface mais bien liquide en dessous et ne doit surtout pas brûler au fond."]' where recette_id = 'a70e6b316dfc19d09a8cb4c520db1086';
update fact_recette_base set etapes = '[''Préparation 4 h Préparation : 2 h Repos : - Cuisson : 2 h'', "Étape 1 Préparer les légumes :\nÉtape 2 Peler, épépiner et concasser les tomates. Hacher les oignons, écraser l''ail. Emincer les blancs de poireaux.\nÉtape 3 Mettre tous ces légumes dans une grande marmite.\nÉtape 4 Vider les poissons, réserver les foies que l''on hachera.\nÉtape 5 Couper les têtes et les queues, couper les pattes des cigales de mer.\nÉtape 6 Ajouter les déchets des poissons (têtes et queues) et les cigales dans la marmite, ajouter 25 cl d''huile d''olive.\nÉtape 7 Mettre également le fenouil, le laurier, le persil, les poivre en grains et la peau d''orange séchée.\nÉtape 8 Couvrir et faire cuire 15 min à feu moyen en remuant de temps en temps.\nÉtape 9 Faire bouillir 5 l d''eau à part.\nÉtape 10 Mettre la marmite de légumes à vif et y verser l''eau bouillante. Saler, porter à ébullition et baisser le feu.\nÉtape 11 Laisser mijoter 20 min.\nÉtape 12 Au bout de ce temps, écumer passer la soupe au chinois en écrasant bien les légumes et morceaux de poisson.\nÉtape 13 Rajouter le safran.\nÉtape 14 Couper les poissons en tronçons égaux, ou couper les plus gros en 2 ou 3.\nÉtape 15 Les faire cuire successivement dans la préparation précédente portée à ébullition sur feu vif :\nÉtape 16 Le congre cuit environ 10 min, le Saint-pierre 6 min, la lotte 4 min, la rascasse 4 min, le grondin 3 min et la vive 3 min.\nÉtape 17 Les poissons ne doivent pas être complètement cuits, mais juste à point. Les sortir du bouillon et réserver dès qu''ils sont cuits.\nÉtape 18 Préparer la rouille :\nÉtape 19 Faire tremper le pain dans le lait.\nÉtape 20 Eplucher, dégermer et piler l''ail avec les piments rouges épépinés. Rajouter la mie de pain trempée et essorée puis l''huile, sans cesser de piler. Saler, poivrer et délayer avec 1 cuillère à soupe de bouillon.\nÉtape 21 Pour servir la bouillabaisse : lier le bouillon avec les foies hachés des poissons en fouettant bien.\nÉtape 22 Servir le bouillon lié dans les assiettes, et répartir les morceaux de poissons.\nÉtape 23 Accompagner de tranches de pain de campagne frottées à l''ail et à l''huile et grillées, et de la rouille."]' where recette_id = 'b62493a360cba7921d5d4b86eddbde3f';
update fact_recette_base set etapes = '[''Préparation 4 h Préparation : 1 h Repos : - Cuisson : 3 h'', ''Étape 1 Mettre la mojette à tremper la veille dans l’eau froide.\nÉtape 2 Égoutter la mojette, la mettre à cuire dans une cocotte, recouverte d’eau froide, non salée, avec 5 ou 6 gousses d’ail, du thym et du laurier, pendant une bonne 1/2 heure, 3/4 d’heure, à partir de l’ébullition.\nÉtape 3 Égoutter la mojette, puis la mettre dans une grande cocotte, recouvrir d’eau. Ajouter le concentré de tomate, les rondelles de saucisson, la poitrine fumée coupée préalablement en morceaux, quelques gousses d’ail, (on aura ôté les anciennes), du thym, du laurier, remettre a mijoter.\nÉtape 4 Dans une poêle, faire griller la poitrine fraîche coupée en morceaux , ensuite les saucisses, et rajouter tout ceci dans la cocotte, en ayant pris soin d’essuyer le surplus de graisse avec un sopalin. Saler, poivrer, et remettre a mijoter une heure a feu très doux (thermostat 3 maximum sur la plaque mijotron), en remuant de temps en temps.\nÉtape 5 Sortir les cuisses de canard des boîtes, bien les nettoyer de toute la graisse, et séparer les haut et les bas de cuisses.\nÉtape 6 Ajouter dans la cocotte, vérifier l’assaisonnement, et laisser encore mijoter 1/2 heure. Mettre le four à préchauffer, chaleur tournante (on mettra deux plats sur deux niveau), à 110°C (thermostat 3 ou 4).\nÉtape 7 Prendre deux grands plat à gratin en terre cuite à bord assez haut, les frotter avec de l’ail, puis, délicatement, répartir le contenu de la cocotte dans les deux plats (attention au confit qui se détachent très facilement). Il faut que la sauce recouvre juste a niveau les haricots. saupoudrer alors de chapelure, et mettre au four.\nVérifier régulièrement que la préparation cuit tout doucement, et qu’il y a suffisamment de sauce, il faut toujours que le jus soit au niveau des haricots. De temps en temps, appuyer sur les morceaux de viande ou de saucisse pour les remettre un peu dans la sauce.\nÉtape 8 On peut laisser mijoter encore 1/2 heure, deux heures, ou mieux laisser refroidir au bout d’une heure et remettre à cuire encore une heure ( par exemple si on prépare la veille) \nC’est encore meilleur réchauffé.'']' where recette_id = '90747bc6256e7c37ccf99fdfbe340490';
update fact_recette_base set etapes = '[''Préparation 4h45 Préparation : 40 min Repos : 5 min Cuisson : 4 h'', "Étape 1 LA VEILLE : Pour la sauce, peler et émincer finement les carottes, la branche de céleri, les oignons, les échalotes et les gousses d''ail. Réserver.\nÉtape 2 Mettre le persil grossièrement ciselé, le bouquet garni, les clous de girofle et une cuillère à café de poivre écrasé dans une grande casserole à fond épais.\nÉtape 3 Ajouter les 2 bouteilles de vin rouge, les 3/4 de celle de blanc et 10 cl de vinaigre.\nÉtape 4 Porter à ébullition puis baisser le feu et laisser mijoter 30 minutes environ.\nÉtape 5 Pendant ce temps, faire revenir les carottes, oignons, échalotes, ail et céleri dans une poêle avec 2 cuillères à soupe d''huile, en remuant sans arrêt jusqu''à ce que le mélange soit doré.\nÉtape 6 Ajouter cette préparation dans le vin et faire réduire, sur feu vif, jusqu''à ce qu''il ne reste que 1,5 litre.\nÉtape 7 Passer en écrasant les légumes avec une spatule et remettre dans la casserole nettoyée.\nÉtape 8 Ajouter le bouillon de boeuf, 1 cuillère à café de poivre écrasé, le vin blanc restant.\nÉtape 9 Faire à nouveau réduire pendant 1h30 à petits bouillons jusqu''à ce qu’il reste environ 70 cl de liquide.\nÉtape 10 Passer la sauce au chinois.\nÉtape 11 Faire fondre 30 g de beurre dans une grande casserole, ajouter 30 g de farine et cuire 2 à 3 min sans cesser de tourner.\nÉtape 12 Ajouter la sauce réduite, progressivement en tournant avec un fouet, et monter à petite ébullition 10 min. Réserver cette sauce jusqu’au lendemain.\nÉtape 13 Pour le cuissot : étant paré et ficelé, le poser dans le lèche-frite du four ou dans un grand plat à rôtir et le badigeonner d''eau de vie.\nÉtape 14 Etaler de l’huile, du thym, romarin, poivre, muscade, sur toutes les faces du cuissot.\nÉtape 15 Faire cuire 30 minutes à 200°C (thermostat 6-7), chaleur tournante, puis 45 minutes à 180°C. Tout au long de la cuisson, arroser plusieurs fois avec du vin blanc et le jus de cuisson. N''hésitez pas à piquer la viande pour vérifier la cuisson, le jus doit être perlé rosé.\nÉtape 16 Filtrer et verser le jus de cuisson dans la sauce précédente. Sortir le cuissot du four, le saler et le laisser refroidir puis l’envelopper dans du film alimentaire et mettre au réfrigérateur jusqu’au lendemain.\nÉtape 17 LE JOUR MEME : Découper le cuissot bien froid en tranches comme un gigot d''agneau.\nÉtape 18 20 min avant de servir, faire chauffer le plat de service vide au four à 200°C (thermostat 6-7) et faire réchauffer la sauce dans la casserole, en lui incorporant un peu crème pour l''adoucir. Rectifier l’assaisonnement.\nÉtape 19 Ranger les tranches de viande dans le plat de service bien chaud.\nÉtape 20 Napper de la sauce chaude et passer au four 8 à 10 min. Bon appétit !"]' where recette_id = '03e0af67de3284282dc9cc9a10a9b656';
update fact_recette_base set etapes = '[''Préparation 5 h Préparation : 1 h Repos : - Cuisson : 4 h'', "Étape 1 Détailler la viande en cubes de 3 cm de côté, enlever les gros morceaux de gras.\nÉtape 2 Couper l''oignon en morceaux. Le faire revenir dans une poêle au beurre. Une fois transparent, le verser dans une cocotte en fonte de préférence.\nÉtape 3 Procéder de même avec la viande mais en plusieurs fois, jusqu''à ce que tous les morceaux soient cuits. Les ajouter au fur et à mesure dans la cocotte. Ne pas avoir peur d''ajouter du beurre entre chaque fournée.\nÉtape 4 Quand toute la viande est dans la cocotte, déglacer la poêle avec de l''eau ou du vin et faire bouillir en raclant pour récupérer le suc. Saler, poivrer, ajouter au reste.\nÉtape 5 Recouvrir le tout avec une partie du vin et faire mijoter quelques heures avec le bouquet garni et les carottes en rondelles.\nÉtape 6 Le lendemain, faire mijoter au moins 2 heures en plusieurs fois, ajouter du vin ou de l''eau si nécessaire."]' where recette_id = '58179e1a4e7a723e89f2fd81a17abfa5';
update fact_recette_base set etapes = '[''Préparation 5 h Préparation : 3 h Repos : - Cuisson : 2 h'', ''Étape 1 Semoule :\nÉtape 2 Dans un grand plat creux, versez la semoule. Ajoutez une bonne pincée de sel, un peu d\''huile végétale.\nÉtape 3 A l\''aide de vos mains, mélangez la semoule de façon à ce que l\''huile soit bien répartie sur les grains. (évite les paquets)\nÉtape 4 Versez un peu d\''eau en pluie, mélangez et laissez gonfler.\nÉtape 5 Légumes et viande :\nÉtape 6 Pendant ce temps, dans une cocotte, versez l\''huile végétale de manière à ce que le fond soit recouvert. Ajoutez les morceaux de viande, une pincée de sel, poivre et une cuillère à café de gingembre.\nÉtape 7 Coupez les oignons en lamelles puis versez-les sur la viande.\nÉtape 8 Epluchez les tomates uis coupez-les en petits cubes, versez dans la cocotte. Hachez une petite poignée de coriandre, ajoutez à la cocotte.\nÉtape 9 Laissez les tomates rendre leurs jus au moins 5 à 10 minutes. Puis ajoutez les pois chiches (s\''il sont trempés de la veille si en boîte, ajoutez-les plus loin dans la rectte) et de l\''eau jusqu\''à recouvrir la viande au 3/4. Fermez la cocotte.\nÉtape 10 Vérifiez régulièrement, ajoutez de l\''eau au besoin.\nÉtape 11 Selon les viandes (vieilles ou non) la cuisson peut être longue, allant parfois jusqu\''à plus d\''une heure ! Notez qu\''il faut que la viande puisse se détacher avec du bout des doigts.\nÉtape 12 Pendant ce temps, épluchez carottes, navets, courgettes (en laissant une bande sur deux), enlevez les graines de la courge, laissez la moitié de vos fèves entière, ne gardez que les grains de l\''autre moitié. Selon la taille de vos légumes, coupez-les de façon à obtenir des morceaux assez gros pour éviter "la purée ". Enlevez bien le coeur des carottes.\nÉtape 13 Laissez-les tremper dans l\''eau avec un peu de vinaigre (pour bien les laver !)\nÉtape 14 Semoule :\nÉtape 15 Votre semoule doit être ferme à présent.\nÉtape 16 A l\''aide de vos deux mains l\''une contre l\''autre, frottez la semoule afin de séparez les grains.\nÉtape 17 Ajoutez encore un peu d\''eau, mélangez et laissez reposer.\nÉtape 18 Mettre l\''eau au fond de la couscoussière, puis une fois la semoule gonflée répétez l\''opération de séparation des grains. Faites cuire à la vapeur jusqu\''à ce que cette dernière ait traversée complètement la semoule.\nÉtape 19 Puis versez de nouveau dans le plat.\nÉtape 20 Mélangez à l\''aide d\''une grosse cuillère puis ajoutez une fois de plus un peu d\''eau. Répétez la cuisson deux fois en ajoutant toujours de l\''eau.\nÉtape 21 Avant la dernière fois, ajoutez du beurre en petits morceaux.\nÉtape 22 Puis faites cuire à la vapeur une troisième et dernière fois.\nÉtape 23 Une fois votre viande cuite, ajoutez les carottes et navets.\nÉtape 24 Laissez cuire suivant les légumes 10 à 15 minutes. Notez qu\''il faut que les carottes et navets soit mi-cuit c\''est-à-dire légèrement ferme car ils vont encore subir de la cuisson. Toujours pour éviter la "purée "!\nÉtape 25 Une fois pré-cuits, ajoutez les fèves. Laissez bien cuire les fèves jusqu\''à ce que la peau des grainnes soient "flétrie". Les fèves sont longues à cuire et tiennent bien la cuisson.\nÉtape 26 Ajoutez maintenant la courge en morceaux.\nÉtape 27 Ajoutez ensuite un bouquet de coriandre que vous aurez ficelez à l\''aide de fil alimentaire ou simplement de couture !\nÉtape 28 Ajoutez enfin le chou coupé en deux ou 4 (suivant le chou) puis 5 minutes après les courgettes.\nÉtape 29 Une fois les courgettes cuites et le chou tendre, arrêtez la cocotte.\nÉtape 30 Pour servir :\nÉtape 31 Dans un grand plat, mettez la semoule en puits.\nÉtape 32 Moi, je sort une grande assiette me permettant de déposer temporairement les légumes pour atteindre la viande que l\''on mettra au centre du puit.\nÉtape 33 Ajoutez les légumes autour de la viande (comme on mets les biscuits d\''une charlotte au chocolat !).\nÉtape 34 Puis les graines de fèves, pois chiches et sauces par dessus.\nÉtape 35 Mettez à disposition la sauce dans un bol.\nÉtape 36 Notez que certains aiment boire du lait fermenté appelé \''lben.\nÉtape 37 Bon appétit !'']' where recette_id = '1bea011483f5c4d5596793f757a39227';
update fact_recette_base set etapes = '[''Préparation 5h20 Préparation : 20 min Repos : - Cuisson : 5 h'', "Étape 1 Dans un faitout plein d''eau froide, mettre 2 cuillères à soupe de vinaigre, 1 poignée de gros sel et les pieds ; faire bouillir 15 mn en écumant soigneusement puis rincer à l''eau froide.\nÉtape 2 Dans une grande cocotte disposer les carottes en rondelles, les oignons épluchés, l''ail écrasé, le laurier, le thym, les clous de girofle, les pieds, du sel et du poivre.\nÉtape 3 Recouvrir du vin blanc dans lequel aura été délayé le cube de bouillon et laisser mijoter à feu doux pendant 4h30 en remuant de temps en temps.\nÉtape 4 Lier la sauce avec la Maïzena délayée dans un peu d''eau froide et remettre à mijoter 1/2 heure.\nÉtape 5 Laisser refroidir dans la cocotte.\nÉtape 6 Réchauffer le lendemain après avoir dégraissé la surface. Servir, saupoudré de persil, avec une purée pomme de terre/céleri ou des pâtes."]' where recette_id = 'cbfebd451af9c8d517e0c8d7d02132ab';
update fact_recette_base set etapes = '[''Préparation 6 h Préparation : 1 h Repos : - Cuisson : 5 h'', ''Étape 1 Préparer votre viande :\nÉtape 2 Écraser votre ail dans le pilon avec les épices et mélanger au concentré de tomates. Badigeonner votre viande en couche épaisse de cette mixture et laisser reposer. Vous pouvez faire ceci la veille de votre mloukhia ce sera encore meilleur !\nÉtape 3 Faites revenir votre oignon avec l’huile d’olive jusqu’à ce qu’il soit translucide. Verser votre poudre de mloukhia et mélanger.\nÉtape 4 Quand la pâte devient un peu compact (ne pas attendre qu’elle fasse des grumeaux).\nÉtape 5 Verser une louche d’eau chaude, remuer, reverser une autre louche, remuer et ce jusqu’à l’obtention d’une sauce pas trop liquide mais surtout pas crémeuse non plus, consistance d’une soupe légère : la sauce épaissira lors de la cuisson.\nÉtape 6 Ajouter vos morceaux de viandes et le reste de la mixture.\nÉtape 7 Mettez vos feuilles de laurier. (Certains mettent de la coriandre, évidemment le goût est un peu différent !)\nÉtape 8 Saler, poivrer, vous pouvez aussi ajouter un piment vert selon le goût désiré.\nÉtape 9 Couvrir et laisser cuire 5 h minimum à feu doux en remuant de temps à autre et ajouter un peu d’eau si vous trouver la préparation trop épaisse au début.\nÉtape 10 Quand la cuisson est terminée vous devez voir l’huile remonter à la surface et la texture crémeuse.\nÉtape 11 Si votre plat est trop piquant, ne pas hésiter pas à ajouter quelques pommes de terre pour absorber le piquant.'']' where recette_id = 'bc6140fd7490136b5cd2301be7c32f2c';
update fact_recette_base set etapes = '[''Préparation 6h45 Préparation : 45 min Repos : - Cuisson : 6 h'', "Étape 1 Faire tremper les haricots la veille\nÉtape 2 Blanchir les feuilles de chou. Il sera plus digeste.\nÉtape 3 Remplir une marmite avec environ 3.5 l d''eau et y déposer la viande.\nÉtape 4 Quand l''eau de la marmite bout, ajouter les légumes coupés en morceaux (sauf le chou et les pommes de terre) ainsi que l''ail et l''oignon piqué de clous de girofle.\nÉtape 5 Couvrir et laisser bouillir à feu doux.\nÉtape 6 Lorsque les haricots sont suffisamment tendres, ajouter les pommes de terre coupées en dés et le chou en fines lanières. Poivrer et laisser bouillir à gros bouillon pendant 30 min.\nÉtape 7 Lorsque la garbure est cuite, retirer l''oignon, la tête d''ail.\nÉtape 8 Déchiqueter la viande dans la marmite afin qu''elle se mélange bien avec les légumes, au moment de servir.\nÉtape 9 Plus elle mijote et meilleure elle est."]' where recette_id = '53dd9fd99f943015a009a48bab796c34';
update fact_recette_base set etapes = '[''Préparation 7h07 Préparation : 2h17 Repos : - Cuisson : 4h50'', ''Étape 1 (Dessaler la viande 5h si salée, 2h si demi sel.)\nÉtape 2 Retirer quelques feuilles autour du choux et retirer le trognon du dessous.\nÉtape 3 Couper le chou en 4, retirer le blanc au milieu et laver.\nÉtape 4 Éplucher les carottes et les navets.\nÉtape 5 Blanchir le choux : le plonger dans une grande cocotte et recouvrir d’eau. Porter à ébullition et après 2 min à grosses bulles sortir, égoutter et passer sous l’eau froide pour arrêter la cuisson.\nÉtape 6 Piquer l’oignon avec les 20 clous de girofle.\nÉtape 7 Dans une cocotte, mettre la viande dans l’eau froide (sauf la saucisse) et ajouter l’oignon piqué. Ne pas saler. Porter à ébullition à feu fort puis enlever toute l’écume au dessus.\nÉtape 8 Une fois tout écumé, baisser le feu pour atteindre une petite ébullition, ajouter le bouquet garni et le poivre 5 baies, laisser cuire doucement pendant 1h30.\nÉtape 9 Couper maintenant le chou en lanières et les carottes en bâtonnet.\nÉtape 10 Prendre une autre cocotte, mettre de l’huile au fond, et mettre à feu fort les carottes pendant 5 min puis mettre le choux. Faire chauffer encore 10 minutes à feu doux, en remuant bien.\nÉtape 11 Ajouter les navets et la graisse de canard, laisser cuire doucement encore 30 minutes.\nÉtape 12 Ajouter, la saucisse de Morteau par-dessus et laisser chauffer de nouveau pendant 1h15.\nÉtape 13 Ajouter les pommes de terre épluchées et coupées en rondelles. Faire cuire encore 30 minutes en remuant de temps en temps.\nÉtape 14 Quand elle est cuite, on ajoute la viande dans la cocotte qui contient les légumes et on laisse le tout à feu réduit encore une demi-heure.\nÉtape 15 Bon appétit !'']' where recette_id = 'e78ed56d31d3db09aab1b9bb7b423f58';
update fact_recette_base set etapes = '[''Préparation 8h30 Préparation : 30 min Repos : - Cuisson : 8 h'', "Étape 1 Mettre les pieds et les paquets dans une cocotte ou une marmite, les laisser rendre leur jus à feu doux.\nÉtape 2 Une fois le jus rendu, rajouté la purée de tomate et continuer la cuisson a feu doux pendant environ 20 minutes.\nÉtape 3 Au bout de 20 minutes, ajouter le vin blanc. Saler, poivrer et ajouter un petit bouquet de thym.\nÉtape 4 Laisser mijoter à feu doux pendant 6h. Surveiller de temps en temps et remuer pour ne pas que ça accroche. Ajouter un peu d''eau si la sauce réduit trop.\nÉtape 5 Au bout de 6h, ajouter le cognac. Laisser mijoter à feu doux encore au moins 2h. Bien sûr, l''idéal serait de laisser mijoter toute la journée et de servir ce plat le lendemain, accompagné de pommes de terre cuites à la vapeur.\nÉtape 6 Cette recette est très simple, mais la cuisson est longue. Je n''ai jamais trouvé cette recette telle que je la présente sur aucun livre de cuisine... Mais il faut savoir que je la tient de ma grand-mère(elle faisait elle-même les paquets) qui la tenait de sa grand-mère et nous sommes de pure souche provençale. Donc je pense bien que ma recette est la vraie!\nÉtape 7 Pour l''améliorer encore un peu, finissez la cuisson au feu de bois!"]' where recette_id = '68c8cdd8d69a12c8b628991d5900557c';

commit;
